window.__TRANSKY_ATLAS_DATA__=window.__TRANSKY_ATLAS_DATA__||[];window.__TRANSKY_ATLAS_DATA__.push("ume\":3,\"start\":1255,\"end\":1257,\"summary\":\"天语遥借射气球释放压抑情绪，花五十元清空靶面，赢得MP3并难得获得母亲赞赏。母女在中心大厅买软陶材料、工具、书及教学碟，让她可在家自学。逛花鸟市场时，她想起从前投喂并随她行动的大黑狼犬，担心旧部是否继续照顾；停在兔笼前出神，母亲再次询问要不要买。\",\"turn\":\"陶艺计划获得现实资源；旧日温柔面与动物牵挂被揭示，宠物购买尚待决定。\",\"time\":\"母女雨天出游\",\"people\":[\"天语遥\",\"天语遥母亲\",\"游艺摊老板\",\"大黑狼犬\",\"宠物店老板\"],\"objects\":[\"MP3\",\"软陶材料工具\",\"教学书和DVD\",\"兔子\"],\"places\":[\"游乐园\",\"中心大厅工艺品店\",\"花鸟市场\"]},{\"key\":\"c322\",\"id\":322,\"title\":\"天语遥和女装\",\"kind\":\"main\",\"volume\":3,\"start\":1258,\"end\":1260,\"summary\":\"母亲替天语遥买下黑白兔，二人按方格饼干般毛色给它取名饼干，又买盆栽。逛服装层时天自觉昔日七彩造型幼稚，对店主称自己为女儿感受复杂；母亲买齐四季女装邀她试穿。天口头拒绝却觉内心动摇，原文将身体变化与心理联系只是角色困惑，不能当作必然规律。\",\"turn\":\"新宠物落定姓名，服装使身份与自主选择矛盾进一步具体化。\",\"time\":\"母女出游当日\",\"people\":[\"天语遥\",\"天语遥母亲\",\"饼干\",\"服装店主\"],\"objects\":[\"兔笼\",\"盆栽\",\"四季女装\"],\"places\":[\"游乐园花鸟市场\",\"游乐园服装层\"]},{\"key\":\"c323\",\"id\":323,\"title\":\"软陶骰子\",\"kind\":\"main\",\"volume\":3,\"start\":1261,\"end\":1263,\"summary\":\"母亲反思只要孩子健康快乐便好，回家后天语遥为饼干挡风，独处时终于说出喜欢可爱的情绪。她耐心学习软陶，花下午做出精整黑白骰子，继而尝试印章等小作品，把书架清空作为展示处。父亲疲倦晚归为缺席出游道歉，天虽心疼仍赌气，陶艺上的成就先于亲子和解到来。\",\"turn\":\"陶艺建立耐心与成就感，关心父亲的情绪尚难直接表达。\",\"time\":\"出游当日下午至夜晚\",\"people\":[\"天语遥\",\"天语遥父母\",\"饼干\"],\"objects\":[\"软陶骰子\",\"印章作品\",\"书架\",\"牛奶\"],\"places\":[\"天语遥家\"]},{\"key\":\"c324\",\"id\":324,\"title\":\"调皮的母亲大人\",\"kind\":\"main\",\"volume\":3,\"start\":1264,\"end\":1267,\"summary\":\"天语遥专注制作后早早疲倦，母亲照常给她助眠药。她梦见软陶能化为真实事物，并恢复失去的身体，梦最终转为惊惧。母亲夜里未经她同意趁熟睡替她换上女装，期待她适应；次晨天照镜发现，愤怒又无奈地质问，母亲装无辜打趣。情节虽以玩笑描写，仍存在身体与选择边界被越过。\",\"turn\":\"恢复身体只是梦；现实换装未经同意，母女相处仍含关爱与控制。\",\"time\":\"软陶学习当夜至次晨\",\"people\":[\"天语遥\",\"天语遥母亲\",\"天语遥父亲\"],\"objects\":[\"助眠药\",\"女装\",\"栗色发卡\",\"落地镜\",\"软陶（梦中）\"],\"places\":[\"天语遥卧室\"]},{\"key\":\"c325\",\"id\":325,\"title\":\"方莜莜的家事\",\"kind\":\"main\",\"volume\":3,\"start\":1268,\"end\":1271,\"summary\":\"连绵秋雨中苏雨晴逗朱雀，与合租伙伴谈中秋回家。张与林均未向家里坦白，苏仍自认无家可归，只有胡计划回村。方莜莜透露幼年父母离婚且生母不要自己，父亲另娶后又与继母疏离，近来赴大城市工作；她以无人管束换自由自我安慰。旁边林默画令人不安的纷乱色线。\",\"turn\":\"不同原生家庭状况使合租屋成为替代归属；方的温柔背后显露被舍弃经验。\",\"time\":\"中秋前的雨天休息日\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"林夕晨\",\"方莜莜父母和继母\",\"曲奇\",\"咖啡\",\"朱雀\"],\"objects\":[\"月饼（谈及）\",\"猫粮\",\"林夕晨抽象画\"],\"places\":[\"合租屋\"]},{\"key\":\"c326\",\"id\":326,\"title\":\"方莜莜的地址\",\"kind\":\"main\",\"volume\":3,\"start\":1272,\"end\":1275,\"summary\":\"林夕晨画完抽象人形后如释重负，把画揉团丢弃，这与她珍存普通作品形成区别。苏替懒散张做饭，胡因恋爱短信羞涩防备。方与安念在游戏中因劫掠行为遭多公会追杀，下线后继续亲近聊天；安借暂存物品索地址，方只给附近代收杂货店，既怕暴露身份又暗盼现实相见。\",\"turn\":\"林用画泄压；方安关系从线上迈向可收实物的联系，真实身份仍隐瞒。\",\"time\":\"同一雨天双休日\",\"people\":[\"林夕晨\",\"苏雨晴\",\"张思凡\",\"胡玉牛\",\"方莜莜\",\"安念\",\"游戏公会成员\"],\"objects\":[\"抽象画\",\"电脑游戏\",\"短信\",\"杂货店代收地址\"],\"places\":[\"合租屋\",\"网络论坛和游戏\"]},{\"key\":\"c327\",\"id\":327,\"title\":\"萎靡的小红鸡\",\"kind\":\"main\",\"volume\":3,\"start\":1276,\"end\":1279,\"summary\":\"周一王海峰解释培训缺人而调苏雨晴休假，实是为她避开最繁重班次；王、陈淑艳拌嘴仍共同护着她，梅经理也宽和。午餐时苏与胡在安静走廊交谈，胡沉默认已开始注射药物，苏担心其身体下降却难劝出口。二人下班回家，见林夕晨担忧蹲在已显萎靡的朱雀旁。\",\"turn\":\"职场保护持续，胡健康顾虑获证实，朱雀病危开启失落事件。\",\"time\":\"教师节后周一\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"徐嫂\",\"梅经理\",\"胡玉牛\",\"林夕晨\",\"朱雀\"],\"objects\":[\"培训排班\",\"药物（叙事）\",\"盒饭\"],\"places\":[\"超市\",\"员工走廊\",\"合租屋\"]},{\"key\":\"c328\",\"id\":328,\"title\":\"小红鸡之死\",\"kind\":\"main\",\"volume\":3,\"start\":1280,\"end\":1282,\"summary\":\"苏雨晴发现朱雀病重，众人和曲奇、咖啡都努力照顾却未能挽回。胡解释染色雏鸡的脆弱，苏仍自责，带猫鼠到小区绿化角落埋葬，以石头和柳枝作记号。回家后林夕晨赠她海景画安慰。苏渐平静，却因宠物寿命想到父母也终会离世，重新审视永不相见的决定。\",\"turn\":\"朱雀确实死亡安葬；失落深化苏对亲情和时间不可逆的意识。\",\"time\":\"教师节后周一下班后\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"林夕晨\",\"朱雀\",\"曲奇\",\"咖啡\"],\"objects\":[\"小墓石和柳枝\",\"海景画\"],\"places\":[\"合租屋\",\"小区绿化角落\"]},{\"key\":\"c329\",\"id\":329,\"title\":\"方莜莜的生日（一）\",\"kind\":\"main\",\"volume\":3,\"start\":1283,\"end\":1285,\"summary\":\"九月二十二日苏雨晴轮休在家，翻日记、看朱雀小墓并思考自由与束缚；冉空城问候减少到节日，她仍不回应。林送来自己署名、共四十九幅无字画册，每页背身主角穿行不同景象，其中海中变形鱼与折翼鹰明显呼应莫空寓言。苏欲细究，被请半天假的张思凡归来打断。\",\"turn\":\"林画册把既有寓言化为视觉线索；生日筹备前苏反思自己的相对幸运。\",\"time\":\"2004年9月22日星期三\",\"people\":[\"苏雨晴\",\"冉空城\",\"林夕晨\",\"张思凡\",\"莫空（回想）\",\"曲奇\"],\"objects\":[\"日记本\",\"日历\",\"49幅无字画册\",\"短信\"],\"places\":[\"合租屋\"]},{\"key\":\"c330\",\"id\":330,\"title\":\"方莜莜的生日（二）\",\"kind\":\"main\",\"volume\":3,\"start\":1286,\"end\":1288,\"summary\":\"张思凡说明今日是方莜莜生日，已买十二寸蛋糕，三人用气球、彩带和窗花布置惊喜。苏备画有包装图案的钢笔，林送珍藏名家拨云见日山水画，张的大盒礼物暂保密。她亲自做满桌食物，众人与猫鼠等到天黑仍不见方；苏既期待又敏感地察觉张方旧友关系更亲近。\",\"turn\":\"共同筹备以具体劳动表达珍惜，同时映出苏对关系地位与被爱程度的不安。\",\"time\":\"9月22日下午至傍晚\",\"people\":[\"苏雨晴\",\"张思凡\",\"林夕晨\",\"方莜莜（等待）\",\"曲奇\",\"咖啡\"],\"objects\":[\"12寸蛋糕\",\"气球彩带\",\"钢笔\",\"拨云见日山水画\",\"大礼盒\",\"礼花筒\"],\"places\":[\"合租屋\",\"楼道窗前\"]},{\"key\":\"c331\",\"id\":331,\"title\":\"方莜莜的生日（三）\",\"kind\":\"main\",\"volume\":3,\"start\":1289,\"end\":1292,\"summary\":\"项目完工后方莜莜正常下班，接马甲蛋糕店来电，才知雨晶杂货店有礼物。以方宇悠身份工作的她谎称自己是方莜莜男友取件，确认安念按资料生日送来高档蛋糕，又收到生日快乐短信。多年独自或不过生日的方深受触动，既期待亲近又畏真实相见，绕路落泪后回家。\",\"turn\":\"方宇悠为方的出生名；安的礼物打动方，线上情感首次具体进入现实。\",\"time\":\"9月22日下班后\",\"people\":[\"方莜莜\",\"朱志杰\",\"安念\",\"蛋糕店配送员\",\"雨晶杂货店老板娘\"],\"objects\":[\"彩虹蛋糕\",\"生日短信\",\"曲奇叫声铃音\"],\"places\":[\"公司\",\"电话亭\",\"雨晶杂货店\",\"返家街道\"]},{\"key\":\"c332\",\"id\":332,\"title\":\"方莜莜的生日（四）\",\"kind\":\"main\",\"volume\":3,\"start\":1293,\"end\":1296,\"summary\":\"方莜莜回家被礼花与祝福惊喜包围，外表埋怨惊吓，内心因多年缺失的庆生而感动。安念送的彩虹蛋糕虽跌落略损仍完整，数字蜡烛标明方二十一岁；她先称自买，后承认网友相赠但对方不知身份。众人吃张的自制餐点，点两份蛋糕蜡烛唱歌，方把同一愿望许两遍，未公布内容。\",\"turn\":\"生日使原生家庭的缺席由朋友陪伴补足；方对安的心意未正式确立恋爱。\",\"time\":\"2004年9月22日，方莜莜21岁生日\",\"people\":[\"方莜莜\",\"张思凡\",\"苏雨晴\",\"林夕晨\",\"安念（礼物）\"],\"objects\":[\"彩虹蛋糕\",\"21数字蜡烛\",\"莲花音乐蜡烛\",\"巧克力冻香蕉\"],\"places\":[\"合租屋\"]},{\"key\":\"c333\",\"id\":333,\"title\":\"方莜莜的生日（五）\",\"kind\":\"main\",\"volume\":3,\"start\":1297,\"end\":1300,\"summary\":\"庆生正热闹时胡玉牛未经事先告知带柳韵进门，伙伴因身份隐私紧张，方及时改男声接待，柳以为这里有三个女孩。大家确认她仍不知胡的愿望和合租者身份，对贸然来客不满。苏提议吃蛋糕缓和场面，柳吃醋后用奶油逗胡，众人加入玩闹，暂时掩盖了边界冲突。\",\"turn\":\"柳初见合租伙伴仍不知实情；隐私边界与胡对群体的隔阂变得明显。\",\"time\":\"方生日夜间\",\"people\":[\"方莜莜\",\"张思凡\",\"苏雨晴\",\"林夕晨\",\"胡玉牛\",\"柳韵\"],\"objects\":[\"生日蛋糕\"],\"places\":[\"合租屋\"]},{\"key\":\"c334\",\"id\":334,\"title\":\"方莜莜的生日（六）\",\"kind\":\"main\",\"volume\":3,\"start\":1301,\"end\":1304,\"summary\":\"十点胡送柳回家，听她称自己很有男子气概时勉强微笑，想问秘密却再次退缩。其他人清扫到近午夜，方拆出苏的钢笔、林的山水画和张的成人用品玩笑礼盒，窘迫收起。胡回来为没帮忙道歉，苏无心说大家习惯了，反使他感到被排除；庆生欢乐后各自隐藏的失落仍在。\",\"turn\":\"胡被恋人肯定的男性形象与本愿冲突，伙伴的一句习惯触动其归属危机。\",\"time\":\"9月22日22:00至近午夜\",\"people\":[\"胡玉牛\",\"柳韵\",\"苏雨晴\",\"方莜莜\",\"张思凡\",\"林夕晨\"],\"objects\":[\"钢笔\",\"山水画\",\"成人用品礼盒\",\"气球彩带\"],\"places\":[\"合租屋\",\"返柳家路上\"]},{\"key\":\"c335\",\"id\":335,\"title\":\"新世界之门（上）\",\"kind\":\"main\",\"volume\":3,\"start\":1305,\"end\":1307,\"summary\":\"天语遥母亲照护半月后返工，父母为未来保障更忙，父还考虑合资工厂但未实施。天研究兔子照护、更换饼干笼具，逐渐能面对用药和外观变化，旧部仍只以为她变乖。她因好奇网上搜索自愿改变性别的人，从强烈排斥转向阅读资料，却仍难理解别人主动追求自己痛失的改变。\",\"turn\":\"天开始认识不同性别经验，接纳自己仍与对别人偏见并存。\",\"time\":\"母亲照护约半月后\",\"people\":[\"天语遥\",\"天语遥父母\",\"饼干\",\"旧日部下\",\"网络群体\"],\"objects\":[\"兔笼及用品\",\"网页资料\",\"女装\"],\"places\":[\"天语遥家\",\"网络\"]},{\"key\":\"c336\",\"id\":336,\"title\":\"新世界之门（下）\",\"kind\":\"main\",\"volume\":3,\"start\":1308,\"end\":1311,\"summary\":\"父母疲惫返家带饭和食品，天语遥第一次难为情地关心父亲劳累，逐渐看见一直存在的爱。她问为何有人愿放弃男性身份，母亲提醒每人有苦衷、应先尊重别人；天虽激动否认同类，仍收敛敌意。她继续搜索，找到需邀请码的“新世界之门”论坛，申请审核群，准备进一步接触。\",\"turn\":\"家庭关心修复关系，母亲推动尊重差异；天正式迈向同类社区入口。\",\"time\":\"同日晚间\",\"people\":[\"天语遥\",\"天语遥父母\"],\"objects\":[\"牛奶零食\",\"方便面\",\"新世界之门论坛\"],\"places\":[\"天语遥家\",\"网络\"]},{\"key\":\"c337\",\"id\":337,\"title\":\"好想做个女孩子\",\"kind\":\"main\",\"volume\":3,\"start\":1312,\"end\":1315,\"summary\":\"审核管理员月橙发来用药和心理问卷，天语遥为入论坛尝试以女性心理作答，通过后取昵称软陶，并加入“好想做个女孩子”群。论坛令她发现主动与被动改变者并存，理解更多经历，也生出未来身体可能性的希望；她仍难赞同他人选择、仍恨伤自己的胡。热情群聊与沉郁帖子形成反差。\",\"turn\":\"天以软陶进入既有社群，认知开始变化但仇恨和身份边界尚未消解。\",\"time\":\"c336之后同夜\",\"people\":[\"天语遥\",\"张思凡\",\"论坛管理员和成员\"],\"objects\":[\"审核问卷\",\"邀请码\",\"软陶账号\",\"论坛及QQ群\"],\"places\":[\"新世界之门论坛\",\"好想做个女孩子QQ群\"]},{\"key\":\"c338\",\"id\":338,\"title\":\"空壳\",\"kind\":\"main\",\"volume\":3,\"start\":1316,\"end\":1318,\"summary\":\"苏雨晴在休息日疼痛乏力，伙伴称为反噬，机制只是圈内传闻。昏睡中她见自我相残、亲友死亡或精神失常、陌生者复仇及自己永恒漂流，均为噩梦。随后她以不能自主控制的视角来到天台，熟悉却看不清脸的男子称她女友，并介绍大学生秋易；彩色光洞再现，她才醒来。\",\"turn\":\"身体痛苦与密集梦境形成重大伏笔，不能把梦见的死亡当作已发生结局。\",\"time\":\"后章确认中秋9月28日\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"胡玉牛（梦）\",\"方莜莜（梦）\",\"林夕晨（梦）\",\"张思凡（梦）\",\"天台男子（梦）\",\"秋易（梦）\"],\"objects\":[\"茶杯\",\"彩色光洞\",\"助眠药（梦中）\"],\"places\":[\"合租屋\",\"噩梦宇宙\",\"梦中天台\"]},{\"key\":\"c339\",\"id\":339,\"title\":\"中秋（上）\",\"kind\":\"main\",\"volume\":3,\"start\":1319,\"end\":1322,\"summary\":\"中秋苏雨晴病痛后醒来，只记得梦中被称女友的片段，猜测可能与冉空城有关，却无从确认。冉又发短信，引她回忆两年同桌情谊：他以善意看待她的柔美，为阻止体育课代表强派搬水而争辩并打架，反遭扔进垃圾桶。苏想援手仍受恐吓，女班长及时进教室制止。\",\"turn\":\"苏动摇于友情是否含爱情，校园保护往事揭示依恋形成的具体缘由。\",\"time\":\"2004年9月28日星期二，中秋；中学回忆\",\"people\":[\"苏雨晴\",\"冉空城\",\"孔荀\",\"金晶\"],\"objects\":[\"短信\",\"水桶\",\"教室垃圾桶\"],\"places\":[\"合租屋\",\"旧学校教室（回忆）\"]},{\"key\":\"c340\",\"id\":340,\"title\":\"中秋（下）\",\"kind\":\"main\",\"volume\":3,\"start\":1323,\"end\":1326,\"summary\":\"回忆中校长女儿金晶呵退有体育教师表哥撑腰的孔荀，命苏以后遇欺凌求助；苏与冉留级后她仍常探望。现实短信告知金已赴别城读高中，苏仍不回冉，想切断旧关系又难舍。无月中秋，伙伴分享月饼，方温柔劝她可回家；苏担心不被接纳，只把团圆推给以后，也反思喜欢林是否受性别限制。\",\"turn\":\"旧友去向部分明确，苏的亲情和爱情都处于渴望与自我阻拦之间。\",\"time\":\"2004年9月28日\",\"people\":[\"苏雨晴\",\"冉空城\",\"金晶\",\"孔荀\",\"方莜莜\",\"张思凡\",\"林夕晨\"],\"objects\":[\"中秋短信\",\"月饼\"],\"places\":[\"旧学校（回忆）\",\"合租屋阳台\"]},{\"key\":\"c341\",\"id\":341,\"title\":\"流庆寺（上）\",\"kind\":\"main\",\"volume\":3,\"start\":1327,\"end\":1330,\"summary\":\"国庆出游因车票与人潮取消杭州计划，五名合租者改去流庆寺，门外拥堵两个多小时令苏几乎站不稳。传闻寺内接待贵客，九点后才开门；饮水与伙伴照应助她缓过。进寺后众人讨论各自信仰，苏和林一同上香，张方受浓烟困扰，胡冷淡旁观，群体共同出游中各有心事。\",\"turn\":\"旅行暴露苏体力限制；信仰与求愿议题开启，杭州之行未成。\",\"time\":\"2004年国庆假期第一天\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"香客\",\"交警\"],\"objects\":[\"遮阳伞\",\"矿泉水\",\"佛香蜡烛\"],\"places\":[\"流庆寺外道路\",\"流庆寺\"]},{\"key\":\"c342\",\"id\":342,\"title\":\"流庆寺（下）\",\"kind\":\"main\",\"volume\":3,\"start\":1331,\"end\":1334,\"summary\":\"胡玉牛说寺内弥勒像由自己家族捐资，却未能阻止家道没落，因此心怀怨意。苏虔诚祈求父母接纳和未来顺利，其余人亦各自礼拜。后院售卖开光物与抽签让张不满，昂贵青莲手串未购；苏区分自己的信仰与僧人买卖行为，带大家去吃斋饭，表现出信仰中的自持与判断。\",\"turn\":\"胡家衰落与寺庙关联揭示；苏对信仰有个人边界，未简单依附宗教权威。\",\"time\":\"国庆出游同日\",\"people\":[\"胡玉牛\",\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"售卖法器禅师\"],\"objects\":[\"胡家捐资弥勒像\",\"青莲沉香手串（未购）\",\"签筒\"],\"places\":[\"流庆寺各殿\",\"后院\",\"斋堂\"]},{\"key\":\"c343\",\"id\":343,\"title\":\"叶族博物馆\",\"kind\":\"main\",\"volume\":3,\"start\":1335,\"end\":1337,\"summary\":\"众人吃斋后参观寺院收贫家孩子的学习托管处，张逗弄小和尚被方拉开，离寺前买护身符。挤公交时林主动依偎，苏拥抱她，下车后林又主动牵手，关系更加亲密。五人到叶族博物馆参观村落遗迹与兵器，发现巨大叶祖像及弑仙传说；张方、苏林各结伴，胡夹在中间愈显孤单。\",\"turn\":\"苏林双向依偎更明显；集体无意疏离胡，叶祖线与城市来历浮现。\",\"time\":\"国庆出游同日\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"小和尚\",\"叶祖（传说）\"],\"objects\":[\"护身符\",\"古兵器\",\"叶祖像\"],\"places\":[\"流庆寺托管处\",\"公交车\",\"叶族博物馆\"]},{\"key\":\"c344\",\"id\":344,\"title\":\"神话传说\",\"kind\":\"main\",\"volume\":3,\"start\":1338,\"end\":1341,\"summary\":\"苏和张认出叶祖像所持“轮回”剑与百流山山顶所见相同，张买叶族神话册，众人讨论家族传说、历史及湖泊来历，但尚不能证实神话。疲累返家后决定假期不再外游，张因电视阅兵激昂，林画各国军队共同对抗似叶祖的巨人。方处理完工作又与安念相约在游戏里看风景。\",\"turn\":\"实物图像连接此前山顶线索，神话与林画相互呼应但真假尚未回收。\",\"time\":\"国庆假期首日结束\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"胡玉牛\",\"安念\",\"叶祖（传说）\"],\"objects\":[\"轮回剑\",\"叶族神话册\",\"巨人战场画\"],\"places\":[\"叶族博物馆\",\"合租屋\",\"游戏地图\"]},{\"key\":\"c345\",\"id\":345,\"title\":\"奶油布丁\",\"kind\":\"main\",\"volume\":3,\"start\":1342,\"end\":1344,\"summary\":\"国庆第三天苏雨晴整理四个月收支，自记存款三千四百元，在电脑、未来手术和过冬衣物之间取舍，最终放弃买电脑并标出必需用品。方第一次做奶油与酸奶布丁，四人与猫鼠边吃边看憨豆先生；苏和林偏爱酸奶，张偏爱奶油。经济紧缩没有消除细小享受，苏逐渐找到自主安排生活的乐趣。\",\"turn\":\"苏把生存与梦想写进预算，节制与共同生活使有限资源仍能带来幸福。\",\"time\":\"约2004年10月3日，距假期首日两天\",\"people\":[\"苏雨晴\",\"方莜莜\",\"张思凡\",\"林夕晨\",\"曲奇\",\"咖啡\"],\"objects\":[\"账本\",\"衣物购物计划\",\"奶油布丁\",\"酸奶布丁\",\"憨豆先生影碟\"],\"places\":[\"合租屋\"]},{\"key\":\"c346\",\"id\":346,\"title\":\"方莜莜的决定\",\"kind\":\"main\",\"volume\":3,\"start\":1345,\"end\":1348,\"summary\":\"方莜莜已存三万元，因工作难请足恢复假而决定辞职后安排身体手术，张存一万多、拟实习结束再做，仍犹豫。方选择不先告诉父母，以去父母城市工作为由手写辞职报告，估计最快十二月离职；报告尚未获准。苏希望明年底实现计划，方劝成年再做，张支持其坚持。安与方继续暧昧聊天但未确立恋爱。\",\"turn\":\"方愿为身体道路放弃良好职位；工作、家庭隐瞒和亲密关系的后果尚待展开。\",\"time\":\"国庆假期；预计12月辞职、苏计划次年底\",\"people\":[\"方莜莜\",\"张思凡\",\"苏雨晴\",\"安念\",\"公司总经理（谈及）\"],\"objects\":[\"手写辞职报告\",\"存款\",\"身体手术计划\"],\"places\":[\"合租屋\",\"网络\"]},{\"key\":\"c347\",\"id\":347,\"title\":\"莫空和大黑狗\",\"kind\":\"main\",\"volume\":3,\"start\":1349,\"end\":1352,\"summary\":\"莫空在国庆仅有的一天休假到废旧小区河边读书，给压住书本的大黑狗饼干。戴帽清瘦少年来探，先想退避，被大黑认出扑迎，随后温柔喂丰盛嵌糕；面对莫却戒备，抽女士烟并自称这片老大。莫尊重不追问，两帮此前分日期使用的公共区如今已能共同聚会。\",\"turn\":\"大黑牵引天重回旧地，莫与天首次现实会面形成新的观察关系。\",\"time\":\"莫空国庆休假日\",\"people\":[\"莫空\",\"天语遥\",\"黑皇\",\"两帮成员（述及）\"],\"objects\":[\"小说\",\"饼干\",\"嵌糕\",\"女士烟\"],\"places\":[\"废旧小区后门\",\"公共河边\"]},{\"key\":\"c348\",\"id\":348,\"title\":\"莫空和天语遥\",\"kind\":\"main\",\"volume\":3,\"start\":1353,\"end\":1356,\"summary\":\"莫空已从黄枸听过天冲云，询问身体使天误以为仇敌来犯。他只加热罐头相赠，天吃不惯转喂大黑，随后默然离开。回家她发现罐底纸条劝既决心断过去便不必追忆，对莫如何知情疑惑。末尾旧部其实已知她受创且仍愿接纳，黄枸劝不要打扰其新生活，引发争执。\",\"turn\":\"莫看穿天的割舍痛苦；旧部已有接纳而天不知，仇怨未被化解。\",\"time\":\"c347同日\",\"people\":[\"莫空\",\"天语遥\",\"黄枸\",\"天语遥旧部\",\"黑皇\",\"流浪猫狗\"],\"objects\":[\"军用式罐头\",\"折叠小炉勺\",\"罐底纸条\",\"小说\"],\"places\":[\"公共河边\",\"天语遥家\"]},{\"key\":\"c349\",\"id\":349,\"title\":\"仇人相见\",\"kind\":\"main\",\"volume\":3,\"start\":1357,\"end\":1360,\"summary\":\"国庆过后胡玉牛已一月未注射、半月未用药，体力恢复，却仍想重启计划，继续在梦想与柳韵间犹豫。二人河边许诺过年见面、柳毕业后一同去杭州，恋爱将近两月。天语遥偶然认出他们，控诉重伤后果；胡承认出手过重，柳指出先前侵害。胡流露复杂羡慕被天视为讽刺，二人离开，她哭誓报复。\",\"turn\":\"天与胡当面对质未动手，停药没有解决胡身份冲突，复仇线重新燃起。\",\"time\":\"国庆后约小半月；恋爱近两月\",\"people\":[\"胡玉牛\",\"柳韵\",\"天语遥\",\"孔医生（述及）\"],\"objects\":[\"药物（暂停）\",\"河边鞋子\"],\"places\":[\"小城市河边\"]},{\"key\":\"c350\",\"id\":350,\"title\":\"被撕开的伤口\",\"kind\":\"main\",\"volume\":3,\"start\":1361,\"end\":1364,\"summary\":\"重遇胡后天语遥的创伤与复仇执念激烈爆发，昏厥并第三次入院。两天两夜后醒来，母亲转述贫血、发热已退，天却忘记重遇当天的事。父亲送进口电子烟取悦并承诺周末全家游杭州，随即返工；天虽不舍却体谅，要求回家让母亲上班。她主动说永远是妈妈孩子，亲子关心增加而创伤暂被遗忘。\",\"turn\":\"记忆缺口暂压复仇，家庭关系继续软化；杭州约定尚未见执行。\",\"time\":\"重遇后昏睡两天两夜\",\"people\":[\"天语遥\",\"天语遥父母\",\"医生\"],\"objects\":[\"软陶\",\"电子烟\",\"零食\"],\"places\":[\"天语遥家\",\"医院\"]},{\"key\":\"c351\",\"id\":351,\"title\":\"一剑破万法\",\"kind\":\"main\",\"volume\":3,\"start\":1365,\"end\":1368,\"summary\":\"秋雨中林夕晨通过样画、圈点和手把手方式教苏融合素描与写意，苏的暗恋更深却不敢明说，林神色似有幸福。张读悟空传激动模仿台词，方劝其休息，并拆穿她借茶叶谈环境的牵强哲理。苏把完成的御剑仙人山水图送张，张惊喜后与方争画，平淡生活中梦想与亲昵交织。\",\"turn\":\"苏林通过技艺交流加深依恋，苏将受教成果化为对伙伴的礼物。\",\"time\":\"国庆后秋雨日\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\"],\"objects\":[\"画板\",\"悟空传\",\"茶杯\",\"仙人山水图\"],\"places\":[\"合租屋阳台\"]},{\"key\":\"c352\",\"id\":352,\"title\":\"偷吃巧克力\",\"kind\":\"main\",\"volume\":3,\"start\":1369,\"end\":1372,\"summary\":\"王休假时苏与陈淑艳及促销员在灯坏多时的散称仓盘点，翁只要求当天完成。陈以工作被剥削为由邀请偷吃商品巧克力，苏受催尝了一块，见他人习惯如此仍良心不安，拒绝继续。她担心自己被社会同化、失去本色，也因久未见周超猜他离职而失落，但周的实际去向此时并未确认。\",\"turn\":\"受照顾者也有道德瑕疵，苏开始主动守住边界；周离职只是猜测。\",\"time\":\"国庆后工作日\",\"people\":[\"苏雨晴\",\"陈淑艳\",\"翁锡芽\",\"促销员\",\"周超（猜测）\"],\"objects\":[\"散称巧克力\",\"手电筒\",\"损坏灯具\",\"盘点表\"],\"places\":[\"超市散称仓\"]},{\"key\":\"c353\",\"id\":353,\"title\":\"吹牛打屁\",\"kind\":\"main\",\"volume\":3,\"start\":1373,\"end\":1376,\"summary\":\"连雨令狗头帮聚在废楼梯下打牌聊天，墙纸和废料茶几构成秘密基地。彩虹分享新闻与知识，剑鱼解题出主意又以民族话术掩饰英语不足，凤凰跑腿买面。黄枸严禁成员沾毒，强调感情需负责，却对偷窃打斗等仍放任。成员彼此陪伴又吹嘘，自我规则与现实伤害并存。\",\"turn\":\"帮派分工、友情和选择性道德进一步呈现，为仇敌相遇作铺垫。\",\"time\":\"连绵秋雨日\",\"people\":[\"黄枸\",\"彩虹\",\"剑鱼\",\"凤凰\",\"鼠标\",\"狗头帮成员\"],\"objects\":[\"报纸\",\"自制茶几\",\"扑克牌\",\"方便面\"],\"places\":[\"废旧小区楼梯下秘密基地\"]},{\"key\":\"c354\",\"id\":354,\"title\":\"是你！\",\"kind\":\"main\",\"volume\":3,\"start\":1377,\"end\":1380,\"summary\":\"彩虹领人用废木做床，天语遥帮的元老也在公共基地。胡带柳来探救过她的狗头帮，老三突然认出胡正是伤天之人，六名旧部想报仇。黄枸首次知道伤人者身份，认为天侵害在先而两不相帮；老二以实力不足和应让老大决定劝住老三。胡带柳离开，未发生新打斗，但报复追踪将继续。\",\"turn\":\"原本友好探访让仇人身份向旧部公开，老二暂阻冲突却未化解仇怨。\",\"time\":\"秋雨日\",\"people\":[\"胡玉牛\",\"柳韵\",\"黄枸\",\"彩虹\",\"剑鱼\",\"老二\",\"老三\",\"两帮成员\"],\"objects\":[\"木板床\",\"木工工具\",\"雨伞\"],\"places\":[\"两帮公共基地\"]},{\"key\":\"c355\",\"id\":355,\"title\":\"同在小城\",\"kind\":\"main\",\"volume\":3,\"start\":1381,\"end\":1384,\"summary\":\"天语遥花三天制成大黑软陶像并在论坛晒图，书架已能排出迷你街道。她渐融入论坛日常，仍不全理解不同性别愿望。群聊揭月橙就是张思凡、优子就是方莜莜；得知张同住小城市白兔街后，天答应次日拜访，接受地址电话。她实报十七岁，却把一米六一虚报一米七以维护旧自尊。\",\"turn\":\"天与合租群体即将现实交会，网名身份对应明确，仍隐瞒被动变化缘由。\",\"time\":\"c354前后；约次日拜访\",\"people\":[\"天语遥\",\"张思凡\",\"方莜莜\",\"论坛成员\"],\"objects\":[\"大黑软陶像\",\"透明展盒\",\"相机\",\"QQ地址电话\"],\"places\":[\"天语遥家\",\"好想做个女孩子群\",\"白兔街（约定）\"]},{\"key\":\"c356\",\"id\":356,\"title\":\"男人……也能长得这么漂亮？\",\"kind\":\"main\",\"volume\":3,\"start\":1385,\"end\":1388,\"summary\":\"天语遥独自乘出租车到白兔街，八点致电确认后进入合租屋。张热情介绍自己月橙、方优子、苏清泉、林夕子；胡不在场。天惊讶同伴容貌与女性声音，尤其苏林完全超出她的先入想象。得知声音可以练习转换，她更觉新奇，却用不常上网掩饰为何对社区知识陌生。\",\"turn\":\"网络联系转为现实，同伴形象打破天的刻板预期；仇人胡没有在场。\",\"time\":\"次日早08:00\",\"people\":[\"天语遥\",\"张思凡\",\"方莜莜\",\"苏雨晴\",\"林夕晨\",\"天语遥母亲\",\"出租车司机\"],\"objects\":[\"地址纸条\",\"手机\",\"电子烟\"],\"places\":[\"白兔街合租屋\"]},{\"key\":\"c357\",\"id\":357,\"title\":\"天语遥的会面\",\"kind\":\"main\",\"volume\":3,\"start\":1389,\"end\":1392,\"summary\":\"初次会面中天语遥受林夕晨吸引又纠结性别，既恢复些豪爽，又怕坦白自己并非主动选择会被排斥。张擅自掀帽、端详脸型、指出谎报身高，邀化妆屡遭拒绝；再谎称果汁下了助眠药逗她，触发其强烈戒备后才说只是玩笑。方温柔递纸，与张缺少边界的热情形成差异。\",\"turn\":\"天的身份冲突和个人边界显露；果汁并未实际下药，不可写成真投药。\",\"time\":\"首次拜访同日上午\",\"people\":[\"天语遥\",\"张思凡\",\"方莜莜\",\"苏雨晴\",\"林夕晨\"],\"objects\":[\"果汁\",\"帽子\",\"电子烟\",\"纸巾\"],\"places\":[\"合租屋\"]},{\"key\":\"c358\",\"id\":358,\"title\":\"天语遥的女“妆”\",\"kind\":\"main\",\"volume\":3,\"start\":1393,\"end\":1396,\"summary\":\"方莜莜为张的玩笑解围并提醒需尊重同意，林递星形饼干使天感到被善待。天对妆后形象好奇，终于随张去梳妆；张又越界触碰引她愤怒委屈，随后道歉。镜中女性形象令天惊讶，口头淡漠却同意拍照并索要照片，拒绝过分姿势。她体验新可能，同时仍认为自己是在强迫改变。\",\"turn\":\"温柔安慰与越界并存，天首次愿意保留女性形象，却未解决内在不认同。\",\"time\":\"首次拜访同日\",\"people\":[\"天语遥\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"苏雨晴\",\"曲奇\"],\"objects\":[\"星形饼干\",\"化妆品\",\"相机\",\"妆后照片\"],\"places\":[\"合租屋\",\"张思凡卧室\"]},{\"key\":\"c359\",\"id\":359,\"title\":\"小弟的留言\",\"kind\":\"main\",\"volume\":3,\"start\":1397,\"end\":1400,\"summary\":\"会面次晨天语遥想念热闹，反复整理外表并从张发来的照片选三张发论坛，受到赞美、嘲讽和不受欢迎邀约，后者被她鄙弃。老三留言表示兄弟已知受创却永认她为老大，又告知发现胡。温情令她感动，仇敌线索却恢复上次昏厥前记忆，复仇愤怒重燃，她努力保持冷静。\",\"turn\":\"新的自我探索被旧仇打断，旧部接纳与复仇消息共同拉她回过去。\",\"time\":\"首次拜访次晨\",\"people\":[\"天语遥\",\"张思凡（照片留言）\",\"老三\",\"论坛成员\"],\"objects\":[\"妆后照片\",\"论坛帖子\",\"老三留言\",\"梳子洗面奶\"],\"places\":[\"天语遥家\",\"新世界之门论坛\"]},{\"key\":\"c360\",\"id\":360,\"title\":\"那次事情之后和小弟们的第一次见面\",\"kind\":\"main\",\"volume\":3,\"start\":1401,\"end\":1404,\"summary\":\"天语遥回神发现自己已在阳台抚兔，对记忆空白与失控感恐惧。她回复老三，意外垃圾信息原是其电脑中木马；电话中旧部重申接纳，天部署寻找胡，得知帮派因缺席面临分裂。她承诺立即见面，带着仍未消失的自毁念头与复仇目的赴烂尾工地旁旧木屋，敲门后获二十余名兄弟惊喜迎接。\",\"turn\":\"截至本段天重返旧群体且开始找胡，实际复仇未发生，心理危机仍持续。\",\"time\":\"c359同日上午\",\"people\":[\"天语遥\",\"饼干\",\"老三\",\"老二\",\"其他部下\",\"出租车司机\"],\"objects\":[\"QQ留言\",\"中木马电脑\",\"宽大卫衣\"],\"places\":[\"天语遥家阳台\",\"烂尾工地旁小木屋\"]},{\"key\":\"c361\",\"id\":361,\"title\":\"这一切，终将逝去\",\"kind\":\"main\",\"volume\":3,\"start\":1405,\"end\":1408,\"summary\":\"天语遥重回昔日小弟身边，得到抛起庆祝的热情欢迎。她带忠心的兄弟登山，面对离心者已无意强留；身体衰弱使熟悉山路也走得艰难。重新有水却改道的小溪触动她对旧生活的怀念，她意识到帮派终将散去，仍舍不得眼前的情谊。\",\"turn\":\"旧日首领身份与身体变化冲突，天语遥开始考虑散帮。\",\"time\":\"秋天\",\"people\":[\"天语遥\",\"老二\",\"老三\",\"老四\"],\"objects\":[\"稻草堆\",\"口香糖\",\"狗尾巴草\",\"零食\"],\"places\":[\"帮派木屋\",\"山路\",\"山间小溪\"]},{\"key\":\"c362\",\"id\":362,\"title\":\"言语侮辱\",\"kind\":\"main\",\"volume\":3,\"start\":1409,\"end\":1412,\"summary\":\"在溪边休息的天语遥被雷声惊得落水，原部下老六带分裂者前来，趁机以性别和伤后身体辱骂她并争夺老大位置。忠心小弟揭穿老六忘恩负义，天语遥克制后接受挑战，凭经验将其击倒并放他离开，但受辱者仍准备偷袭。\",\"turn\":\"老六的夺权与恶意羞辱将冲突升级，失败后仍不肯罢休。\",\"time\":\"\",\"people\":[\"天语遥\",\"老六\",\"老二\",\"老三\"],\"objects\":[\"猪肉脯\"],\"places\":[\"山间小溪\"]},{\"key\":\"c363\",\"id\":363,\"title\":\"残身\",\"kind\":\"main\",\"volume\":3,\"start\":1413,\"end\":1416,\"summary\":\"老六偷袭不是继续比武，而是公开暴露天语遥的伤后身体，揭出自己对旧恋情的嫉恨；他恶意歪曲夏归月选择天语遥的往事。兄弟们制伏老六并表忠心，但天语遥心理崩溃而严重自伤。众人将她救起，冒暴雨抬下山求救；老六及追随者乘乱逃走。\",\"turn\":\"天语遥陷入生命危机；背叛和公开羞辱造成创伤复发。\",\"time\":\"\",\"people\":[\"天语遥\",\"老六\",\"老二\",\"老三\",\"老四\"],\"objects\":[\"折叠小刀\",\"救护车\"],\"places\":[\"山间小溪\",\"山路\",\"烂尾楼旁\"]},{\"key\":\"c364\",\"id\":364,\"title\":\"急救\",\"kind\":\"main\",\"volume\":3,\"start\":1417,\"end\":1420,\"summary\":\"众兄弟凑钱后才得以将天语遥送上救护车，外包人员又未施行急救。医院内的管医生则平等温和地救治她，手术成功使她脱离危险。管鹏为父亲送饭，支持父亲离职的念头；叙述明确预告管医生后来辞职。天语遥父母赶来照顾，并未责怪救人的兄弟。\",\"turn\":\"天语遥获救，兄弟情进一步稳固；医护与逐利管理形成对照。\",\"time\":\"\",\"people\":[\"天语遥\",\"老二\",\"老三\",\"老四\",\"管医生\",\"管鹏\",\"天语遥父母\",\"外包急救人员\"],\"objects\":[\"救护车\",\"两百元零钞\",\"盒饭\"],\"places\":[\"医院急诊部\",\"手术室\",\"病房\"]},{\"key\":\"c365\",\"id\":365,\"title\":\"不想再醒来的梦\",\"kind\":\"main\",\"volume\":3,\"start\":1421,\"end\":1424,\"summary\":\"天语遥昏迷中梦见自己以天冲云身份与旧恋人夏归月结婚，拥有儿女与平静生活；她意识到这只是难以实现的愿望后不愿醒来。狐耳九尾少女将她推出梦境。醒后老二以报仇劝她活下去，她要求暂不告知父母仇人线索，并向母亲承诺不再轻生。\",\"turn\":\"与夏归月的婚姻仅为梦境；报仇暂时成为天语遥继续生活的动力。\",\"time\":\"\",\"people\":[\"天语遥\",\"夏归月\",\"老二\",\"老三\",\"天语遥母亲\",\"九尾狐少女\"],\"objects\":[\"婚戒\",\"六芒阵\"],\"places\":[\"梦境婚礼\",\"黑色梦境空间\",\"医院病房\"]},{\"key\":\"c366\",\"id\":366,\"title\":\"林夕晨的外套\",\"kind\":\"main\",\"volume\":3,\"start\":1425,\"end\":1428,\"summary\":\"王海峰因人手调整建议苏雨晴去轻松的玩具部，她舍不得和善主管而拒绝。下班暴雨将她困住，林夕晨主动撑伞来接，又将自己的大衣披给她；这份无声照料令苏雨晴更确信自己的爱意。回家后的一次浴后尴尬使她害羞躲开，夕晨则露出宠溺笑容。\",\"turn\":\"夕晨主动接送与让衣，使雨晴对这段感情的期待加深。\",\"time\":\"秋日暴雨\",\"people\":[\"苏雨晴\",\"林夕晨\",\"王海峰\",\"陈淑艳\"],\"objects\":[\"资料\",\"长柄雨伞\",\"大衣\"],\"places\":[\"大润发超市\",\"员工通道\",\"出租屋\"]},{\"key\":\"c367\",\"id\":367,\"title\":\"电视剧的套路\",\"kind\":\"main\",\"volume\":3,\"start\":1429,\"end\":1432,\"summary\":\"曲奇捣乱引发两人尴尬的浴后照面，夕晨表面平静却悄悄脸红。两人一起看思凡租来的电视剧：故事里两个因女人结仇的男子最后相爱，表现爱可跨越性别；雨晴半途睡着，夕晨看完并因剧中的爱情寓意提出想吃柠檬，还偷偷看向雨晴。\",\"turn\":\"夕晨对雨晴的情感借电视剧与柠檬意象得到暗示，未明说。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"林夕晨\",\"曲奇\",\"咖啡\",\"张思凡\",\"方莜莜\"],\"objects\":[\"浴巾\",\"租借碟片\",\"电视机\",\"柠檬\"],\"places\":[\"出租屋客厅\"]},{\"key\":\"c368\",\"id\":368,\"title\":\"再平淡不过的一天\",\"kind\":\"main\",\"volume\":3,\"start\":1433,\"end\":1436,\"summary\":\"休息日雨晴写周记并照料宠物，发现咖啡毛色已完全变为深紫。胡玉牛为改变外形强穿小鞋，雨晴担忧却无从帮助。夕晨穿昂贵服装、化淡妆出门，让雨晴误以为赴约而吃醋；夕晨以拥抱安抚，明确否认去见男友，并为她露出笑容。\",\"turn\":\"夕晨的外出目的未明；胡玉牛外貌焦虑持续加重。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"林夕晨\",\"胡玉牛\",\"曲奇\",\"咖啡\"],\"objects\":[\"日记本\",\"玩具熊\",\"过小鞋子\",\"名牌衣服\"],\"places\":[\"出租屋\"]},{\"key\":\"c369\",\"id\":369,\"title\":\"早点回来\",\"kind\":\"main\",\"volume\":3,\"start\":1437,\"end\":1440,\"summary\":\"王海峰通知雨晴因领导检查而再休一天，使未具身份证的用工状态显露。雨晴整日惦记外出的夕晨，抱着宠物等候。晚饭时夕晨仍未归，电话里声音疲惫，只说会晚回；雨晴发短信提醒夜路安全，又特意留出她喜欢的春卷、糖醋藕和蛋糕。\",\"turn\":\"夕晨迟归引发不安，雨晴的关怀落实在留饭与等候中。\",\"time\":\"次日将有领导检查\",\"people\":[\"苏雨晴\",\"林夕晨\",\"王海峰\",\"胡玉牛\",\"张思凡\",\"方莜莜\",\"曲奇\",\"咖啡\"],\"objects\":[\"手机\",\"电视购物广告\",\"春卷\",\"糖醋藕\",\"蛋糕\"],\"places\":[\"出租屋\"]},{\"key\":\"c370\",\"id\":370,\"title\":\"小城市小商品市场\",\"kind\":\"main\",\"volume\":3,\"start\":1441,\"end\":1444,\"summary\":\"雨晴等夕晨到睡着，翌日在夕晨床上醒来，具体如何被移至床上未叙。她邀夕晨盛装陪逛小商品市场，精打细算购入换季衣物并首次费力议价买羽绒服。两人牵手同行，雨晴又买红色狐尾围巾送夕晨，为自己挑白猫围巾；夕晨笑着表示喜欢。\",\"turn\":\"雨晴送出具有成对意味的围巾，两人度过亲密的购物日。\",\"time\":\"翌日晴天\",\"people\":[\"苏雨晴\",\"林夕晨\"],\"objects\":[\"羽绒服\",\"火红狐尾围巾\",\"白猫围巾\",\"换季衣物\"],\"places\":[\"出租屋\",\"公交车\",\"小城市小商品市场\"]},{\"key\":\"c371\",\"id\":371,\"title\":\"上晚班的日常（上）\",\"kind\":\"main\",\"volume\":3,\"start\":1445,\"end\":1448,\"summary\":\"雨晴上晚班时耐心回答顾客问路，却被投诉霉米的老人错当服务台人员斥责羞辱。周超以清楚解释和带路替她解围；她才发现他仍在超市工作。另一边王海峰与厂家商议促销地堆并收取小额好处，叙述借此呈现人情与职场规则对好人的侵蚀。\",\"turn\":\"周超重新出现并展现善于沟通的一面，雨晴感激他的帮助。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"王海峰\",\"周超\",\"投诉霉米的老人\",\"厂家业务员\"],\"objects\":[\"小票\",\"霉米\",\"酒柜\",\"促销地堆\"],\"places\":[\"大润发超市酒柜\",\"一楼服务台\"]},{\"key\":\"c372\",\"id\":372,\"title\":\"上晚班的日常（下）\",\"kind\":\"main\",\"volume\":3,\"start\":1449,\"end\":1452,\"summary\":\"周超确认已由防损部调到酒柜，称喜欢王海峰的工作氛围，对雨晴又有明显亲近之意。雨晴为顾客结账、替家电部处理锁机后的付款，面对陌生人已比初入社会时自然成熟。新的中年兼职也到岗；雨晴坚持等交班才去吃饭，显示责任感。\",\"turn\":\"雨晴工作能力成熟，周超成为直属同部门同事。\",\"time\":\"叙述明确二零零四年；独立生活半年\",\"people\":[\"苏雨晴\",\"周超\",\"王海峰\",\"家电部主管\",\"中年兼职员工\"],\"objects\":[\"收银机\",\"微波炉\",\"红酒\",\"小票\"],\"places\":[\"大润发超市酒柜\"]},{\"key\":\"c373\",\"id\":373,\"title\":\"你竟然也住在这里\",\"kind\":\"main\",\"volume\":3,\"start\":1453,\"end\":1455,\"summary\":\"周六清晨天语遥来合租屋做客，询问房租并想搬来，实因父母在两次自伤后严密看护，令她失去自由。思凡说明整套六房由五名同伴承租，以避免外人打扰。正当她问起未见过的第五人，去见柳韵后情绪不佳的胡玉牛回家；天语遥立即认出了仇人。\",\"turn\":\"天语遥与胡玉牛意外相遇，原本分离的仇恨线汇入合租主线。\",\"time\":\"周六清晨；秋季\",\"people\":[\"天语遥\",\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\",\"胡玉牛\",\"天语遥父母\"],\"objects\":[\"钥匙\",\"早餐\",\"棉被\"],\"places\":[\"出租屋\"]},{\"key\":\"c374\",\"id\":374,\"title\":\"天大的笑话\",\"kind\":\"main\",\"volume\":3,\"start\":1456,\"end\":1459,\"summary\":\"天语遥意识到致自己重伤的胡玉牛也是渴望女性身份的同伴，原定以同样伤害复仇的计划失效。她在失控中攻击其外形后哭着离开。室友不知真实缘由，思凡用感情纠纷玩笑试图缓和，胡玉牛拒绝解释。天语遥跑到陌生小公园痛哭，意外遇见旧恋人夏归月。\",\"turn\":\"复仇计划受挫；夏归月重新进入天语遥生活。\",\"time\":\"同日上午\",\"people\":[\"天语遥\",\"胡玉牛\",\"张思凡\",\"方莜莜\",\"苏雨晴\",\"林夕晨\",\"夏归月\",\"热心老大娘\"],\"objects\":[\"枫叶\"],\"places\":[\"出租屋\",\"街道\",\"无名小公园\"]},{\"key\":\"c375\",\"id\":375,\"title\":\"夏归月\",\"kind\":\"main\",\"volume\":3,\"start\":1460,\"end\":1462,\"summary\":\"夏归月认出哭泣而虚弱的天语遥并拉住她；天语遥羞于展示变化，试图否认身份和逃走，却一度昏倒。夏归月以膝枕照料，回忆昔日一年多恋情及和平分手，坚决而温柔地劝她倾诉。天语遥口称已成陌路人，夏归月看穿逞强，主动亲吻她。\",\"turn\":\"旧情在脆弱与照料中重燃，天语遥的男性强硬形象被打破。\",\"time\":\"距昔日分手约一年\",\"people\":[\"天语遥\",\"夏归月\"],\"objects\":[\"长椅\",\"落叶\"],\"places\":[\"无名小公园\"]},{\"key\":\"c376\",\"id\":376,\"title\":\"说出来会好受一些\",\"kind\":\"main\",\"volume\":3,\"start\":1463,\"end\":1466,\"summary\":\"天语遥终于向夏归月讲出遭遇与内心苦痛。夏归月先因现实顾虑委婉拒绝复合，提出做姐妹，天语遥拒绝被同情而离开；她孤独的回望又让夏归月决定跨越顾虑追求旧爱。夏归月追上明确提出在一起，天语遥嘴上拒绝，最终接受牵手同行，把眼前幸福视作可能短暂的安慰。\",\"turn\":\"夏归月重新提出恋爱关系；天语遥仍对共同未来缺乏信心。\",\"time\":\"\",\"people\":[\"天语遥\",\"夏归月\"],\"objects\":[\"落叶\"],\"places\":[\"无名小公园\"]},{\"key\":\"c377\",\"id\":377,\"title\":\"来，我喂你吃\",\"kind\":\"main\",\"volume\":3,\"start\":1467,\"end\":1470,\"summary\":\"夏归月带天语遥吃火锅，发现她已不能适应从前爱吃的辣，便换清淡锅底并细心喂食。天语遥承认父母已将身份证姓名改为天语遥，却希望夏归月仍叫冲云以保留旧日自我。两人恢复亲密约会，夏归月邀请她回家见父母，天语遥虽紧张仍接受。\",\"turn\":\"饮食和称呼凸显变化；关系推进至正式见家长。\",\"time\":\"与重逢同日\",\"people\":[\"天语遥\",\"夏归月\"],\"objects\":[\"火锅\",\"水杯\",\"身份证\"],\"places\":[\"二楼火锅店\",\"街道\"]},{\"key\":\"c378\",\"id\":378,\"title\":\"爸，妈！\",\"kind\":\"main\",\"volume\":3,\"start\":1471,\"end\":1474,\"summary\":\"初见夏归月父母时，沉浸婚后幻想的天语遥误喊爸妈，令众人尴尬。夏父开明友善，夏母对女儿带恋人回家保留顾虑；两人不断送水果查看房内情况。夏归月给天语遥戴小红花取乐，她逐渐看见自己不再独断控制后，归月比旧日恋爱时更自由快乐。\",\"turn\":\"夏归月父母首次接触天语遥，暂不知其身体情况；恋爱权力关系改变。\",\"time\":\"重逢同日下午\",\"people\":[\"天语遥\",\"夏归月\",\"夏归月父亲\",\"夏归月母亲\"],\"objects\":[\"小红花\",\"水果盘\",\"报纸\"],\"places\":[\"夏归月家\"]},{\"key\":\"c379\",\"id\":379,\"title\":\"柳韵调戏胡玉牛\",\"kind\":\"main\",\"volume\":3,\"start\":1475,\"end\":1478,\"summary\":\"胡玉牛与柳韵在公园竹林玩大富翁和五子棋，柳韵调皮争胜又大胆表达亲密，阿牛则纵容她并在意她的情感经历。肯德基约会看似甜蜜，阿牛却想起孔雀医生所述生育与身体变化问题，面临维持恋情和继续转变的两难，仍拖延作出取舍。\",\"turn\":\"阿牛渴望兼得恋爱与身份转变，逃避选择埋下后患。\",\"time\":\"叙述明确二零零四年\",\"people\":[\"胡玉牛\",\"柳韵\",\"孔雀\"],\"objects\":[\"大富翁\",\"五子棋\",\"薯片\"],\"places\":[\"公园竹林\",\"肯德基\"]},{\"key\":\"c380\",\"id\":380,\"title\":\"让他走吧\",\"kind\":\"main\",\"volume\":3,\"start\":1479,\"end\":1482,\"summary\":\"夏归月学业繁忙，两人的恋爱多靠短信维系。部下再次发现阿牛，天语遥赶到小城第一高中，表面接受道歉并命兄弟放行，还把帮主交给老三后退出。实际上她已决定假装和解，争取搬入合租屋搜集阿牛身份的证据，借柳韵及其亲属实施更深的报复。\",\"turn\":\"天语遥退出帮派，表面宽恕掩盖针对阿牛社会关系的复仇计划。\",\"time\":\"\",\"people\":[\"天语遥\",\"夏归月\",\"胡玉牛\",\"老二\",\"老三\",\"老四\",\"黑皇\",\"阿呆\"],\"objects\":[\"手机短信\",\"狗粮\",\"狗绳\"],\"places\":[\"两帮公共区域\",\"小城第一高中门口\"]},{\"key\":\"c381\",\"id\":381,\"title\":\"周超和他的新女朋友\",\"kind\":\"main\",\"volume\":3,\"start\":1483,\"end\":1486,\"summary\":\"周超的未具名女友来到酒柜，两人公开亲密并购买食品日用品。雨晴短暂失落于自己误判他的追求，继而思考普通恋情与自身身份处境的差距。她从孙昊细微神情怀疑他只对思凡抱猎奇心理，但缺乏把握没有提醒；想到夕晨，仍是甜蜜与不安并存。\",\"turn\":\"周超已有女友；雨晴对孙昊动机的怀疑尚属个人判断。\",\"time\":\"二零零四年\",\"people\":[\"苏雨晴\",\"周超\",\"周超女友\",\"王海峰\",\"张思凡\",\"孙昊\"],\"objects\":[\"退货清单\",\"鸡尾酒\",\"日用品\"],\"places\":[\"大润发超市酒柜\"]},{\"key\":\"c382\",\"id\":382,\"title\":\"游戏里的结婚\",\"kind\":\"main\",\"volume\":3,\"start\":1487,\"end\":1490,\"summary\":\"莜莜上线《传奇》后被安念带去婚姻殿堂。因她用男性角色优子，安念换女号有只银娘，二人在游戏结婚并办只有两人的喜宴。莜莜决定继续隐瞒自身经历，既幸福又担忧无法现实相见；夜里梦见婚后被安念发现身份而辱骂惊醒，显示隐瞒带来的焦虑。\",\"turn\":\"两人确立网恋；现实身份未坦白，辱骂仅发生于莜莜噩梦。\",\"time\":\"夜晚至翌日清晨\",\"people\":[\"方莜莜\",\"安念\"],\"objects\":[\"电脑\",\"传奇\",\"游戏结婚戒指\"],\"places\":[\"出租屋莜莜房间\",\"传奇土城\",\"游戏婚姻殿堂\"]},{\"key\":\"c383\",\"id\":383,\"title\":\"莫空和胡玉牛的对话\",\"kind\":\"main\",\"volume\":3,\"start\":1491,\"end\":1494,\"summary\":\"莫空将跳上岸的鱼放回水中，随后听胡玉牛坦白身份愿望、天语遥旧怨与柳韵恋情。莫空表示不歧视，以鱼的生存处境劝其慎重，并列出放弃转变、放弃恋情、兼顾两者三条路。阿牛仍寄望奇迹，选择同时前行；莫空提醒若真爱柳韵，也须考虑她的感受。\",\"turn\":\"阿牛选择兼顾两条道路，莫空强调决定与责任最终仍在本人。\",\"time\":\"\",\"people\":[\"莫空\",\"胡玉牛\"],\"objects\":[\"木头烟盒\",\"香烟\",\"草鱼\"],\"places\":[\"河边长椅\"]},{\"key\":\"c384\",\"id\":384,\"title\":\"猫大王\",\"kind\":\"main\",\"volume\":3,\"start\":1495,\"end\":1498,\"summary\":\"雨晴与夕晨带曲奇、咖啡晨游公园，夕晨主动牵她的手。曲奇击退挑衅的宠物犬，却与大黑狗亲近相处，形成狗背猫、猫背鼠的奇景。摄影者获许只拍局部，雨晴避免面貌曝光。她提出向夕晨持续学画，希望将来一起在家工作，夕晨温柔答应。\",\"turn\":\"雨晴确定学画愿望；宠物跨物种亲密呼应人与人的接纳。\",\"time\":\"清爽的休息日早晨\",\"people\":[\"苏雨晴\",\"林夕晨\",\"曲奇\",\"咖啡\",\"黑皇\",\"摄影青年\"],\"objects\":[\"照相机\"],\"places\":[\"公园\"]},{\"key\":\"c385\",\"id\":385,\"title\":\"搬到外面去住（上）\",\"kind\":\"main\",\"volume\":3,\"start\":1499,\"end\":1502,\"summary\":\"天语遥带兔子饼干在小区吃草，感叹笼中安稳与自由的代价。退帮后的空落里，她将夏归月视为暂时温暖，甚至打算复仇后告别生活。看到父亲劳累、母亲照料又心疼不已；软陶教程未能吸引注意，她最终在晚饭时向父母提出搬出居住。\",\"turn\":\"搬离计划开始执行，恋爱和亲情尚未消除她的自毁倾向。\",\"time\":\"双休日\",\"people\":[\"天语遥\",\"天语遥父亲\",\"天语遥母亲\",\"饼干\"],\"objects\":[\"兔笼\",\"软陶教程\",\"电脑\"],\"places\":[\"天语遥小区草坪\",\"天语遥家\"]},{\"key\":\"c386\",\"id\":386,\"title\":\"搬到外面去住（下）\",\"kind\":\"main\",\"volume\":3,\"start\":1503,\"end\":1506,\"summary\":\"天语遥以融入同类、学习接纳变化为理由请求搬去合租，隐瞒真正的复仇目的。父母整夜商量后，由父亲说服母亲同意，条件是周末回家、出事即搬回，并亲自检查住处。他们迅速替她准备被褥行李，父亲又给一千元生活费；她感激父母，却继续维持说辞。\",\"turn\":\"父母授权搬入同伴住处，天语遥获得接近胡玉牛的机会。\",\"time\":\"请求次日清晨\",\"people\":[\"天语遥\",\"天语遥父亲\",\"天语遥母亲\"],\"objects\":[\"行李箱\",\"被褥\",\"一千元生活费\"],\"places\":[\"天语遥家\"]},{\"key\":\"c387\",\"id\":387,\"title\":\"住满了的合租房\",\"kind\":\"main\",\"volume\":3,\"start\":1507,\"end\":1510,\"summary\":\"父母陪天语遥带行李来到合租屋，而她事前并未征得室友同意。莜莜顾虑旧怨，思凡见她恳求而心软接纳，六间房从此住满。父母认真审视住处、整理家具并不断询问室友情况；莜莜准备午饭，最终勉强收下三百元伙食费，众人面对过度关怀既理解又不自在。\",\"turn\":\"天语遥正式入住，第六房被填满；复仇者进入共同家庭。\",\"time\":\"搬家当天上午至午饭\",\"people\":[\"天语遥\",\"天语遥父母\",\"方莜莜\",\"张思凡\",\"苏雨晴\",\"林夕晨\",\"曲奇\"],\"objects\":[\"行李\",\"房间钥匙\",\"三百元伙食费\",\"画纸\"],\"places\":[\"六人合租屋\"]},{\"key\":\"c388\",\"id\":388,\"title\":\"和平相处\",\"kind\":\"main\",\"volume\":3,\"start\":1511,\"end\":1514,\"summary\":\"天语遥父母留下联系方式离去。雨晴靠夕晨肩头睡着，夕晨换左手画画以免吵醒她，却画出令曲奇不安、带创伤意味的画面。傍晚阿牛携柳韵回家，众人担心旧怨揭开秘密；天语遥继续伪装释怀，没有揭露阿牛身份，使他误以为纠纷已过。\",\"turn\":\"表面和平建立；夕晨隐藏情绪通过不安的画作流露。\",\"time\":\"搬家当日傍晚\",\"people\":[\"天语遥\",\"天语遥父母\",\"林夕晨\",\"苏雨晴\",\"曲奇\",\"胡玉牛\",\"柳韵\",\"方莜莜\",\"张思凡\"],\"objects\":[\"名片\",\"笔记本电脑\",\"画作\"],\"places\":[\"六人合租屋\"]},{\"key\":\"c389\",\"id\":389,\"title\":\"方莜莜的辞职申请\",\"kind\":\"main\",\"volume\":3,\"start\":1515,\"end\":1518,\"summary\":\"总经理正式处理方莜莜的辞职请求，惜其能力与潜力而挽留。她以去外地陪恋人为借口，真实目的是安排手术；获准最早次月二十日、月底左右离职。莜莜加紧完成任务，准备推荐并培养朱志杰接任；朱自觉学历不足、也舍不得这位友善主管。\",\"turn\":\"辞职时间确定，手术准备提速，工作传承开始。\",\"time\":\"2004年十月底；拟十一月下旬离职\",\"people\":[\"方莜莜\",\"朱志杰\",\"总经理\"],\"objects\":[\"辞职报告\",\"电脑机箱\",\"工作资料\"],\"places\":[\"公司总经理办公室\",\"部门办公室\"]},{\"key\":\"c390\",\"id\":390,\"title\":\"搜集证据\",\"kind\":\"main\",\"volume\":3,\"start\":1519,\"end\":1521,\"summary\":\"天语遥一直等夕晨外出，终于在她盛装离家后搜集阿牛证据，却发现房门上锁，客厅物品也无法证明属于他。她想到需要数码相机及更完整计划，只先收集部分药盒。佛经暂缓她的急躁，饼干受限与曲奇的自由形成对照，她承认自己擅长大局却缺耐心。\",\"turn\":\"搜证首次受挫，天语遥准备把报复从物件搜查推进至影像证据。\",\"time\":\"\",\"people\":[\"天语遥\",\"林夕晨\",\"胡玉牛\",\"饼干\",\"曲奇\",\"咖啡\"],\"objects\":[\"佛经\",\"门锁\",\"药盒\",\"脱毛膏\",\"数码相机设想\",\"兔笼\"],\"places\":[\"六人合租屋\"]},{\"key\":\"c391\",\"id\":391,\"title\":\"在梦中做个女孩子\",\"kind\":\"main\",\"volume\":3,\"start\":1522,\"end\":1525,\"summary\":\"立冬休息日雨晴从成为理想女孩的梦中醒来，面对身体不适、寒冷与现实失落，以佛教文字平复心绪，却坚持人不能完全没有愿望。天语遥周末回家后提前带各种早餐返屋，既为融入与行事方便，也是真心感谢同伴。雨晴开心吃嵌糕，二人称呼更亲近。\",\"turn\":\"共同生活开始改变天语遥习惯；雨晴仍坚持自身选择。\",\"time\":\"2004年11月7日，星期日，立冬\",\"people\":[\"苏雨晴\",\"天语遥\",\"曲奇\",\"饼干\"],\"objects\":[\"解脱歌\",\"证道歌\",\"棉被\",\"嵌糕\",\"早餐\"],\"places\":[\"六人合租屋\"]},{\"key\":\"c392\",\"id\":392,\"title\":\"天语遥和夏归月和过山车\",\"kind\":\"main\",\"volume\":3,\"start\":1526,\"end\":1529,\"summary\":\"天语遥离开合租屋后与夏归月在游乐园约会，两人吃冰淇淋、坐摩天轮并亲吻。她既珍惜眼前甜蜜又担心没有未来。归月首次坐过山车前犹豫，天语遥鼓励同行，却也紧张虚脱；仍坚持自己解安全带并照顾归月，显示她不愿放下强撑的习惯。\",\"turn\":\"天语遥在亲密中短暂松弛，旧日强硬自尊仍在。\",\"time\":\"立冬当日游玩\",\"people\":[\"天语遥\",\"夏归月\"],\"objects\":[\"冰淇淋\",\"摩天轮\",\"过山车\"],\"places\":[\"小城市游乐园\"]},{\"key\":\"c393\",\"id\":393,\"title\":\"婚纱摄影\",\"kind\":\"main\",\"volume\":3,\"start\":1530,\"end\":1533,\"summary\":\"夏归月想尝试游乐园服装摄影，天语遥付钱选婚纱套餐。两人先穿旗袍中山装、皇帝皇后装，再拍六张婚纱照；归月坚持分担费用，天语遥则以亲密关系回应。自然投入的拍摄让她仿佛实现梦中婚礼，但这仅是情侣留影，她们等待现场打印照片。\",\"turn\":\"婚纱照片把未实现的婚姻愿望变成可保存的纪念物。\",\"time\":\"同日\",\"people\":[\"天语遥\",\"夏归月\",\"婚纱摄影师\"],\"objects\":[\"婚纱照\",\"旗袍\",\"中山装\",\"宫廷服\",\"礼服\"],\"places\":[\"游乐园摄影服务点\",\"人工河\",\"草地\"]},{\"key\":\"c394\",\"id\":394,\"title\":\"公益捐款的策划\",\"kind\":\"main\",\"volume\":3,\"start\":1534,\"end\":1537,\"summary\":\"思凡被分派筹划元旦前后的公益募捐，却苦于项目和基金会联络。众人讨论后，莜莜提供做性别相关支持工作的群友联系方式，思凡准备联系并申报。对未成年者选择的讨论令雨晴更明确自我；莜莜忙着赶工辞职，思凡则坦言对不可逆手术仍犹豫。\",\"turn\":\"公益支线启动；不同角色对身份选择和手术的态度被区分。\",\"time\":\"2004年十一月；活动拟元旦前后\",\"people\":[\"张思凡\",\"苏雨晴\",\"方莜莜\",\"孔雀\"],\"objects\":[\"公益项目申请\",\"账本\",\"宣传单设想\",\"联系方式\"],\"places\":[\"六人合租屋\"]},{\"key\":\"c395\",\"id\":395,\"title\":\"真角大古\",\"kind\":\"main\",\"volume\":3,\"start\":1538,\"end\":1541,\"summary\":\"雨晴绕路到中学旁小卖部，看学生吃零食、玩四驱车和看《迪迦奥特曼》结局。她既怀念校园，也意识到自己的童年被学习及功利安排占据，难与同龄人共享话题。回家后想到春节将近、超市忙碌和王海峰明年辞职的传闻，担心友善工作环境随之消失。\",\"turn\":\"雨晴把童年遗憾与当前就业不安联系起来；大古仅为文化引用。\",\"time\":\"2004年末；提及2005年二月春节\",\"people\":[\"苏雨晴\",\"中学生\",\"小卖部老板\",\"王海峰\"],\"objects\":[\"咪咪虾条\",\"四驱车\",\"悠悠球\",\"陀螺\",\"神光棒玩具\",\"迪迦奥特曼\"],\"places\":[\"中学旁小卖部\",\"出租屋\"]},{\"key\":\"c396\",\"id\":396,\"title\":\"枯黄的爬山虎\",\"kind\":\"main\",\"volume\":3,\"start\":1542,\"end\":1545,\"summary\":\"众人回到思凡郊外的集装箱房打扫，雨晴面对枯黄爬山虎回忆初来小城的失窃、流浪、面馆工作与再次迁居。她想念父母身体和旧日照料，承认离家带来的悔意，却仍不愿放弃自我。悲伤中即兴写曲唱出失去、哭泣与继续前行，天语遥坐来倾听。\",\"turn\":\"雨晴以创作容纳乡愁，承认悲伤也能与坚强共存。\",\"time\":\"2004年冬；离家约半年\",\"people\":[\"苏雨晴\",\"天语遥\",\"张思凡\",\"苏雨晴父母\"],\"objects\":[\"集装箱房\",\"枯黄爬山虎\",\"原创歌曲\",\"木椅\"],\"places\":[\"郊外集装箱房\",\"小面馆（回忆）\"]},{\"key\":\"c397\",\"id\":397,\"title\":\"正式的辞职离开\",\"kind\":\"main\",\"volume\":3,\"start\":1546,\"end\":1549,\"summary\":\"方莜莜完成全部任务后正式辞职，推荐朱志杰任临时主管，并鼓励他靠学习独当一面。离别有惋惜也有解脱，她终于拥有个人时间，去河边与一名未具名落魄男子喂鱼，观察蚂蚁和自然细节，重新感到希望，决定预约周末手术以便朋友照应。\",\"turn\":\"莜莜结束重要工作阶段，进入手术与休养生活；朱志杰获试任机会。\",\"time\":\"2004年十一月底\",\"people\":[\"方莜莜\",\"朱志杰\",\"总经理\",\"河边落魄男子\"],\"objects\":[\"水杯\",\"枕头\",\"面包屑\"],\"places\":[\"公司\",\"河岸\"]},{\"key\":\"c398\",\"id\":398,\"title\":\"斩断退路的方莜莜\",\"kind\":\"main\",\"volume\":3,\"start\":1550,\"end\":1553,\"summary\":\"莜莜在孔雀私人诊所接受去势手术，雨晴、思凡、夕晨和天语遥守候，阿牛未到场。手术成功但恢复疼痛，孔雀轻率展示术后组织令天语遥创伤反应强烈。孔雀正是群中基金会经营者，给予费用优惠和后续照料。莜莜心中反而安定，开始考虑向安念坦白。\",\"turn\":\"莜莜完成去势手术，尚非完整性别确认手术；坦白恋情的念头成形。\",\"time\":\"十一月底周末，后文称上周末手术\",\"people\":[\"方莜莜\",\"孔雀\",\"苏雨晴\",\"张思凡\",\"林夕晨\",\"天语遥\"],\"objects\":[\"手术相关器物\",\"病床\"],\"places\":[\"孔雀私人诊所\"]},{\"key\":\"c399\",\"id\":399,\"title\":\"跟踪胡玉牛\",\"kind\":\"main\",\"volume\":3,\"start\":1554,\"end\":1557,\"summary\":\"天语遥连续第五天跟踪阿牛，终于从超市一路跟到孔雀诊所。她使用向父亲撒娇换来的高清数码相机拍下阿牛接受激素注射，又向孔雀假称收藏讨走空针筒，视作照片与实物配套证据。她知道仍需完整证明，但报复计划首次取得有价值的材料。\",\"turn\":\"天语遥掌握关键影像与实物，复仇具备实施基础。\",\"time\":\"2004年十一月底星期五；莜莜出诊所后五天\",\"people\":[\"天语遥\",\"胡玉牛\",\"孔雀\",\"天语遥父亲\",\"苏雨晴\"],\"objects\":[\"数码相机\",\"录像\",\"空针筒\"],\"places\":[\"超市员工通道\",\"公交车\",\"孔雀私人诊所\"]},{\"key\":\"c400\",\"id\":400,\"title\":\"下雪了\",\"kind\":\"main\",\"volume\":3,\"start\":1558,\"end\":1561,\"summary\":\"十二月小城初雪，莜莜在家恢复，雨晴接手做清淡饭菜、厨艺渐进，夕晨帮她收碗并继续教画。六人难得同桌，阿牛刻意少吃引人担忧。天语遥制作一套夏归月陶人，面对已经齐全的复仇证据却决定暂缓，想先弥补旧日遗憾，与归月过一个快乐新年。\",\"turn\":\"照料使合租生活温暖；天语遥因爱情推迟复仇到过年后。\",\"time\":\"2004年十二月初雪\",\"people\":[\"方莜莜\",\"苏雨晴\",\"林夕晨\",\"张思凡\",\"天语遥\",\"胡玉牛\",\"夏归月\"],\"objects\":[\"雪\",\"早餐\",\"画板\",\"夏归月陶人\",\"证据袋\"],\"places\":[\"六人合租屋\"]},{\"key\":\"c401\",\"id\":401,\"title\":\"把真相告诉你\",\"kind\":\"main\",\"volume\":4,\"start\":1563,\"end\":1566,\"summary\":\"术后数周的莜莜通过QQ和YY向安念坦白药娘经历与手术真相，用变换声线证明自己此前隐瞒的身份。安念惊讶后明确接纳并维持恋爱，说明自己童年也想过成为女孩，因此能部分理解。莜莜喜极而泣，约定明年六月在安念生日时见面，并改成表达爱意的QQ签名。\",\"turn\":\"噩梦中的被抛弃没有成真，坦诚成为网恋转向现实计划的转折。\",\"time\":\"术后数周；约定2005年六月见面\",\"people\":[\"方莜莜\",\"安念\"],\"objects\":[\"QQ\",\"YY语音\",\"QQ签名\"],\"places\":[\"莜莜房间\",\"网络语音频道\"]},{\"key\":\"c402\",\"id\":402,\"title\":\"为什么要这个时候生病？\",\"kind\":\"main\",\"volume\":4,\"start\":1567,\"end\":1570,\"summary\":\"圣诞前超市忙碌，王海峰因结石就医仍被总经理叫回，又遭不合情理的病中责难，副经理附和。周超、翁锡芽、徐嫂、陈淑艳等同事一致为他不平，梅经理也愿代请假。他继续工作，众人默契分担重活；多年受排挤后，他宣布明年辞职，认为资助上大学的恩情已偿还。\",\"turn\":\"病中受辱坚定王海峰离职，众员工显出真实团结与不舍。\",\"time\":\"2004年圣诞节临近\",\"people\":[\"王海峰\",\"苏雨晴\",\"周超\",\"翁锡芽\",\"徐嫂\",\"陈淑艳\",\"梅经理\",\"超市总经理\",\"食品副经理\"],\"objects\":[\"年货地堆\",\"工作清单\"],\"places\":[\"大润发超市\"]},{\"key\":\"c403\",\"id\":403,\"title\":\"大雪纷飞的圣诞夜（上）\",\"kind\":\"main\",\"volume\":4,\"start\":1571,\"end\":1573,\"summary\":\"大雪中的圣诞夜，其他室友各有约会或复诊安排，雨晴与夕晨牵手逛街，关系已自然亲密。她们向老伯买糖苹果，又尝路边小吃、到开放海边公园买荧光棒。雨晴暂不计较花费，只想珍惜共同快乐；夕晨面对糖苹果有一瞬低落，随即掩藏。\",\"turn\":\"圣诞约会承载亲密幸福，也闪现夕晨未解释的忧伤。\",\"time\":\"2004年12月25日夜\",\"people\":[\"苏雨晴\",\"林夕晨\",\"卖糖葫芦老伯\",\"张思凡\",\"孙昊\",\"方莜莜\",\"孔雀\"],\"objects\":[\"糖苹果\",\"小吃\",\"荧光棒\",\"雨伞\"],\"places\":[\"小城街道\",\"开放海边公园\"]},{\"key\":\"c404\",\"id\":404,\"title\":\"大雪纷飞的圣诞夜（下）\",\"kind\":\"main\",\"volume\":4,\"start\":1574,\"end\":1577,\"summary\":\"两人在海边大石后休息，遇见一名沧桑男子自言自语谈孤独、捷径与金钱代价。夕晨罕见震惊，并流畅低声说不那样做又该如何，雨晴尊重秘密未追问。夕晨随后捡起黄白色贝壳，分为两半各留一半；雨晴猜测是信物，却没敢问明，深夜两人回家。\",\"turn\":\"半贝壳成为亲密信物；夕晨赚钱与表情控制伏笔加深。\",\"time\":\"2004年圣诞夜至午夜\",\"people\":[\"苏雨晴\",\"林夕晨\",\"海边沧桑男子\"],\"objects\":[\"梅花糕\",\"荧光手环\",\"成对半贝壳\"],\"places\":[\"海边公园大石后\",\"海滩\"]},{\"key\":\"c405\",\"id\":405,\"title\":\"2004 年年末的日常（上）\",\"kind\":\"main\",\"volume\":4,\"start\":1578,\"end\":1581,\"summary\":\"年货陈列增多，雨晴因失眠疲惫，在值守酒柜时误把顾客交来的彩票当钱，导致七百元茅台损失。发现后她在隐瞒侥幸与承担责任间挣扎，不愿同事赔偿，更担心上报后的处分与猜疑，最后想到用个人积蓄补齐钱箱。\",\"turn\":\"一次疲劳失误威胁雨晴积蓄，她决定自行承担七百元损失。\",\"time\":\"2004年圣诞后\",\"people\":[\"苏雨晴\",\"买茅台的顾客\",\"促销员\"],\"objects\":[\"茅台\",\"过期彩票\",\"收银钱箱\",\"三节梯子\"],\"places\":[\"大润发超市酒柜\"]},{\"key\":\"c406\",\"id\":406,\"title\":\"2004 年年末的日常（下）\",\"kind\":\"main\",\"volume\":4,\"start\":1582,\"end\":1585,\"summary\":\"雨晴午休赶回家，从自缝布袋取出七百元补入钱箱，积蓄近减半，整日心疼自责。夕晨察觉她低落，送来昂贵外文复合药物，恰缓解即将缺药的经济焦虑。雨晴感激并决定日后回赠，仍不愿说出失误，早睡不吃晚饭；室友误以为只是身体不适。\",\"turn\":\"失误被私人补足，夕晨的赠药深化信赖，来源仍不明。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"方莜莜\",\"天语遥\",\"胡玉牛\",\"曲奇\"],\"objects\":[\"七百元\",\"自缝存钱布袋\",\"嵌糕\",\"外文复合药物\"],\"places\":[\"出租屋\",\"大润发超市\"]},{\"key\":\"c407\",\"id\":407,\"title\":\"真的好喜欢你\",\"kind\":\"main\",\"volume\":4,\"start\":1586,\"end\":1589,\"summary\":\"年末一天以多组恋情并置：莜莜找工作时与安念互诉依恋；思凡收到孙昊寄来的机械八音盒，听《月光》并相信长久承诺。雨晴差点向夕晨说出喜欢，急以冰淇淋掩饰；天语遥将爱藏心中；阿牛与柳韵在天台相拥，都希望永远相伴。\",\"turn\":\"相似爱语背后各含信任、隐瞒或不安，为命运对照铺垫。\",\"time\":\"2004年12月31日星期五\",\"people\":[\"方莜莜\",\"安念\",\"张思凡\",\"孙昊\",\"苏雨晴\",\"林夕晨\",\"天语遥\",\"夏归月\",\"胡玉牛\",\"柳韵\"],\"objects\":[\"机械八音盒\",\"月光乐曲\",\"巧克力冰淇淋\",\"QQ\"],\"places\":[\"各人房间\",\"街道\",\"小吃店\",\"天台\"]},{\"key\":\"c408\",\"id\":408,\"title\":\"元旦节\",\"kind\":\"main\",\"volume\":4,\"start\":1590,\"end\":1593,\"summary\":\"元旦雨晴写日记改年份，为室友做早餐，回顾八个月里从独自流浪到六人同住的过程。她羡慕天语遥父母支持，却不知对方转变并非自愿。思凡说明公益活动推迟至一月内，谈到为未来接纳而行动的必要；莜莜恢复后也更会与同伴嬉闹。\",\"turn\":\"新年串联合租成员来历，公益募捐延期但继续推进。\",\"time\":\"2005年1月1日星期六；离家八个月\",\"people\":[\"苏雨晴\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"林夕晨\",\"天语遥\",\"曲奇\",\"咖啡\"],\"objects\":[\"日记本\",\"早餐\",\"猫窝设想\"],\"places\":[\"六人合租屋\"]},{\"key\":\"c409\",\"id\":409,\"title\":\"信\",\"kind\":\"main\",\"volume\":4,\"start\":1594,\"end\":1597,\"summary\":\"夕晨收到大姐来信，得知父亲肿瘤需赴城市医院治疗、需要更多钱。她回忆父亲重男轻女却对自己宠爱、三个姐姐早嫁少受教育，既想家又惧怕改变后的身体被发现。她寄出存款五千元、只留一千；在邮局外为治疗费发愁时，接到男人以宝贝相称的西餐邀约。\",\"turn\":\"父病与经济压力具体化，夕晨对外身份和收入隐情渐显。\",\"time\":\"2005年一月；离家近三年\",\"people\":[\"林夕晨\",\"林夕晨大姐\",\"林夕晨父亲\",\"林夕晨母亲\",\"林夕晨三位姐姐\",\"来电男人\"],\"objects\":[\"家书\",\"信封\",\"画纸\",\"五千元寄款\",\"手机\"],\"places\":[\"出租屋\",\"邮局\",\"乡村老家（回忆）\"]},{\"key\":\"c410\",\"id\":410,\"title\":\"被偷东西的超市\",\"kind\":\"main\",\"volume\":4,\"start\":1598,\"end\":1601,\"summary\":\"超市连续三晚遭盗，笔记本样机和名酒丢失，破损员工门与防损值班失察引发不满。王海峰已因长期不公心寒，不再把超市损失当己任。他与陈淑艳仍保护体弱雨晴、互相斗嘴；雨晴坦言若王离职自己也不想留，这份友好关系成为她留职核心。\",\"turn\":\"超市盗案未破；王海峰职业疏离与雨晴的去留相连。\",\"time\":\"连续盗窃第三天\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"防损部主管\",\"超市员工\"],\"objects\":[\"被盗笔记本样机\",\"茅台\",\"员工通道门\",\"高架梯\"],\"places\":[\"大润发超市后仓\",\"酒柜\",\"员工通道\"]},{\"key\":\"c411\",\"id\":411,\"title\":\"青年广场上的爱心传递（上）\",\"kind\":\"main\",\"volume\":4,\"start\":1602,\"end\":1605,\"summary\":\"青年广场公益募捐开场，思凡与知其身份的大学同学子凡搭起偏角小摊，莜莜、夕晨帮忙，孔雀因外出缺席。子凡讨论不能凭外形判断性取向。第一位母亲听明项目后带孩子避开并辱骂，令众人受挫；天语遥随后到场捐一百元，留下协助。\",\"turn\":\"公益行动遭遇公开偏见，但同伴仍守住摊位。\",\"time\":\"2005年一月某晴日上午\",\"people\":[\"张思凡\",\"子凡\",\"方莜莜\",\"林夕晨\",\"天语遥\",\"募捐母子\",\"孔雀\"],\"objects\":[\"雨棚\",\"宣传单\",\"登记本\",\"捐款箱\",\"热水袋\"],\"places\":[\"青年广场\"]},{\"key\":\"c412\",\"id\":412,\"title\":\"青年广场上的爱心传递（中）\",\"kind\":\"main\",\"volume\":4,\"start\":1606,\"end\":1609,\"summary\":\"雨晴获王海峰允许延长午休，到青年广场寻找同伴。拥挤的人群、以受创儿童博取同情的展示令她强烈反感，并投射出对自身未来的恐惧。大雨中她找到仅天语遥留守的摊位，海边别墅大小姐和女仆也来避雨，雨晴担心被认出而避开目光。\",\"turn\":\"雨晴对被怜悯、被展示的反感加深；大小姐再度进入故事。\",\"time\":\"活动当日午间下雨\",\"people\":[\"苏雨晴\",\"王海峰\",\"天语遥\",\"被展示的残障儿童\",\"雯雯\",\"大小姐女仆\"],\"objects\":[\"手机\",\"公益海报\"],\"places\":[\"大润发超市\",\"青年广场\"]},{\"key\":\"c413\",\"id\":413,\"title\":\"青年广场上的爱心传递（下）\",\"kind\":\"main\",\"volume\":4,\"start\":1610,\"end\":1613,\"summary\":\"女仆阅读性别相关募捐传单后发问，雨晴因长期偏见经验而误以为将受羞辱。天语遥勉强解释援助目的，女仆实际捐出两百元，大小姐亦默默捐约一两千元。雨晴随后捐一百元，在登记性别栏填男，并借思凡黑伞离开；他人的善意与她的戒备构成反差。\",\"turn\":\"大小姐主仆实际援助；雨晴仍受身份暴露与自我认定困扰。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"天语遥\",\"雯雯\",\"大小姐女仆\"],\"objects\":[\"宣传单\",\"登记本\",\"捐款箱\",\"黑色雨伞\"],\"places\":[\"青年广场募捐摊\"]},{\"key\":\"c414\",\"id\":414,\"title\":\"莫空捐赠的折扣券\",\"kind\":\"main\",\"volume\":4,\"start\":1614,\"end\":1617,\"summary\":\"思凡与子凡接手摊位，莜莜不适返家、夕晨临时有事离去。莫空前来读海报，注意雨晴登记的性别，捐入一张女人之家高级VIP一折券后离开且未署名。思凡把限购五件的券收入自己口袋。全天募得两千多元，却多遭辱骂与带矫正意味的同情，活动标语显得讽刺。\",\"turn\":\"公益只获有限款项；折扣券由思凡保存，集体受到现实冲击。\",\"time\":\"活动当日下午至收摊\",\"people\":[\"张思凡\",\"子凡\",\"莫空\",\"苏雨晴\",\"方莜莜\",\"林夕晨\"],\"objects\":[\"女人之家一折券\",\"登记本\",\"捐款箱\",\"豆腐干\"],\"places\":[\"青年广场\"]},{\"key\":\"c415\",\"id\":415,\"title\":\"暂别\",\"kind\":\"main\",\"volume\":4,\"start\":1618,\"end\":1621,\"summary\":\"一月底春节将至，天语遥、思凡、莜莜陆续回家，阿牛也计划返村，只剩雨晴与夕晨留守。莜莜因父亲继母和好而回去团圆，穿男装掩饰变化，雨晴担心她不再回来。两人与莜莜在火车站道别，她承诺节后回来，并鼓励两人感情；成对围巾随行。\",\"turn\":\"六人分散返乡，雨晴与夕晨将独自共度第一个离家春节。\",\"time\":\"2005年一月底\",\"people\":[\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"张思凡\",\"天语遥\",\"胡玉牛\",\"方莜莜父亲与继母\"],\"objects\":[\"火车票\",\"行李\",\"狐尾围巾\",\"白猫围巾\"],\"places\":[\"合租屋\",\"小城市火车站\"]},{\"key\":\"c416\",\"id\":416,\"title\":\"临近\",\"kind\":\"main\",\"volume\":4,\"start\":1622,\"end\":1626,\"summary\":\"除夕前最后晚班，周超透露自己是职高实习班学生，计划暑假前离职学面点、奶茶或做销售；王海峰也准备同期走，雨晴尚未确定下一工作。阿牛与雨晴下班同行，她羡慕他能回家，他反羡慕她断开家庭束缚；被问是否向柳韵坦白或停药，他仍无法决定。\",\"turn\":\"就业转折临近；阿牛对关系与转变的逃避持续。\",\"time\":\"2005年2月7日，除夕前一天\",\"people\":[\"苏雨晴\",\"周超\",\"王海峰\",\"胡玉牛\",\"张燕\",\"姚玲\"],\"objects\":[\"货架\",\"促销商品\"],\"places\":[\"大润发超市\",\"回家街道\"]},{\"key\":\"c417\",\"id\":417,\"title\":\"除夕（一）\",\"kind\":\"main\",\"volume\":4,\"start\":1627,\"end\":1630,\"summary\":\"除夕清晨雨晴发现夕晨睡在沙发，担心着凉并费力抱她回房，夕晨却没有不适。冰箱食材已空，雨晴决定与她去思凡的郊外集装箱房过年。两人采购米菜、水果、烟花和春联，带曲奇咖啡搭公交至农村终点，再雇三轮车去花芯村后森林前。\",\"turn\":\"雨晴主动为两人建立过年仪式，离开城中喧闹寻找安宁。\",\"time\":\"2005年除夕清晨\",\"people\":[\"苏雨晴\",\"林夕晨\",\"曲奇\",\"咖啡\",\"三轮车司机\"],\"objects\":[\"食材\",\"烟花\",\"春联\",\"薄毯\"],\"places\":[\"合租屋\",\"街市\",\"公交车\",\"花芯村路口\"]},{\"key\":\"c418\",\"id\":418,\"title\":\"除夕（二）\",\"kind\":\"main\",\"volume\":4,\"start\":1631,\"end\":1634,\"summary\":\"雨晴与三轮车司机议价后抵达集装箱房，整理住处、晒被，宠物与乡间狗群游玩。午间她因思念父母而哭，夕晨拥抱安抚，使她重新振作。两人合作准备年夜饭，雨晴耐心教不会下厨的夕晨，户外桌上摆家常菜与酸菜鱼，也为宠物留食。\",\"turn\":\"乡愁被理解承接，两人以照料和共同劳动建立家庭感。\",\"time\":\"除夕中午至夜晚\",\"people\":[\"苏雨晴\",\"林夕晨\",\"曲奇\",\"咖啡\",\"三轮车司机\"],\"objects\":[\"棉被\",\"嵌糕\",\"移动灶炉\",\"酸菜鱼\"],\"places\":[\"郊外集装箱房\"]},{\"key\":\"c419\",\"id\":419,\"title\":\"除夕（三）\",\"kind\":\"main\",\"volume\":4,\"start\":1635,\"end\":1638,\"summary\":\"雨晴与夕晨在烟花下举杯迎年，夕晨默默为她夹好菜。另一线阿牛离开全村年夜饭，借摩托去接柳韵；她大胆提议翻墙进入关闭的游乐园。二人体验无人园区的刺激与私密，坐上停摆海盗船看星空，柳韵遗憾无月亮见证爱情。\",\"turn\":\"两段不同约会并置，柳韵的月亮爱情观成为后续意象。\",\"time\":\"除夕夜\",\"people\":[\"苏雨晴\",\"林夕晨\",\"胡玉牛\",\"柳韵\",\"胡玉牛母亲\",\"柳韵父母\"],\"objects\":[\"饮料杯\",\"摩托车\",\"海盗船\"],\"places\":[\"集装箱房\",\"阿牛村\",\"柳韵家\",\"夜间游乐园\"]},{\"key\":\"c420\",\"id\":420,\"title\":\"除夕（四）\",\"kind\":\"main\",\"volume\":4,\"start\":1639,\"end\":1642,\"summary\":\"午夜烟花齐放，雨晴邀夕晨笑，夕晨举起新年快乐横批并真诚微笑。雨晴趁烟火巨响喊出喜欢，却不能确定她是否听见，未获直接回答。两人继续燃放烟花，雨晴想起童年、感叹长大；困倦饮酒后被夕晨抱回床陪伴，夕晨直到天亮才入睡。\",\"turn\":\"雨晴第一次喊出爱意，关系即将从暗恋转为明说。\",\"time\":\"除夕午夜至正月初一清晨\",\"people\":[\"苏雨晴\",\"林夕晨\"],\"objects\":[\"烟花\",\"新年快乐横批\",\"火花棒\",\"啤酒\",\"电视春晚\"],\"places\":[\"郊外集装箱房\"]},{\"key\":\"c421\",\"id\":421,\"title\":\"大年初一（上）\",\"kind\":\"main\",\"volume\":4,\"start\":1643,\"end\":1646,\"summary\":\"两人睡到大年初一傍晚才醒，夕晨少见地自然微笑、流畅说话。雨晴问新年愿望，夕晨让她感受心跳，并明确说愿望是和她在一起。雨晴惊喜确认这是真实发生，两人相拥认定爱情，不再执着谁扮男方女方；随后起床热年夜饭剩菜、喂等了一天的宠物。\",\"turn\":\"主角情侣正式互通心意，这是现实中的确认关系。\",\"time\":\"2005年正月初一傍晚\",\"people\":[\"苏雨晴\",\"林夕晨\",\"曲奇\",\"咖啡\"],\"objects\":[\"空调遥控器\",\"剩菜\"],\"places\":[\"郊外集装箱房\"]},{\"key\":\"c422\",\"id\":422,\"title\":\"大年初一（下）\",\"kind\":\"main\",\"volume\":4,\"start\":1647,\"end\":1650,\"summary\":\"返乡的天语遥看雪想念夏归月，也回忆兄弟们的愿望，承认旧日选择带来伤痛。她仍打算年后报复再结束生命，却又割舍不下爱情。与归月跨省通话时，她终于说想念；归月期待做她新娘、催她早回，两人互唱《水调歌头》，暂时驱散她的压抑。\",\"turn\":\"爱情暂缓自毁情绪却未改计划；返乡地理与前文存在矛盾。\",\"time\":\"2005年大年初一\",\"people\":[\"天语遥\",\"夏归月\",\"老二\",\"老三\",\"老四\",\"邻居老大爷\"],\"objects\":[\"手机\",\"二锅头\",\"水调歌头\",\"猴头菇饼干\"],\"places\":[\"天语遥返乡住处\"]},{\"key\":\"c423\",\"id\":423,\"title\":\"艳阳高照\",\"kind\":\"main\",\"volume\":4,\"start\":1651,\"end\":1654,\"summary\":\"正月初五，雨晴与夕晨吃完集装箱房剩余食材，带曲奇返城。确定恋情后雨晴觉得世界明亮起来，围栏裂缝里萌出的嫩芽呼应她的希望。乡间哈士奇追随曲奇送到车站，两人回到尚无室友返回、已经积灰的公寓。莜莜来电说带着大批家乡特产即将到站，邀请她们接站分享年味。\",\"turn\":\"恋情使雨晴重新产生希望，假期结束、室友即将陆续重聚。\",\"time\":\"2005年正月初五\",\"people\":[\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"曲奇\",\"乡间哈士奇\"],\"objects\":[\"年夜食材\",\"木围栏\",\"嫩芽\",\"麻糕\",\"面窝\",\"麻糖\",\"太极饼\"],\"places\":[\"集装箱房\",\"乡间公交总站\",\"六室合租公寓\",\"菜市场\"]},{\"key\":\"c424\",\"id\":424,\"title\":\"张思凡对阵熊孩子\",\"kind\":\"main\",\"volume\":4,\"start\":1655,\"end\":1658,\"summary\":\"思凡在老家仍隐瞒身份。顽皮小表弟来访，她担心收藏被毁，带一群孩子到村里玩雪地捉迷藏。两个小时后才发现小表弟偷偷回屋，趁大人纵容损坏高达与美少女战士模型、小霸王游戏机和新买的PSP。她愤怒地打孩子屁股，却被母亲和亲戚指责不该为玩具较真。\",\"turn\":\"珍爱收藏被毁且家长偏袒小孩，思凡与母亲的矛盾急剧升级。\",\"time\":\"2005年春节返乡期间\",\"people\":[\"张思凡\",\"思凡母亲\",\"小表弟\",\"表舅家亲属\",\"大黄狗\"],\"objects\":[\"高达模型\",\"美少女战士手办\",\"红色扎古\",\"小霸王游戏机\",\"PSP\"],\"places\":[\"思凡老家\",\"村庄雪地\"]},{\"key\":\"c425\",\"id\":425,\"title\":\"负气\",\"kind\":\"main\",\"volume\":4,\"start\":1659,\"end\":1662,\"summary\":\"母亲又要求将思凡花一个月制作的限量高达送给小表弟，孩子当面摔坏它。思凡愤怒毁掉剩余收藏和电脑显示器，负气离家乘车返城，打算毕业后接受去势手术。列车上，她先梦见与孙昊相守、收养孩子的晚年，又梦见父母拒绝和恋人背叛；醒后仍选择相信孙昊。叙述补明父母正在向表舅借创业款，偏袒孩子为保借款，争执使原许诺十万降至三万，思凡并不知情。\",\"turn\":\"亲子双方都感委屈且信息不通，幸福婚姻和遭弃仅是两段梦境。\",\"time\":\"2005年春节返乡期间\",\"people\":[\"张思凡\",\"思凡父母\",\"小表弟\",\"表舅\",\"孙昊\"],\"objects\":[\"限量高达\",\"模型收藏\",\"电脑显示器\",\"行李\",\"开店借款\"],\"places\":[\"思凡老家\",\"返城火车\",\"小城火车站\"]},{\"key\":\"c426\",\"id\":426,\"title\":\"神秘的包裹\",\"kind\":\"main\",\"volume\":4,\"start\":1663,\"end\":1666,\"summary\":\"莜莜回到公寓分家乡点心，感慨父亲和继母有了孩子后疏远自己；思凡也负气归来，向室友诉说亲子冲突。顺丰送来一个没有寄件地址的大包裹，内有雨晴童年爱吃的进口零食、合身衣鞋、抱枕和昂贵SD娃娃。众人猜是她父母所寄，雨晴口头否认父母知道住处，心里却渴望获得他们的接纳，抱着礼物哭着想回家。\",\"turn\":\"神秘寄件人尚未查明，礼物唤起雨晴对父母接纳的期待。\",\"time\":\"2005年春节假期结束、正月初五前后\",\"people\":[\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"张思凡\",\"顺丰快递员\",\"莜莜父亲\",\"方莜莜继母\"],\"objects\":[\"神秘包裹\",\"太极饼\",\"进口零食\",\"衣鞋\",\"抱枕\",\"毛绒玩具\",\"SD娃娃\"],\"places\":[\"六室合租公寓\"]},{\"key\":\"c427\",\"id\":427,\"title\":\"讽刺和还击\",\"kind\":\"main\",\"volume\":4,\"start\":1667,\"end\":1670,\"summary\":\"春节返乡后，天语遥到旧帮会与黄枸帮会共用的小巷，怀念初见夏归月的时刻，向流浪大黑狗倾诉。两名混混辱骂她的身体变化，她凭旧日打架经验迅速反击，随后克制了进一步造成严重伤害的冲动。外表与体力改变并未消除她维护尊严的强硬，内心却开始察觉自己不愿让别人重受同样的痛苦。\",\"turn\":\"她能克制当下报复冲动，针对胡玉牛的长期仇恨却仍未化解。\",\"time\":\"2005年春节后\",\"people\":[\"天语遥\",\"夏归月\",\"黑皇\",\"两名挑衅混混\"],\"objects\":[\"宽大外套\",\"帽子\"],\"places\":[\"废弃小巷\"]},{\"key\":\"c428\",\"id\":428,\"title\":\"抱着我\",\"kind\":\"main\",\"volume\":4,\"start\":1671,\"end\":1674,\"summary\":\"天语遥陪夏归月游百流山，讨论身体与心灵的自由。她本想照顾恋人，却因体力衰退反被夏归月拉上山；两人参观供奉叶祖的旧庙，谈起族谱和历史。夏归月信任她会守护自己，天语遥却暗认自己不配、准备离开，忍着泪请求对方紧抱不放，归月虽不知缘由仍温柔回应。\",\"turn\":\"共享山顶亲密时刻，天语遥单方面安排离别而夏归月尚不知情。\",\"time\":\"2005年春节后\",\"people\":[\"天语遥\",\"夏归月\",\"叶祖\"],\"objects\":[\"围巾\",\"叶祖塑像\",\"族谱\"],\"places\":[\"百流山\",\"山顶旧庙\"]},{\"key\":\"c429\",\"id\":429,\"title\":\"她最喜欢的是什么呢？\",\"kind\":\"main\",\"volume\":4,\"start\":1675,\"end\":1678,\"summary\":\"新年上班后，雨晴发现胡玉牛将调往更辛苦、待遇较高的退货部，两人与其他室友日渐疏远。她认真检查保质期、午间用奶油蛋糕犒劳自己，在食堂偶遇阿牛。谈到情人节礼物，她问柳韵最喜欢什么，阿牛竟答不出来，只能继续困惑自己是否了解恋人、是否爱得足够深。\",\"turn\":\"室友间距离扩大；一个礼物问题促使阿牛检视恋爱中的不了解。\",\"time\":\"2005年春节后、情人节将近\",\"people\":[\"苏雨晴\",\"胡玉牛\",\"柳韵\",\"王海峰\",\"员工通道看门女员工\"],\"objects\":[\"奶油蛋糕\",\"电视手机\",\"情人节礼物\"],\"places\":[\"超市货架区\",\"超市员工餐厅\",\"超市退货部\"]},{\"key\":\"c430\",\"id\":430,\"title\":\"外国人\",\"kind\":\"main\",\"volume\":4,\"start\":1679,\"end\":1682,\"summary\":\"雨晴用有限英语帮助一名外国女顾客找中国白酒，交流遇阻后请王海峰协助，终于弄清对方要整箱二锅头。她因此想起父母对移居海外的不同看法，也向往更能接纳自己的生活。促销员借口补货把检查保质期留给她，陈淑艳为她不平；雨晴不愿引起争执，婉拒替自己出头，维持平静工作。\",\"turn\":\"工作应对能力增强，但雨晴仍以退让回避同事间的利益冲突。\",\"time\":\"2005年春节后\",\"people\":[\"苏雨晴\",\"王海峰\",\"外国女顾客\",\"陈淑艳\",\"炒货促销员\",\"苏雨晴父母\"],\"objects\":[\"二锅头\",\"商品保质期标签\"],\"places\":[\"超市酒柜\",\"炒货货架\"]},{\"key\":\"c431\",\"id\":431,\"title\":\"计划开始\",\"kind\":\"main\",\"volume\":4,\"start\":1683,\"end\":1686,\"summary\":\"阴冷独处的一天，天语遥决定正式实施报复，不再顾虑证据会连带伤害室友。她检查两套照片以及标名的针筒、药盒和隔门录音，联络老三次日到初见之处帮最后一次忙，并冷淡拒谈帮会近况。老三忆起小学受欺负时被她带领反抗，既忠诚又心痛，感到昔日关系正在消散。\",\"turn\":\"报复从搜集资料进入实施，天语遥明确不顾对共同居住者的波及。\",\"time\":\"2005年春节后、某星期五\",\"people\":[\"天语遥\",\"老三\",\"老二\",\"胡玉牛\"],\"objects\":[\"证据信封\",\"照片\",\"针筒\",\"药盒\",\"录音器\"],\"places\":[\"六室合租公寓\",\"老三住处\"]},{\"key\":\"c432\",\"id\":432,\"title\":\"冷笑\",\"kind\":\"main\",\"volume\":4,\"start\":1687,\"end\":1690,\"summary\":\"天语遥想象报复后退出夏归月的生活，又反复否定两人长久相守的可能，以为离开才是替她着想。独处时遇见胡玉牛，她用冷笑回应歉意，暗示对方会感谢自己。她决定数日不见归月，以免动摇。阿牛则接柳韵放学，掩饰肌肉变化，应邀到柳家做饭留宿，不知危机已逼近。\",\"turn\":\"阿牛误以为旧怨已解，天语遥借主动断联维持报复与离别决心。\",\"time\":\"同c431的星期五\",\"people\":[\"天语遥\",\"胡玉牛\",\"夏归月\",\"柳韵\"],\"objects\":[\"电视\",\"手机\"],\"places\":[\"六室合租公寓\",\"小城第一高中校门\"]},{\"key\":\"c433\",\"id\":433,\"title\":\"意乱情迷\",\"kind\":\"main\",\"volume\":4,\"start\":1691,\"end\":1694,\"summary\":\"阿牛在柳韵家做土豆饼和红豆粥，两人在厨房共进温暖晚餐。他对继续身体转变与承担恋爱责任仍犹豫，甚至怀疑自己的身份愿望是否含有逃避；但柳韵主动亲近使两人关系进一步发展。他沉浸在相守的想象里，仍未向她坦白用药与内心矛盾，也尚未作出承诺所需要的选择。\",\"turn\":\"亲密关系进一步发展，却没有解决身份隐瞒、责任与未来选择。\",\"time\":\"同c432夜晚\",\"people\":[\"胡玉牛\",\"柳韵\"],\"objects\":[\"土豆饼\",\"红豆粥\"],\"places\":[\"柳韵家\"]},{\"key\":\"c434\",\"id\":434,\"title\":\"去办事\",\"kind\":\"main\",\"volume\":4,\"start\":1695,\"end\":1698,\"summary\":\"老三在旧城区麦当劳后的小区等候天语遥，那里是她当年救他并请吃甜筒的地方。她交付证据，要求查明柳韵住址再伪装快递送达，并明确不再回归帮会。老三完成跟踪，确认柳家在五〇二室；想到帮会从五六十人散至约十人、自己多年忽略父母期待，他重新记起儿时做木匠的理想。\",\"turn\":\"证据送达前准备完成；老三在团体瓦解中开始思考退出混混生活。\",\"time\":\"c431通话的次日\",\"people\":[\"天语遥\",\"老三\",\"柳韵\",\"胡玉牛\"],\"objects\":[\"证据信封\",\"人物照片\",\"甜筒\",\"手机门牌记录\"],\"places\":[\"旧城区世纪联华超市\",\"麦当劳后小区\",\"小城第一高中\",\"柳韵家五〇二室\"]},{\"key\":\"c435\",\"id\":435,\"title\":\"林欲静而风不止\",\"kind\":\"main\",\"volume\":4,\"start\":1699,\"end\":1702,\"summary\":\"初八上班时，思凡因返乡冲突和孙昊背叛的噩梦无心工作，身旁友善女同事替她完成文稿。下班后母亲来电话叮嘱加衣，未责怪她负气离家；她感受到父母牵挂，也为隐瞒身份内疚，原定暑假手术的决心再度摇摆。一路思绪纷乱走错楼，才暂时决定用游戏与电视转移注意。\",\"turn\":\"亲子电话修补春节冲突，却强化思凡对自我选择与父母期待的两难。\",\"time\":\"2005年正月初八\",\"people\":[\"张思凡\",\"思凡母亲\",\"思凡父亲\",\"思凡女同事\",\"孙昊\",\"走错门中年女住户\"],\"objects\":[\"Word文稿\",\"手机\",\"大毛衣\"],\"places\":[\"思凡实习公司\",\"回家路\",\"合租公寓相邻楼\"]},{\"key\":\"c436\",\"id\":436,\"title\":\"神秘的信封\",\"kind\":\"main\",\"volume\":4,\"start\":1703,\"end\":1706,\"summary\":\"老三伪装快递将天语遥的匿名证据送给柳韵。柳逐一查看照片、药盒、针筒与录音，再对照网上信息及阿牛的身体变化，确认对方隐瞒了转变愿望。带有污名与猜测的信激起她愤怒，女装照尤其令她排斥；她想以向众人揭露来报复，隐住情绪发短信约阿牛次日见面。\",\"turn\":\"柳韵知道隐瞒真相却受恶意信件引导，报复链条开始扩散。\",\"time\":\"跟踪住址的次日\",\"people\":[\"柳韵\",\"老三\",\"天语遥\",\"胡玉牛\"],\"objects\":[\"匿名信\",\"证据照片\",\"女装照片\",\"针筒\",\"药盒\",\"录音笔\",\"短信\"],\"places\":[\"柳韵家\"]},{\"key\":\"c437\",\"id\":437,\"title\":\"我们去见你父母吧\",\"kind\":\"main\",\"volume\":4,\"start\":1707,\"end\":1710,\"summary\":\"柳韵在学校表现出班级大姐头的强势，与阿牛面前的温顺判若两人。校门口莫空劝阿牛立即离开恋人以避祸，阿牛不明所以仍等候。柳见到他的真诚后内心软化，开始承认自己真的爱他，又受到既有偏见牵制。她仍按预谋提出见阿牛父母，是否继续揭露却已犹疑。\",\"turn\":\"柳韵并非纯粹利用恋人，真情与偏见冲突，原定报复开始动摇。\",\"time\":\"c436的次日放学\",\"people\":[\"柳韵\",\"胡玉牛\",\"莫空\",\"柳韵男同学\"],\"objects\":[\"巧克力\",\"手机\",\"香烟\"],\"places\":[\"小城第一高中\",\"校门口\"]},{\"key\":\"c438\",\"id\":438,\"title\":\"胡玉牛父母的款待\",\"kind\":\"main\",\"volume\":4,\"start\":1711,\"end\":1714,\"summary\":\"阿牛带柳韵坐公交回近郊村庄，父母惊喜迎接，生火取暖、加菜款待，关心这个十七岁的女孩。柳被他们的淳朴热情与阿牛的体贴打动，觉得揭露隐私拆散家庭过于残忍，最终没有实施计划。可她脱下外衣时，装有证据的信无意滑进灶旁柴堆，离开时也没有察觉。\",\"turn\":\"柳韵主动放弃报复，证据信件却意外留在胡家，危机仍在。\",\"time\":\"c437当日晚间\",\"people\":[\"胡玉牛\",\"柳韵\",\"胡玉牛父母\",\"老刘\"],\"objects\":[\"匿名证据信封\",\"外衣\",\"柴火\",\"海鱼\",\"荞麦烧酒\"],\"places\":[\"胡玉牛老家村庄\",\"胡家厨房\"]},{\"key\":\"c439\",\"id\":439,\"title\":\"坐看风起云涌\",\"kind\":\"main\",\"volume\":4,\"start\":1715,\"end\":1718,\"summary\":\"柳韵逃课来到湖心废弃公园，重访被阿牛拒绝后又因他留下外衣而重燃希望的地点。她想不清该如何面对恋人的转变与自己的感情，对阿牛的接人短信反复犹疑。一个似流浪汉的沧桑男子坐旁看云，给她香烟，离去前提醒互相坦白才能解决问题；她回头时对方已经不见。\",\"turn\":\"逃避未能理清情绪，陌生男子的劝告把解决方向指向双方坦白。\",\"time\":\"拜访胡家后的某日下午\",\"people\":[\"柳韵\",\"胡玉牛\",\"沧桑男子\"],\"objects\":[\"石桌\",\"曾披上的外衣\",\"红梅烟盒\",\"女士香烟\",\"接人短信\"],\"places\":[\"湖心废弃公园\"]},{\"key\":\"c440\",\"id\":440,\"title\":\"被发现的信\",\"kind\":\"main\",\"volume\":4,\"start\":1719,\"end\":1722,\"summary\":\"胡父难得主动做饭，与妻子回忆旧情，也反思把振兴家族的理想强加给儿子。胡母在柴堆发现柳韵的信，胡父坚持不看别人隐私，暂放桌上待归还。另一边柳韵已想起遗失信件，担心阿牛误会，推测送信人是曾被阿牛打伤的混混，觉察自己被借来报复，决意向阿牛坦白寻求办法。\",\"turn\":\"父亲的隐私原则暂时保住秘密；柳韵立场转向保护阿牛并反思报复者。\",\"time\":\"拜访胡家后的某日下午\",\"people\":[\"胡玉牛父母\",\"胡玉牛\",\"柳韵\",\"天语遥\",\"老刘\",\"胡父发小\"],\"objects\":[\"证据信封\",\"南瓜饼\",\"柴火\",\"日历\"],\"places\":[\"胡玉牛老家\",\"柳韵家\"]},{\"key\":\"c441\",\"id\":441,\"title\":\"不孝之子\",\"kind\":\"main\",\"volume\":4,\"start\":1723,\"end\":1726,\"summary\":\"夜里胡母下楼喝水碰落桌上的信，收拾时发现阿牛的就诊与女装照片，惊慌带给丈夫。胡父起初仍反对窥私，最终为查明儿子的事读信，因用药转变而震怒，立刻电话勒令阿牛返家。阿牛在雨晴关心的目送下赶末班公交，忐忑猜测秘密是否暴露，穿过黑暗山路回到仍亮灯的家。\",\"turn\":\"意外落信打破此前的隐私保护，父母得知秘密并召回阿牛对质。\",\"time\":\"c440当夜九点以后\",\"people\":[\"胡玉牛\",\"胡玉牛父母\",\"苏雨晴\"],\"objects\":[\"十二寸彩电\",\"证据信封\",\"女装照片\",\"针筒\",\"药盒\",\"录音笔\",\"手机\"],\"places\":[\"胡玉牛老家\",\"六室合租公寓\",\"郊区末班公交\"]},{\"key\":\"c442\",\"id\":442,\"title\":\"回不去了\",\"kind\":\"main\",\"volume\":4,\"start\":1727,\"end\":1730,\"summary\":\"阿牛见到父母拿出的证据，推断天语遥搜集材料，却错误认定柳韵与其串通故意留信。面对追问，他首次向父亲说出振兴家族重担令自己窒息；父亲自责，答应不再要求传承事业，父母劝他恢复旧日生活。阿牛仍承认如今真想做女人，哭着道歉跑出村庄。父亲无力颓坐，他则在山路放声哭泣，感到内疚而无处安放自己。\",\"turn\":\"父亲撤去家族重担仍不能化解身份冲突，阿牛误认恋人合谋，家庭陷入裂痕。\",\"time\":\"c441当夜\",\"people\":[\"胡玉牛\",\"胡玉牛父母\",\"柳韵\",\"天语遥\"],\"objects\":[\"证据信封\",\"证据照片\"],\"places\":[\"胡玉牛老家\",\"山间小路\"]},{\"key\":\"c443\",\"id\":443,\"title\":\"逃避再逃避\",\"kind\":\"main\",\"volume\":4,\"start\":1731,\"end\":1735,\"summary\":\"阿牛深夜回到公寓，得知天语遥已搬走；他未向莜莜说明遭遇，继续在误会与自责中辗转难眠。柳韵短信约次日下午河边谈话，他仍猜忌这是圈套。次日无心上班，父亲又来电劝他放弃转变，争执从撤去重担再滑向家族传承，最终以不再认他为儿子的气话挂断，令阿牛更加绝望。\",\"turn\":\"天语遥撤离现场，阿牛孤立加深，父子电话从劝返演变成断绝关系。\",\"time\":\"c442深夜至次日中午\",\"people\":[\"胡玉牛\",\"方莜莜\",\"胡玉牛父亲\",\"柳韵\",\"天语遥\"],\"objects\":[\"河边邀约短信\",\"父亲电话\"],\"places\":[\"六室合租公寓\"]},{\"key\":\"c444\",\"id\":444,\"title\":\"恩怨情仇\",\"kind\":\"main\",\"volume\":4,\"start\":1736,\"end\":1739,\"summary\":\"河边会面时，柳韵解释曾想报复却已后悔，信只是意外遗失；阿牛不信，指责她与天语遥合谋，并用伤人的话否定两人的感情。柳批评他的隐瞒与迁怒，仍盼他听进解释，甚至想过若他确实认同女性可转为姐妹。阿牛没有叫住缓慢离开的她，只在愤恨中辱骂与哭泣，两人关系破裂。\",\"turn\":\"解释失败导致分手；柳韵留下关系修复的可能，阿牛未能回应。\",\"time\":\"c443次日下午四点半至五点后\",\"people\":[\"胡玉牛\",\"柳韵\"],\"objects\":[\"邀约短信\",\"河边树木\"],\"places\":[\"超市附近小河\"]},{\"key\":\"c445\",\"id\":445,\"title\":\"转交给胡玉牛\",\"kind\":\"main\",\"volume\":4,\"start\":1740,\"end\":1743,\"summary\":\"天语遥为保证报复奏效，另准备写明雌性激素的包裹来到超市后仓，将其交给爱传闲话的促销员，嘱转交阿牛。她算准同事好奇与偏见会扩大影响，满意离开。促销员向同伴打听药物用途，议论迅速从猜测发散成对阿牛身份、身体和手术的荒谣，令工作场所也成为公开羞辱的来源。\",\"turn\":\"第二条报复渠道发动，隐私被用于制造职场排斥且谣言失去事实边界。\",\"time\":\"阿牛未上班的当日晚间\",\"people\":[\"天语遥\",\"胡玉牛\",\"狭眼促销员\",\"超市议论员工\",\"出租车司机\"],\"objects\":[\"标注雌性激素的包裹\",\"快递单\",\"电子烟\"],\"places\":[\"大润发超市后仓入口\",\"出租车\"]},{\"key\":\"c446\",\"id\":446,\"title\":\"人言可畏\",\"kind\":\"main\",\"volume\":4,\"start\":1744,\"end\":1747,\"summary\":\"阿牛把饭桌普通谈笑感为嘲讽，突然摔碗回房。室友担心他与柳韵出事，决定次晨询问，却只得到没事的回答。上班时主管宽容地将前日缺勤改作调休，周围员工态度却因谣言改变。促销员当众递给他标着雌性激素的包裹，阿牛震惊，旁人进一步把他的反应当作证实，心理防线濒临崩溃。\",\"turn\":\"室友帮助未获回应，工作场所公开递包裹加剧羞辱与孤立。\",\"time\":\"c445当夜至次日下午\",\"people\":[\"胡玉牛\",\"苏雨晴\",\"方莜莜\",\"张思凡\",\"林夕晨\",\"胡玉牛主管\",\"狭眼促销员\"],\"objects\":[\"饭碗\",\"白色发卡\",\"雌性激素包裹\"],\"places\":[\"六室合租公寓\",\"超市后仓\"]},{\"key\":\"c447\",\"id\":447,\"title\":\"世界崩坏\",\"kind\":\"main\",\"volume\":4,\"start\":1748,\"end\":1751,\"summary\":\"阿牛试图保持冷静，却在议论中喊出否认，反而招来更多注视与传闻。他失控逃出超市，跑到山腰破亭独自发泄，双手受伤；回公寓时忘带钥匙，在门前站到思凡下班开门。众人被他痛苦而激动的状态吓住，虽不了解全貌，仍决定隔门劝慰，试着让他别再独自压住困境。\",\"turn\":\"公开羞辱引发急剧危机，阿牛受伤退回封闭房间，室友尚不知原因。\",\"time\":\"c446当日下午至晚间\",\"people\":[\"胡玉牛\",\"张思凡\",\"方莜莜\",\"苏雨晴\",\"超市员工\",\"面包车司机\"],\"objects\":[\"工作服\",\"留在寄存柜的钥匙\",\"茅草亭木柱\"],\"places\":[\"大润发超市\",\"十字路口\",\"山腰茅草亭\",\"六室合租公寓\"]},{\"key\":\"c448\",\"id\":448,\"title\":\"好梦\",\"kind\":\"main\",\"volume\":4,\"start\":1752,\"end\":1755,\"summary\":\"莜莜、思凡和雨晴隔门劝阿牛说出难处，他始终不回应；她们只能暂停，夕晨画出月亮与奇异降雨后将画撕碎。阿牛独处时反省自己的隐瞒、误会与逃避，却认定已经太迟，向柳韵和父母发去语序混乱的致谢短信，随后严重自伤。他在意识模糊中曾后悔放弃希望，此时无人知道房内发生了什么。\",\"turn\":\"多重打击与孤立发展成自伤危机，含混短信成为外界得知危险的线索。\",\"time\":\"c447当夜\",\"people\":[\"胡玉牛\",\"方莜莜\",\"张思凡\",\"苏雨晴\",\"林夕晨\",\"柳韵\",\"胡玉牛父母\"],\"objects\":[\"致谢短信\",\"白酒\",\"药瓶\",\"撕碎的月亮抽象画\"],\"places\":[\"六室合租公寓\"]},{\"key\":\"c449\",\"id\":449,\"title\":\"不知道是谁的坟\",\"kind\":\"main\",\"volume\":4,\"start\":1756,\"end\":1759,\"summary\":\"雨晴不安入睡，梦中荒废公园进一步崩坏，小男孩坐秋千，出现无名坟与排列成鹰形的墓园；梦境带来死亡预感。次晨室友照常生活，以为阿牛早已出门，反复响起的房内电话也被当作忘带手机。直到中午，衣着匆忙的柳韵冲到公寓急问阿牛，拨号确认声音来自紧闭卧室。\",\"turn\":\"习惯性的缺席掩盖异常，柳韵赶来才打破室友对阿牛已外出的误判。\",\"time\":\"c448当夜至次日星期六中午\",\"people\":[\"苏雨晴\",\"梦中小男孩\",\"曲奇\",\"咖啡\",\"方莜莜\",\"张思凡\",\"柳韵\",\"胡玉牛\"],\"objects\":[\"无名墓碑\",\"秋千\",\"鹰形墓园\",\"手机\",\"苹果派\",\"纸杯鼠窝\"],\"places\":[\"雨晴梦中荒废公园\",\"梦中墓园\",\"六室合租公寓\"]},{\"key\":\"c450\",\"id\":450,\"title\":\"永远的安眠\",\"kind\":\"main\",\"volume\":4,\"start\":1760,\"end\":1763,\"summary\":\"柳韵急催开门，莜莜找出备用钥匙后，众人发现阿牛倒在房内仍有微弱呼吸。雨晴拨急救电话，思凡说明情况，莜莜与柳韵随救护车送医，其余人赶往医院；最终抢救无效，医生宣布阿牛死亡。柳韵向大家说明匿名信与旧怨，她们才知道天语遥潜伏报复。众人通知父母并配合笔录，雨晴夕晨因证件与身份顾虑避开询问。\",\"turn\":\"胡玉牛抢救无效身亡，报复链条才为室友所知，幸存者进入悲痛与追问。\",\"time\":\"c449星期六中午后\",\"people\":[\"胡玉牛\",\"柳韵\",\"方莜莜\",\"张思凡\",\"苏雨晴\",\"林夕晨\",\"急救人员\",\"医院医生\",\"警察\",\"胡玉牛父母\"],\"objects\":[\"备用钥匙\",\"手机\",\"救护车\",\"药瓶\",\"酒瓶\"],\"places\":[\"六室合租公寓\",\"救护车\",\"医院急诊室\",\"警察局\"]},{\"key\":\"c451\",\"id\":451,\"title\":\"白发人送黑发人（上）\",\"kind\":\"main\",\"volume\":4,\"start\":1764,\"end\":1767,\"summary\":\"柳韵把自己知道的原委告诉胡家父母后离去；胡父没有迁怒报复者，沉重自责，在死亡通知书签字，与妻子守灵一夜，次晨遗体火化。合租屋四人也通宵难眠，雨晴一度仿佛听见阿牛招呼声，对前途与家庭愈加悲观。思凡强作爽朗，提醒仍要生活，请大家出门吃丰盛早茶，暂时从屋内压抑走出来。\",\"turn\":\"父母自责守灵，室友遭受共同丧失；思凡以陪伴和日常活动稳定众人。\",\"time\":\"c450死亡当夜至次晨\",\"people\":[\"胡玉牛父母\",\"胡玉牛\",\"柳韵\",\"苏雨晴\",\"张思凡\",\"方莜莜\",\"林夕晨\"],\"objects\":[\"死亡通知书\",\"电视电影\",\"丰盛早茶\"],\"places\":[\"医院病房\",\"六室合租公寓\",\"早茶店\"]},{\"key\":\"c452\",\"id\":452,\"title\":\"白发人送黑发人（下）\",\"kind\":\"main\",\"volume\":4,\"start\":1768,\"end\":1771,\"summary\":\"数日后胡父尽力操办葬礼，对村人只称突发心脏病；他特选据说来世可做女人的墓地，迟来地尊重阿牛愿望，哭着焚纸。母亲抱墓碑痛哭至晕倒，柳韵和室友送别。雨晴上班后得知职场流言也是压力来源；她一度问死亡是否轻松，被莜莜认真劝回，转而数出继续读书、父母接纳、与夕晨相守等尚未完成的心愿。\",\"turn\":\"阿牛入葬，父亲出现迟到的接纳；雨晴从厌世感转向具体生命愿望。\",\"time\":\"c450数日之后\",\"people\":[\"胡玉牛\",\"胡玉牛父母\",\"柳韵\",\"苏雨晴\",\"方莜莜\",\"张思凡\",\"林夕晨\",\"曲奇\",\"咖啡\",\"风水师\",\"胡父表弟\"],\"objects\":[\"墓碑\",\"红木棺材\",\"纸别墅\",\"纸钱\",\"遗物\",\"蜡烛\",\"香\",\"烟花爆竹\"],\"places\":[\"胡家村庄\",\"山头墓地\"]},{\"key\":\"c453\",\"id\":453,\"title\":\"离开合租房\",\"kind\":\"main\",\"volume\":4,\"start\":1772,\"end\":1775,\"summary\":\"葬礼后四人回到公寓，阿牛遗物已由父母搬空，空房仍使大家触景伤情，终于同意另寻住处。莜莜宣布父母已去外地、自己在小城求职不顺，准备回乡，实际也想离开伤心城市。离别前四人挤在思凡床上笑闹，次晨莜莜做丰盛早餐，三人送她乘十点火车，在《明月几时有》的歌声中目送她离开。\",\"turn\":\"六人共同生活彻底结束：阿牛死亡、天语遥失联、莜莜返乡，只余三人。\",\"time\":\"葬礼之后至莜莜返乡日\",\"people\":[\"苏雨晴\",\"方莜莜\",\"张思凡\",\"林夕晨\",\"胡玉牛父母\",\"柳韵\",\"天语遥\"],\"objects\":[\"空房\",\"思凡的床\",\"离别早餐\",\"行李\",\"明月几时有\"],\"places\":[\"六室合租公寓\",\"小城火车站\"]},{\"key\":\"c454\",\"id\":454,\"title\":\"重新搬进集装箱房\",\"kind\":\"main\",\"volume\":4,\"start\":1776,\"end\":1779,\"summary\":\"送走莜莜后，思凡、雨晴与夕晨回公寓收拾行李，保留尚未取完的物品，暂待月底退租。她们选择重新住进郊外集装箱房，返程受到哈士奇与十多只土狗热闹迎接，发现院落已成部分流浪猫狗的栖处，菜地也在春天复苏。雨晴终于笑起来，向思凡明确承认已与夕晨确定恋爱关系。\",\"turn\":\"三人重返最初庇护所，动物与春日生长带来新的生活感，恋情公开给思凡。\",\"time\":\"c453送站后\",\"people\":[\"张思凡\",\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"曲奇\",\"乡间哈士奇\",\"乡间猫狗群\"],\"objects\":[\"行李\",\"毛绒娃娃\",\"竹蜻蜓\",\"拨浪鼓\",\"库洛牌\",\"后院作物\"],\"places\":[\"小城火车站\",\"六室合租公寓\",\"集装箱房\"]},{\"key\":\"c455\",\"id\":455,\"title\":\"尘封的电瓶车\",\"kind\":\"main\",\"volume\":4,\"start\":1780,\"end\":1783,\"summary\":\"为解决郊外到市中心上班需一小时以上的交通，思凡取出搁置大半年的电瓶车，三人清洗检查，夕晨贴图遮住旧痕，思凡推去换电瓶维修。雨晴回忆最初面馆低薪生活、思凡接送与酒吧获救经历，也因超市议论动念随已递辞职报告的王海峰离开。思凡买菜归来，三人吃海鲜年糕，逐渐恢复胃口与欢笑。\",\"turn\":\"旧交通工具重新连接工作与家，三人恢复生活安排，雨晴开始考虑辞职。\",\"time\":\"重新搬家后的星期日\",\"people\":[\"张思凡\",\"苏雨晴\",\"林夕晨\",\"王海峰\",\"莫空\",\"面馆老板夫妇\"],\"objects\":[\"旧电瓶车\",\"新电瓶\",\"防水贴纸\",\"海鲜年糕\"],\"places\":[\"集装箱房\",\"公交总站电瓶车店\",\"小城菜市\"]},{\"key\":\"c456\",\"id\":456,\"title\":\"坐上电动车去吹风\",\"kind\":\"main\",\"volume\":4,\"start\":1784,\"end\":1787,\"summary\":\"搬回集装箱房后的周一，思凡为送雨晴上早班提早起床，夕晨亲昵唤醒赖床的恋人。雨晴不舍留下夕晨独处，仍坐电动车迎着寒风出发；路上买糯米饭，在车后座吃早餐，六点四十分抵超市没有迟到。思凡约好下班接她，雨晴带着重新获得的希望工作，与王海峰、陈淑艳恢复熟悉的玩笑。\",\"turn\":\"艰辛通勤由友情分担，雨晴在亲密关系和日常照顾中重新稳住生活。\",\"time\":\"搬回后的星期一清晨\",\"people\":[\"苏雨晴\",\"张思凡\",\"林夕晨\",\"王海峰\",\"陈淑艳\",\"早餐摊主\"],\"objects\":[\"席梦思床\",\"电瓶车\",\"糯米饭\"],\"places\":[\"集装箱房\",\"工厂门口早餐摊\",\"大润发超市\"]},{\"key\":\"c457\",\"id\":457,\"title\":\"方莜莜一个人的家\",\"kind\":\"main\",\"volume\":4,\"start\":1788,\"end\":1791,\"summary\":\"莜莜回到武汉附近一个地级市的城中村旧家，父母不在，三层农房空荡冷清。她以自家土豆与咸肉果腹，在好友聊天窗反复输入又删除，安念发现后主动关心。她用反话表达寂寞，安念却只顾游戏，直到她直说才认真陪聊。两人再约六月见面，相互表达喜欢，同时各自担忧现实相见后的未来。\",\"turn\":\"远距离恋情继续，孤独使莜莜学着明确表达需求，现实见面尚待六月。\",\"time\":\"莜莜返乡当晚\",\"people\":[\"方莜莜\",\"安念\",\"莜莜父母\"],\"objects\":[\"藤椅\",\"土豆\",\"咸肉\",\"电脑\",\"QQ秀\",\"电视\"],\"places\":[\"莜莜老家城中村三层农房\"]},{\"key\":\"c458\",\"id\":458,\"title\":\"到底什么样才能算是女孩子呢\",\"kind\":\"main\",\"volume\":4,\"start\":1792,\"end\":1795,\"summary\":\"天语遥亲见阿牛葬礼，认定报复完成，换电话卡和QQ断绝旧兄弟及夏归月联系。快意之后空虚涌来，她仍想活下去，暂缓自伤念头，把尝试接受女性生活称作挑战自己。她以软陶为新网名，照镜练微笑与撒娇；父母看到她久违的自然笑容十分欣慰，只盼她能快乐生活，而她仍思念被自己单方面割舍的归月。\",\"turn\":\"报复完成未带来充实，天语遥断联旧生活后转向试着接纳自身变化。\",\"time\":\"阿牛葬礼当天及其后数日\",\"people\":[\"天语遥\",\"夏归月\",\"天语遥父母\",\"饼干\",\"胡玉牛\"],\"objects\":[\"新电话卡\",\"新QQ号\",\"软陶网名\",\"陶人\",\"兔笼\",\"发卡\",\"镜子\"],\"places\":[\"胡玉牛墓地\",\"天语遥家\"]},{\"key\":\"c459\",\"id\":459,\"title\":\"躲不过\",\"kind\":\"main\",\"volume\":4,\"start\":1796,\"end\":1799,\"summary\":\"天语遥不敢再找大黑狗或夏归月，以免割舍失败；母亲为她报陶艺班，父亲送她、因她累而背到门口，这段确属现实。进教室后，她以为夏归月坐在前排、拉她一起学习，两人久别重逢。然而后文c463揭示从进教室起这些相逢只是天语遥的幻觉，真实的她坐在无人陪伴的后排。\",\"turn\":\"父亲送学真实，进班后的重逢被后文揭为幻觉，不能记录成实际复合。\",\"time\":\"与夏归月断联约半个月后\",\"people\":[\"天语遥\",\"天语遥父母\",\"夏归月\",\"陶艺老师\"],\"objects\":[\"女装\",\"蝴蝶结发绳\",\"猫耳发箍\",\"发卡\"],\"places\":[\"陶艺培训机构\",\"附近街道\"]},{\"key\":\"c460\",\"id\":460,\"title\":\"叔叔，我最喜欢小遥了\",\"kind\":\"main\",\"volume\":4,\"start\":1800,\"end\":1803,\"summary\":\"在后来被c463揭穿的幻境中，夏归月追问失联，索要天语遥新号码，坚持离开才会伤害自己；天语遥教她捏陶人，并以恋人为模特受老师表扬。下课后归月要求到天家，父亲似在书店研究儿女心思，归月向他表白最喜欢小遥。现实中老师表扬的是前排别的学生，归月并未出现，父亲实际买的是玄幻小说。\",\"turn\":\"借幻觉呈现被找回与被接纳的渴望；新号码交换和父亲见恋人均非事实。\",\"time\":\"同c459日、幻觉叙述\",\"people\":[\"天语遥\",\"夏归月\",\"天语遥父亲\",\"陶艺老师\",\"前排两位女生\"],\"objects\":[\"陶艺作品\",\"幻想中的育儿书\"],\"places\":[\"陶艺教室\",\"新华书店\"]},{\"key\":\"c461\",\"id\":461,\"title\":\"我是小遥的女朋友\",\"kind\":\"main\",\"volume\":4,\"start\":1804,\"end\":1807,\"summary\":\"幻觉中的夏归月当父亲面自称女朋友，三人随后到咖啡厅吃牛排喝咖啡。天语遥既珍惜与她相守，又担心耽误她，用筷子吃牛排来化解拘谨；父亲则想象这段爱情的困难。c463纠正实际只有父女两人午餐，第三份餐是为两人食量准备，筷子也是父亲主动要来，根本没有归月见家长。\",\"turn\":\"看似现实的细节均有另一解释，幸福见家长情节是心理愿望的投影。\",\"time\":\"同c459日中午、幻觉叙述\",\"people\":[\"天语遥\",\"夏归月\",\"天语遥父亲\",\"咖啡厅服务员\"],\"objects\":[\"牛排\",\"咖啡\",\"筷子\"],\"places\":[\"咖啡厅\"]},{\"key\":\"c462\",\"id\":462,\"title\":\"天语遥的陶人柜\",\"kind\":\"main\",\"volume\":4,\"start\":1808,\"end\":1812,\"summary\":\"天语遥以为把夏归月带进家，获她无条件支持，展示满柜归月陶人，又为她制作七个不同人生时期的自己，放进亚克力盒。两人似乎相拥而眠，母亲也看到她们；但c463揭示夏归月从未来访：陶人柜与她捏自己的动作真实，陪伴、赠礼和父母讨论恋情皆为幻觉，她实际抱着母亲买的玩具熊睡去。\",\"turn\":\"陶艺把缺失的相守化为可触物件，七个陶人并未真正交到夏归月手里。\",\"time\":\"同c459日下午、幻觉叙述\",\"people\":[\"天语遥\",\"夏归月\",\"天语遥父母\"],\"objects\":[\"陶人展示柜\",\"夏归月陶人\",\"天语遥陶人\",\"亚克力盒\",\"老照片\",\"玩具熊\"],\"places\":[\"天语遥卧室\"]},{\"key\":\"c463\",\"id\":463,\"title\":\"其实都错了\",\"kind\":\"main\",\"volume\":4,\"start\":1813,\"end\":1816,\"summary\":\"叙述明确纠正前几章：天语遥进陶艺班后把旁人的言行改造成与夏归月重逢。真实课堂上她独坐后排自语、捏出异形物，老师表扬的是别人；父亲在书店买《不死不灭》，父女两人吃三份午饭。回家后她独自捏自己的陶人配在归月像旁，抱着玩具熊入睡；母亲开门打断幻境，她才明白一切，仍喊月月流泪。\",\"turn\":\"揭示现实与幻觉的边界，重逢被撤销，天语遥孤独与心理危机显露。\",\"time\":\"对c459—462同日真实事件的回溯\",\"people\":[\"天语遥\",\"天语遥父母\",\"夏归月\",\"陶艺老师\",\"前排女生\"],\"objects\":[\"不死不灭\",\"陶艺异形物\",\"配对陶人\",\"玩具熊\",\"筷子\"],\"places\":[\"陶艺教室\",\"新华书店\",\"咖啡厅\",\"天语遥卧室\"]},{\"key\":\"c464\",\"id\":464,\"title\":\"不想分清虚幻和现实\",\"kind\":\"main\",\"volume\":4,\"start\":1817,\"end\":1820,\"summary\":\"从幻境醒来的天语遥不愿面对现实，试着继续想象夏归月却无法保持清晰。她用新QQ加入无需审核的同类群，观望热闹话题，却难以融入，还把群内谈论误作女性身份模板。随后她再次与想象的归月交谈，幻想对方支持自己、陪她回忆学校生活，晚餐也心不在焉，渐渐不想区分想象与现实。\",\"turn\":\"虚构陪伴从无意识幻觉转为主动沉溺，真正的人际联系仍未重建。\",\"time\":\"c463之后\",\"people\":[\"天语遥\",\"天语遥父母\",\"夏归月\",\"同类QQ群管理员\",\"饼干\"],\"objects\":[\"新QQ号\",\"开放同类QQ群\",\"兔饲料\"],\"places\":[\"天语遥家\",\"QQ线上群聊\"]},{\"key\":\"c465\",\"id\":465,\"title\":\"辞职后想去做什么\",\"kind\":\"main\",\"volume\":4,\"start\":1821,\"end\":1824,\"summary\":\"王海峰的辞职申请终于获批，待下月发薪离职，考虑回乡做主管或筹资开小超市。员工留恋他的宽厚，翁锡芽却只愿暂代、不愿长期接主管。雨晴也明确想辞职，既因为王离去，更因超市勾起阿牛之死；王替她领表。她仍以高三实习生说辞掩饰无证件状态，看见后仓已有新人，体会旧人逐渐被日常遗忘。\",\"turn\":\"王离职已批准，雨晴着手申请，超市工作阶段进入收束。\",\"time\":\"2005年春，王预计下月发薪后离职\",\"people\":[\"王海峰\",\"苏雨晴\",\"陈淑艳\",\"翁锡芽\",\"新后仓男员工\"],\"objects\":[\"辞职申请表\",\"报纸\",\"一角硬币\"],\"places\":[\"大润发超市酒柜\",\"后仓\"]},{\"key\":\"c466\",\"id\":466,\"title\":\"孙昊又来了\",\"kind\":\"main\",\"volume\":4,\"start\":1825,\"end\":1828,\"summary\":\"思凡提前下班接雨晴，先开辞职玩笑，后因高速骑车耗尽电力改推车回家。她心情好是因孙昊将来小城，计划接站并在外相聚；考虑雨晴次日通勤，她把电动车留下自己坐公交。雨晴仍担心孙昊会伤害思凡，却只说路上小心。晚上她与夕晨吃家常饭，并把多做的饭分给院里的哺乳母狗、孕猫与流浪动物。\",\"turn\":\"孙昊再访令思凡兴奋，雨晴对他仍不安；暂时独立通勤成为新日常问题。\",\"time\":\"2005年春某工作日下午\",\"people\":[\"张思凡\",\"苏雨晴\",\"林夕晨\",\"孙昊\",\"乡间哈士奇\",\"哺乳母狗\",\"怀孕母猫\",\"乡间猫狗群\"],\"objects\":[\"电瓶车\",\"晾衣叉\",\"哈士奇画\",\"酱爆茄子\",\"冬瓜骨头汤\",\"猫狗饭碗\"],\"places\":[\"大润发超市门口\",\"返家路\",\"集装箱房\"]},{\"key\":\"c467\",\"id\":467,\"title\":\"天语遥和陌生的网友\",\"kind\":\"main\",\"volume\":4,\"start\":1829,\"end\":1832,\"summary\":\"雨天独处的天语遥制作猫耳猫尾女武神陶人，收到群友淡蓝色的忧郁的主动私聊。她自报十八岁、没有上学，对方询问身份和生活，她多半冷淡简答。后来蓝色赠《魔兽世界》限量测试激活码并邀同玩，她选亡灵战士，对方选亡灵牧师，约用YY交流；空荡的新QQ终于出现一个朋友。\",\"turn\":\"游戏成为断联后新社交入口，蓝色主动接近的动机尚待观察。\",\"time\":\"2005年早春，书中称游戏限量测试次日\",\"people\":[\"天语遥\",\"蓝色\",\"天语遥父亲\"],\"objects\":[\"猫耳女武神陶人\",\"QQ\",\"魔兽世界激活码\",\"泡面\",\"YY\"],\"places\":[\"天语遥家\",\"QQ与魔兽世界线上\"]},{\"key\":\"c468\",\"id\":468,\"title\":\"你的声音还蛮好听的\",\"kind\":\"main\",\"volume\":4,\"start\":1833,\"end\":1836,\"summary\":\"蓝色在YY称赞天语遥声音，热心陪玩却话多得让她疲倦。夜里她仍依赖想象中的归月安慰孤独；接着叙述又呈现归月问到住址、清晨来家等她的幸福相逢。到卧室听见归月赞陶人时，她惊惧抱紧对方，随即醒来发现只有阴雨与怀中的玩具熊；这场上门寻找同样只是梦或幻觉。\",\"turn\":\"新朋友未消除孤独，第二次上门重逢再被否定为虚构陪伴。\",\"time\":\"c467游戏日之夜及梦中次晨\",\"people\":[\"天语遥\",\"蓝色\",\"夏归月\",\"天语遥父母\"],\"objects\":[\"YY耳麦\",\"台灯\",\"毛绒熊\",\"陶人柜\"],\"places\":[\"天语遥家\",\"魔兽世界线上\",\"梦中天家客厅\"]},{\"key\":\"c469\",\"id\":469,\"title\":\"各自人各自的生活\",\"kind\":\"main\",\"volume\":4,\"start\":1837,\"end\":1840,\"summary\":\"思凡与孙昊在宾馆相聚，谈到毕业后搬去他的城市，孙答应接她；她睡着后，孙却对其外貌中男性化特征流露厌恶。莜莜已找到武汉市内工作，冒雨乘车首次上班，安念的早安短信稍解独居寂寞。雨晴则被莜莜自伤的噩梦惊醒，又找不到夕晨，惶恐独留房中；梦中莜莜之死并非现实。\",\"turn\":\"远近各自开始新生活；孙昊真实的外貌排斥与思凡相守愿望形成裂缝。\",\"time\":\"孙昊到访夜至次晨、莜莜新工作首日\",\"people\":[\"张思凡\",\"孙昊\",\"方莜莜\",\"安念\",\"苏雨晴\",\"林夕晨\",\"曲奇\",\"咖啡\"],\"objects\":[\"宾馆床\",\"香烟\",\"公交车\",\"雨伞\",\"早安短信\"],\"places\":[\"小城宾馆\",\"莜莜老家公交站\",\"武汉新工作单位\",\"集装箱房\"]},{\"key\":\"c470\",\"id\":470,\"title\":\"扶住\",\"kind\":\"main\",\"volume\":4,\"start\":1841,\"end\":1844,\"summary\":\"曲奇露出夕晨留下的有事出去纸条，让雨晴稍安。午间夕晨从黑色奔驰下车，收下一沓钱，带名牌包疲惫返家；途中莫空扶住险跌的她，伞被吹走后她拒绝共伞或借伞，独自淋雨。莫空猜她渴望别人关心，留在附近河边烤鱼。回到集装箱房，雨晴忙为浑身湿透、咳嗽乏力的夕晨擦头发并扶入浴室。\",\"turn\":\"神秘外出与现金来源未明；夕晨淋雨病倒，雨晴成为照顾者。\",\"time\":\"c469次日中午雨天\",\"people\":[\"苏雨晴\",\"林夕晨\",\"莫空\",\"奔驰车内男子\",\"曲奇\",\"乡间哈士奇\",\"流浪狗\"],\"objects\":[\"外出纸条\",\"黑色奔驰\",\"现金\",\"名牌包\",\"黑雨伞\",\"草鱼\",\"干毛巾\"],\"places\":[\"集装箱房\",\"郊区公交总站\",\"乡间小路\",\"小河松树下\"]},{\"key\":\"c471\",\"id\":471,\"title\":\"林夕晨发烧了\",\"kind\":\"main\",\"volume\":4,\"start\":1845,\"end\":1848,\"summary\":\"夕晨疲惫发热，雨晴帮她洗漱换衣、量体温，见三十九度后细心照料并喂姜汤。夕晨难得显露撒娇与依赖，紧握雨晴的手入睡。思凡晚八点返家，说明孙昊已走，关心夕晨若不退热须就医；三人相伴休息时，她试探自己离城后雨晴怎么办。雨晴明白她想去孙昊身边，答大概仍留小城，也意识到朋友各有生活。\",\"turn\":\"照顾强化晴夕亲密，思凡首次向雨晴探问自己离城后的安排。\",\"time\":\"c470午后至晚八点后\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"孙昊\",\"莫空\"],\"objects\":[\"体温计\",\"药盒\",\"姜汤\",\"电热毯\",\"羽绒被\"],\"places\":[\"集装箱房\"]},{\"key\":\"c472\",\"id\":472,\"title\":\"天语遥和奇怪的小电影\",\"kind\":\"main\",\"volume\":4,\"start\":1849,\"end\":1852,\"summary\":\"失眠无聊的天语遥主动找蓝色聊天，对方暂停游戏回应，让她感到被在意。聊天转向带有身体羞辱与支配意味的成人视频，蓝色以嘲弄她幼稚来激将；她原本排斥，却逐渐被痛感与自我贬低相连的内容牵动，带着混乱和不适入睡。章末带有侵害感的海滩场景是噩梦，她惊醒，不能视作真实遭遇。\",\"turn\":\"新网友的边界试探与激将加深她的心理混乱，关怀需求被引向危险互动。\",\"time\":\"2005年早春某夜\",\"people\":[\"天语遥\",\"蓝色\",\"天语遥母亲\"],\"objects\":[\"电脑\",\"QQ聊天\",\"成人视频链接\"],\"places\":[\"天语遥卧室\",\"梦中海滩\"]},{\"key\":\"c473\",\"id\":473,\"title\":\"严重的高烧\",\"kind\":\"main\",\"volume\":4,\"start\":1853,\"end\":1856,\"summary\":\"次晨夕晨仍高烧，思凡认为自己请假方便，送雨晴上班后带夕晨就医。初诊处理后她依旧头痛腹痛、呕吐无力，思凡背她上楼重新挂专家号，陪着做尿检、血检并等待超声检查。化验报告的染色体栏写XX，令一直相信夕晨与自己经历相似的思凡震惊，怀疑结果出错。\",\"turn\":\"持续病情促成进一步检查，XX报告开启夕晨身体身世的新线索。\",\"time\":\"c471翌日清晨至八点以后\",\"people\":[\"林夕晨\",\"张思凡\",\"苏雨晴\",\"值班医生\",\"专家医生\",\"化验人员\"],\"objects\":[\"闹钟\",\"电瓶车\",\"糯米饭团\",\"化验报告\",\"牛奶饼干\"],\"places\":[\"集装箱房\",\"大润发超市门口\",\"小城医院\"]},{\"key\":\"c474\",\"id\":474,\"title\":\"女性染色体\",\"kind\":\"main\",\"volume\":4,\"start\":1857,\"end\":1860,\"summary\":\"思凡先质疑XX报告，随后超声结果又让医生确认夕晨具有先天性发育差异；这些均为小说的医学情节设定。医生建议复查并向省级医院咨询，说明重大手术应在慎重选择后进行。复查结果相同，思凡在惊讶与羡慕中把消息告诉苏醒的夕晨；夕晨瞪大眼睛，第一次得知自己与长期以来认定的身体身份并不相同。\",\"turn\":\"重复检查支持书中先天性发育差异设定，改变夕晨与室友对其身份经历的理解。\",\"time\":\"c473同日\",\"people\":[\"林夕晨\",\"张思凡\",\"专家医生\",\"检验医生\",\"检验护士\"],\"objects\":[\"XX化验单\",\"超声影像\",\"病历卡\",\"复查报告\"],\"places\":[\"小城三甲医院检验处\",\"超声室\",\"门诊诊室\"]},{\"key\":\"c475\",\"id\":475,\"title\":\"忍不住笑\",\"kind\":\"main\",\"volume\":4,\"start\":1861,\"end\":1864,\"summary\":\"确认检查消息后，夕晨从难以置信转为无法掩饰的欢笑，想到可以向父母解释自己、与雨晴建立未来家庭；这些生育与婚姻构想尚是她的愿望。思凡真心祝贺，却也因比较自己的处境而羡慕失落。她把夕晨送到雨晴工作的超市后返回公司，把情绪投入文稿，一口气做完原本一周的任务。\",\"turn\":\"夕晨罕见敞开情绪，思凡同时经历祝福与羡慕，以工作消化落差。\",\"time\":\"c474同日上午至工作时间\",\"people\":[\"林夕晨\",\"张思凡\",\"苏雨晴\",\"思凡女同事\"],\"objects\":[\"超声影像\",\"化验报告\",\"最初的梦想\",\"工作文稿\"],\"places\":[\"医院外街道\",\"大润发超市门口\",\"思凡实习公司\"]},{\"key\":\"c476\",\"id\":476,\"title\":\"有林夕晨一起陪伴的工作\",\"kind\":\"main\",\"volume\":4,\"start\":1865,\"end\":1868,\"summary\":\"夕晨到酒柜陪雨晴工作，王海峰体谅让她们在较清闲处相伴，雨晴感到平常一天格外幸福。下班后夕晨终于分享检查确认先天性发育差异的消息，雨晴真心为她高兴；她计划先存钱、回去找父母，再考虑手术。夕晨也表现出流畅说话与主动亲昵，雨晴意识到她平日沉默背后有更多未表达的情绪。\",\"turn\":\"检查消息被恋人共享，晴夕开始期待更具体的将来，尚未回家或手术。\",\"time\":\"c475当日上班至下班\",\"people\":[\"苏雨晴\",\"林夕晨\",\"王海峰\",\"陈淑艳\",\"雯雯\"],\"objects\":[\"检查结果\",\"酒柜\"],\"places\":[\"大润发超市酒柜\",\"超市外\"]},{\"key\":\"c477\",\"id\":477,\"title\":\"初次尝试\",\"kind\":\"main\",\"volume\":4,\"start\":1869,\"end\":1872,\"summary\":\"天语遥仍与蓝色游戏，得知对方也在小城市，却出于警惕不透露自己所在地。她厌倦网络争吵，又被蓝色此前提供的成人影像牵引，在孤独中把身体体验错当成理解女性身份的途径。母亲送茶点时她慌忙遮掩，后来父母外出，她独自尝试身体探索；这些呈现她的困惑，不构成性别认同的判断标准。\",\"turn\":\"她对网友保留地理信息边界，却仍受错误身份脚本与影像引导。\",\"time\":\"2005年早春\",\"people\":[\"天语遥\",\"蓝色\",\"天语遥母亲\"],\"objects\":[\"电脑\",\"YY\",\"网络论坛\",\"茉莉花茶\",\"小点心\",\"软陶\"],\"places\":[\"天语遥家\",\"线上游戏与论坛\"]},{\"key\":\"c478\",\"id\":478,\"title\":\"夏归月的寻找\",\"kind\":\"main\",\"volume\":4,\"start\":1873,\"end\":1876,\"summary\":\"断联近一个月后，夏归月确认天语遥不辞而别，替旧号码缴费仍只能听到关机，周末翘掉兴趣课四处寻找。天的帮会已经解散，地盘被瓜分；黄枸明知住址，却认定离别是替归月好而隐瞒。她回到旧日复合公园，向沧桑男子恳求只想见面问清；对方最终留下一张纸条离去，c479确认此人是莫空。\",\"turn\":\"真正的寻找开始，黄枸以替人决定的善意阻拦，莫空最终提供方向。\",\"time\":\"与天语遥失联近一个月后的双休日\",\"people\":[\"夏归月\",\"天语遥\",\"黄枸\",\"黄枸军师\",\"黄枸帮众\",\"莫空\"],\"objects\":[\"旧电话号码\",\"充值话费\",\"帮会地图\",\"纸条\"],\"places\":[\"废弃小巷\",\"旧日复合公园\",\"小城街道\"]},{\"key\":\"c479\",\"id\":479,\"title\":\"意外的相见\",\"kind\":\"main\",\"volume\":4,\"start\":1877,\"end\":1880,\"summary\":\"夏归月循莫空纸条向右直走，终于真正找到天语遥。天先逃跑，随后错把她当幻觉，游玩时还对树木空气说话；归月心痛陪伴，最后提醒她面对现实。天确认眼前恋人真实，却坚持离开是承担责任、免她承受社会家庭压力。归月表示愿共患难，仍未说服她，天再次挣脱跑走，留下哭泣的归月。\",\"turn\":\"此番相见是真实；幻觉穿插其间，天语遥仍单方面拒绝共同承担困难。\",\"time\":\"c478同日\",\"people\":[\"夏归月\",\"天语遥\",\"莫空\"],\"objects\":[\"指路纸条\",\"街机\"],\"places\":[\"公园外街道\",\"小区转角\",\"游戏厅\",\"咖啡馆\",\"公园\",\"小吃街\"]},{\"key\":\"c480\",\"id\":480,\"title\":\"天语遥和苏雨晴\",\"kind\":\"main\",\"volume\":4,\"start\":1881,\"end\":1884,\"summary\":\"逃离归月后，天语遥反复失去现实感，路遇购物返家的雨晴竟错认成月月。雨晴本要为阿牛质问她，见她对空气自语、神志混乱，愤怒中又生怜悯。短暂清醒的天仍不后悔报复，拒绝同情；雨晴最终没有弃她于路边，把她扶到电话亭联系母亲接回，未向其母公开报复经过。两人望同一天空，感受却截然不同。\",\"turn\":\"雨晴在谴责报复后仍救助天语遥；本段以母亲接回和未解心理危机结束。\",\"time\":\"c479同日稍后\",\"people\":[\"天语遥\",\"苏雨晴\",\"天语遥母亲\",\"夏归月\",\"胡玉牛\"],\"objects\":[\"购物袋\",\"内衣\",\"电话亭\",\"手机\"],\"places\":[\"小城步行街外人行道\",\"电话亭\"]},{\"key\":\"c481\",\"id\":481,\"title\":\"和男人去看电影\",\"kind\":\"main\",\"volume\":4,\"start\":1885,\"end\":1888,\"summary\":\"天语遥复仇后的精神困扰并未消散，只靠游戏暂时转移注意。她发现网友蓝色也住在小城市，经软磨硬泡答应影院见面；三十岁左右的蓝色不断示好，她因被当成女孩而别扭。两人看《活死人之地》，她留意自己对甜食的新偏好，继续困惑于身体与自我认知的变化。\",\"turn\":\"天语遥与蓝色由网友变成线下玩伴，创伤与身份矛盾仍在。\",\"time\":\"\",\"people\":[\"天语遥\",\"蓝色\",\"天语遥父母\",\"胡玉牛\"],\"objects\":[\"爆米花\",\"网络游戏《魔兽世界》\",\"电影《活死人之地》\"],\"places\":[\"天语遥家\",\"小城影院\"]},{\"key\":\"c482\",\"id\":482,\"title\":\"吃豆腐？\",\"kind\":\"main\",\"volume\":4,\"start\":1889,\"end\":1892,\"summary\":\"蓝色在影院不断试探身体接触，天语遥逐渐察觉被冒犯。两人又去网吧，她在旧日混混生活的回忆里睡着，做了关于被强迫改变人生的恶梦；读者可见蓝色趁她睡着越界，她醒后却未确认。天语遥独自回家，觉得对方令人不适，同时为自身复杂感受困惑。\",\"turn\":\"蓝色的越界行为已出现；梦境不能当作真实婚姻、生育事件。\",\"time\":\"\",\"people\":[\"天语遥\",\"蓝色\",\"夏归月\"],\"objects\":[\"网络游戏\",\"网吧电脑\"],\"places\":[\"小城影院\",\"影院楼上网吧\"]},{\"key\":\"c483\",\"id\":483,\"title\":\"天语遥和情趣用品店\",\"kind\":\"main\",\"volume\":4,\"start\":1893,\"end\":1896,\"summary\":\"阴天傍晚，天语遥偶遇消瘦的大黑狗，买火腿肠和牛奶喂它，借它想到夏归月并落泪。失去复仇目标后，她轻生念头加重。返家途中她进入无人成人用品店，买下按摩器并藏在床下；大黑狗一路跟到小区，却被保安赶走，她未注意到这次告别。\",\"turn\":\"大黑狗仍在流浪；天语遥开始以强烈感官刺激暂避痛苦。\",\"time\":\"\",\"people\":[\"天语遥\",\"黑皇\",\"夏归月\",\"小区保安\"],\"objects\":[\"火腿肠与旺仔牛奶\",\"成人用品按摩器\"],\"places\":[\"小城市街头\",\"成人用品店\",\"天语遥家小区\"]},{\"key\":\"c484\",\"id\":484,\"title\":\"天语遥和男性用品\",\"kind\":\"main\",\"volume\":4,\"start\":1897,\"end\":1900,\"summary\":\"天语遥对食物、论坛和聊天都失去兴致，蓝色的信息使她烦躁，捏软陶也泄露出心事。深夜她尝试新买的成人用品，过程令她疲惫却暂时卸下焦虑，罕见地无梦熟睡。次晨她把这份短暂舒缓看作生活中少有的美好，也开始把它误当作解决长期痛苦的办法。\",\"turn\":\"感官刺激被当作减压依靠，不能据此理解为心理问题得到治愈。\",\"time\":\"次日清晨\",\"people\":[\"天语遥\",\"天语遥父母\",\"蓝色\"],\"objects\":[\"软陶\",\"成人用品按摩器\"],\"places\":[\"天语遥家\"]},{\"key\":\"c485\",\"id\":485,\"title\":\"天语遥的第一次（上）\",\"kind\":\"main\",\"volume\":4,\"start\":1901,\"end\":1904,\"summary\":\"长期闲居让天语遥更觉空虚；她靠成人用品排遣情绪，又继续与蓝色在影院、网吧和海边消磨时间，逐渐容忍其陪伴。某日她穿母亲买的保守长裙赴约，看恐怖片后接受蓝色去KTV的提议。两人独处包厢、喝鸡尾酒，她忍不了蓝色的跑调歌声而接过话筒。\",\"turn\":\"关系从公共场合玩伴转入私密包厢，蓝色的追求进入危险阶段。\",\"time\":\"\",\"people\":[\"天语遥\",\"蓝色\",\"天语遥母亲\",\"夏归月\"],\"objects\":[\"长裙与口罩\",\"鸡尾酒\",\"KTV话筒\"],\"places\":[\"小城影院\",\"KTV包厢\",\"海滩\"]},{\"key\":\"c486\",\"id\":486,\"title\":\"天语遥的第一次（下）\",\"kind\":\"main\",\"volume\":4,\"start\":1905,\"end\":1909,\"summary\":\"在KTV中，天语遥饮酒后意识与行动能力受影响，蓝色仍持续越界并与她发生性接触。醒后她记起经过，陷入羞耻、自我厌弃与身份困惑，却因长期绝望而选择继续靠短暂刺激度日。蓝色达成目的后话明显变少，两人默默离开；她并未因此获得被尊重的亲密关系。\",\"turn\":\"蓝色利用脆弱与失去清醒判断的状态越界；后续快感不能抹去当时同意问题。\",\"time\":\"\",\"people\":[\"天语遥\",\"蓝色\"],\"objects\":[\"鸡尾酒\",\"口罩与长裙\"],\"places\":[\"KTV包厢\",\"公交车\"]},{\"key\":\"c487\",\"id\":487,\"title\":\"柳韵的报复\",\"kind\":\"main\",\"volume\":4,\"start\":1910,\"end\":1913,\"summary\":\"柳韵混迹于年长无业男子群体，听蓝色炫耀天语遥的照片后认出旧仇人，决定报复她对胡玉牛之死的推动。她暗中诱导蓝色召集更多人、升级伤害。蓝色先带人参与，随后以私密照片外传威胁；天语遥虽不在乎自己名声，却怕夏归月知道，因而被迫赴下一次约。\",\"turn\":\"柳韵由悲痛转向借刀报复，照片把脆弱关系变成胁迫。\",\"time\":\"\",\"people\":[\"柳韵\",\"蓝色\",\"天语遥\",\"胡玉牛\",\"蓝色同伙\"],\"objects\":[\"蓝色的拍照手机\",\"私密照片\"],\"places\":[\"废旧集装箱聚点\",\"宾馆\"]},{\"key\":\"c488\",\"id\":488,\"title\":\"比死还痛苦\",\"kind\":\"main\",\"volume\":4,\"start\":1914,\"end\":1917,\"summary\":\"天语遥的幻觉、时间错位感和自我认知混乱加剧。两天后她在照片威胁下赴地下室，被十余名男子集体侵害与虐待，蓝色发现失控却被同伙打昏。天语遥失去意识，在与夏归月结婚又遭拒绝的反复幻梦里痛苦挣扎，直到外界传来夏归月敲门呼喊旧名的声音。\",\"turn\":\"侵害造成严重身体与心理创伤；婚礼、庄园及身体变化皆为幻梦。\",\"time\":\"两天后\",\"people\":[\"天语遥\",\"蓝色\",\"蓝色同伙\",\"夏归月\"],\"objects\":[\"私密照片\",\"地下室铁门\"],\"places\":[\"胖子酒吧地下室\",\"幻梦中的花圃与庄园\"]},{\"key\":\"c489\",\"id\":489,\"title\":\"莫空指路\",\"kind\":\"main\",\"volume\":4,\"start\":1918,\"end\":1921,\"summary\":\"夏归月后悔此前未追上天语遥，认定即使没有可预知的结局，也愿意珍惜当下相伴。她在河边再次遇见莫空，经追问与坚定表态拿到双面地址纸条，得知可能来不及便急赶海天大酒店对面胖子酒吧。她最终在自行车地下库内找到铁门，敲门大喊天冲云。\",\"turn\":\"莫空再次提供精确线索，夏归月主动选择不计结局的守护。\",\"time\":\"\",\"people\":[\"夏归月\",\"莫空\",\"出租车司机\",\"天语遥\"],\"objects\":[\"莫空的双面地址纸条\"],\"places\":[\"小河边长椅\",\"海天大酒店\",\"胖子酒吧地下室\"]},{\"key\":\"c490\",\"id\":490,\"title\":\"黄枸救场\",\"kind\":\"main\",\"volume\":4,\"start\":1922,\"end\":1925,\"summary\":\"夏归月找到天语遥却险被施害者拖入。接获某人指引的黄枸带四十余名小弟及时救场，制服十余男子并报警、叫救护车。天语遥短暂清醒，与夏归月重逢后再度昏迷，仍有微弱呼吸。黄枸陪赴医院、派人通知父母，强调救人优先于抢地盘。\",\"turn\":\"天语遥获救并未死亡；黄枸与昔日对手体现互助情义。\",\"time\":\"书内称星期天\",\"people\":[\"天语遥\",\"夏归月\",\"黄枸\",\"黄枸军师与小弟\",\"施害者\",\"警察\",\"医护\",\"天语遥父母\"],\"objects\":[\"地下室铁门\",\"救护车\",\"电话\"],\"places\":[\"胖子酒吧地下室\",\"小城市医院\"]},{\"key\":\"c491\",\"id\":491,\"title\":\"脱离危险\",\"kind\":\"main\",\"volume\":4,\"start\":1926,\"end\":1929,\"summary\":\"天语遥父母赶到医院，医生称她脱水、精力耗尽，已脱险。夏归月承认女友身份，坚持整夜守候，直到次日下午才由其母送回。病房电视播报2005年4月2日大阪飞香港的JL6910航班失联。4月4日周一清晨夏归月醒来，仍惦念昏睡的天语遥。\",\"turn\":\"身体脱险而精神结局未定；航班失联进入正文另一条主线。\",\"time\":\"2005年4月3—4日\",\"people\":[\"天语遥\",\"夏归月\",\"天语遥父母\",\"夏归月父母\",\"医护\"],\"objects\":[\"医院电视\",\"毛毯\",\"夜宵\"],\"places\":[\"小城市医院单人病房\",\"医院食堂\",\"夏归月家\"]},{\"key\":\"c492\",\"id\":492,\"title\":\"醒不过来\",\"kind\":\"main\",\"volume\":4,\"start\":1930,\"end\":1933,\"summary\":\"天语遥长期昏迷，母亲搬电脑到病房工作，父亲与双方律师周旋追责。夏归月每天放学来写作业、讲见闻，父母虽担忧仍允许她守候。空难残骸被找到，书内认定无人幸存。夏归月向她描绘迪士尼、西湖、北京和台湾之旅，哭着自语时忽然被天语遥握住手。\",\"turn\":\"守候成为日常，空难确认悲剧，握手预示意识开始回返。\",\"time\":\"2005年4月起持续一段时间\",\"people\":[\"天语遥\",\"夏归月\",\"天语遥父母\",\"夏归月父母\",\"双方律师\"],\"objects\":[\"病房电脑\",\"空难新闻\",\"书包与作业\"],\"places\":[\"小城市医院\"]},{\"key\":\"c493\",\"id\":493,\"title\":\"天语遥的世界（一）\",\"kind\":\"main\",\"volume\":4,\"start\":1934,\"end\":1937,\"summary\":\"叙事转入天语遥的意识世界：她在少女房间醒来，用残缺记忆拼成自己自愿女性化、卧床三年的解释，并认定这是可自由控制的梦。年轻父母送她到文澜学院，她能用念头改变他人视线；夏归月在这里是青梅竹马、同桌与亲密闺蜜，日常校园生活暂时补偿了现实遗憾。\",\"turn\":\"自愿用药、先天女孩与青梅竹马设定是梦境记忆，非现实前史。\",\"time\":\"意识世界开始\",\"people\":[\"天语遥\",\"夏归月\",\"天语遥父母\",\"叶雯\"],\"objects\":[\"毛绒公仔\",\"女装\",\"桑塔纳汽车\"],\"places\":[\"意识世界的天语遥家\",\"意识世界的文澜学院\"]},{\"key\":\"c494\",\"id\":494,\"title\":\"天语遥的世界（二）\",\"kind\":\"main\",\"volume\":4,\"start\":1938,\"end\":1941,\"summary\":\"天语遥在梦里睡醒后仍留在同一世界，逐渐把它视为第二现实。她操控天气、时间与生活，帮助父母升职、让已逝外公重现，也每天给夏归月惊喜。虽享有造物主般能力，她仍珍惜等待周末的期待感，并刻意不改夏归月的容貌，只反复整理逐渐模糊的现实记忆。\",\"turn\":\"天语遥沉浸理想生活，现实记忆越发被重构。\",\"time\":\"梦内一周及更久\",\"people\":[\"天语遥\",\"夏归月\",\"天语遥父母\",\"天语遥外公\"],\"objects\":[\"意念修改能力\",\"小礼物\",\"女装\"],\"places\":[\"意识世界\"]},{\"key\":\"c495\",\"id\":495,\"title\":\"天语遥的世界（三）\",\"kind\":\"main\",\"volume\":4,\"start\":1942,\"end\":1945,\"summary\":\"天语遥为带夏归月去杭州，凭意念造出机场和小客机。飞行途中真实客机穿过黑洞闯入，她担心梦境被破坏，将其强推回去，引发雷击与爆炸。随后她抹除夏归月的见闻，把旅程改写成暑假乘火车游西湖。两人在酒店谈未来开杂货店，拉钩永不分离，天语遥继续满足于补偿式幸福。\",\"turn\":\"客机灾难与现实失联新闻相接；她的幸福以控制记忆维持。\",\"time\":\"梦内由日常改写为暑假\",\"people\":[\"天语遥\",\"夏归月\",\"客机乘客\"],\"objects\":[\"梦内小客机\",\"闯入的现实客机\",\"黑洞\"],\"places\":[\"意识世界小城市机场\",\"意识世界杭州西湖与酒店\"]},{\"key\":\"c496\",\"id\":496,\"title\":\"天语遥的世界（四）\",\"kind\":\"main\",\"volume\":4,\"start\":1946,\"end\":1949,\"summary\":\"野餐时无法驱散的暴雨打破天语遥的全能感，两道陌生声音称她把梦接入真实世界投影、提供了通道。外来者进入后，她失去操纵时间、空间和天气的能力，只余少量异能。两天后校园生活仿佛重播最初两日，她确认世界线被重置，意识到自己已不能决定这片世界。\",\"turn\":\"全能梦境转成有独立规则的投影，重复日常提示世界重置。\",\"time\":\"梦内秋季、重置后的星期一二\",\"people\":[\"天语遥\",\"夏归月\",\"两名外来者\",\"天语遥母亲\",\"叶雯\"],\"objects\":[\"电话亭\",\"意念能力\"],\"places\":[\"意识世界野餐草地\",\"意识世界文澜学院\"]},{\"key\":\"c497\",\"id\":497,\"title\":\"天语遥的世界（五）\",\"kind\":\"main\",\"volume\":4,\"start\":1950,\"end\":1953,\"summary\":\"天语遥能力持续衰退，梦中的夏归月有了其他朋友与男友；她痛苦却仍肯定对方的幸福。学校跳蚤市场上，她以仅剩力量捏陶人，为小蓝和阳光少年注入身份顺遂、相伴的祝福。随后她感知到入侵者叶雯，对方与两名同伴要求捏真人陶像，她却无法直接质问来意。\",\"turn\":\"陶人连接其他人物命运；夏归月有男友仅发生于投影世界。\",\"time\":\"梦内学期\",\"people\":[\"天语遥\",\"夏归月\",\"夏归月梦中男友\",\"投影中的小蓝\",\"投影中的阳光少年\",\"叶雯\",\"叶雯两名同伴\"],\"objects\":[\"祝福陶人\",\"便签本\"],\"places\":[\"意识世界文澜学院跳蚤市场\"]},{\"key\":\"c498\",\"id\":498,\"title\":\"天语遥的世界（六）\",\"kind\":\"main\",\"volume\":4,\"start\":1954,\"end\":1957,\"summary\":\"天语遥看出叶雯灵魂缺损，将柔软的少女灵魂能量注入陶人。梦内过年后她愈发衰弱，在山头潜入叶雯的梦，见巨人击败猛虎，再构造病房说明梦境将随自己死亡而消失。她留下“这不是梦”纸条，以为即将回光返照；意识返身时握住现实夏归月的手，却不愿再睁眼。\",\"turn\":\"陶人补魂与纸条回收跨线伏笔；将死亡视为将至是天语遥判断。\",\"time\":\"梦内过年后\",\"people\":[\"天语遥\",\"叶雯\",\"夏归月\",\"巨人\",\"猛虎\",\"天语遥父母\"],\"objects\":[\"叶雯陶人\",\"这不是梦纸条\",\"巨人重剑\"],\"places\":[\"意识世界神秘山头\",\"叶雯梦中的病房\"]},{\"key\":\"c499\",\"id\":499,\"title\":\"无法治愈了的精神分裂\",\"kind\":\"main\",\"volume\":4,\"start\":1958,\"end\":1961,\"summary\":\"天语遥睁眼后意识、身份与记忆混乱，作品中的医生判断其精神疾病严重，父母多方求医后带她回家。司法支线以一名主谋无期、其余从犯十年以上收束；父亲为加重追责耗尽大量积蓄。她先暴躁后沉默，唯对夏归月保有信任。夏归月仍每日讲故事，等待恢复的可能。\",\"turn\":\"她活着但需持续照护；精神上“死亡”属修辞，不能写成肉体死亡。\",\"time\":\"长期昏迷后苏醒\",\"people\":[\"天语遥\",\"夏归月\",\"天语遥父母\",\"医护\",\"主谋及从犯\",\"双方律师\"],\"objects\":[\"精神疾病证明\",\"软陶\"],\"places\":[\"小城市医院\",\"法院\",\"天语遥家\"]},{\"key\":\"c500\",\"id\":500,\"title\":\"王海峰离职\",\"kind\":\"main\",\"volume\":4,\"start\":1962,\"end\":1965,\"summary\":\"王海峰辞职回乡前请01部门同事吃告别饭，苏雨晴的辞职也同日生效。他向她推荐近集装箱家的郊区加油站，约定三天内答复。平日互相挤兑的同事难得齐心留下陪晚班，打牌恶作剧送别；他在梯子和仓库写下名字，笑闹背后显出对下属的不舍与对上司的失望。\",\"turn\":\"超市工作正式结束，王海峰为苏雨晴留下下一份工作机会。\",\"time\":\"春末近夏\",\"people\":[\"苏雨晴\",\"王海峰\",\"陈淑艳\",\"翁锡芽\",\"01部门员工\"],\"objects\":[\"记号笔\",\"写有王海峰的梯子与仓库墙\"],\"places\":[\"超市01部门\",\"小餐馆\"]},{\"key\":\"c501\",\"id\":501,\"title\":\"买书\",\"kind\":\"main\",\"volume\":4,\"start\":1966,\"end\":1969,\"summary\":\"离职后苏雨晴白日在新华书店看书，夜晚与张思凡逛市集；林夕晨打扮后独自外出，使她隐隐不安。她照顾羞涩年轻书贩生意，尝试讨价还价买小说，发现摊上非卖陶人酷似海边别墅大小姐。对方称陶人来自远方老家；张思凡取来照片，也买下《小兵传奇》。\",\"turn\":\"陶人把陌生书贩与大小姐支线相连，林夕晨外出形成疑虑。\",\"time\":\"辞职次日\",\"people\":[\"苏雨晴\",\"张思凡\",\"林夕晨\",\"年轻书贩\",\"雯雯\"],\"objects\":[\"二手盗版小说\",\"大小姐陶人\",\"洗好的照片\",\"《小兵传奇》\"],\"places\":[\"夜市书摊\",\"新华书店\"]},{\"key\":\"c502\",\"id\":502,\"title\":\"我想来找你\",\"kind\":\"main\",\"volume\":4,\"start\":1970,\"end\":1973,\"summary\":\"五月，冉空城久违来电，提出六月放假到小城市见苏雨晴。她既担心身份变化被发现，也渴望旧友接纳，反思过去依赖与暗恋，认定如今更珍惜林夕晨。午后准备面试，林夕晨拿出名贵衣裙借她；她虽怕引起误会，仍为让对方开心而接受。\",\"turn\":\"冉空城六月来访确定，身份坦白成为待解问题。\",\"time\":\"五月、离职第二天\",\"people\":[\"苏雨晴\",\"冉空城\",\"林夕晨\",\"曲奇\",\"王海峰\"],\"objects\":[\"手机短信\",\"林夕晨的名贵衣裙\",\"小说插画\"],\"places\":[\"集装箱房及院子\"]},{\"key\":\"c503\",\"id\":503,\"title\":\"随意的面试\",\"kind\":\"main\",\"volume\":4,\"start\":1974,\"end\":1977,\"summary\":\"王海峰陪苏雨晴到郊区加油站，凭与经理的交情替她安排收银工作。她反驳“花瓶”评价，却因没有身份证只能签低保障临时合同，月薪2500元、每天十二小时且有通宵班。告别王海峰后，她感激对方教会工作也能快乐；回家换下借衣，发现林夕晨珍重地收起它。\",\"turn\":\"第三份工作落定，收入提高但劳动强度与保障不足并存。\",\"time\":\"五月、面试当日\",\"people\":[\"苏雨晴\",\"王海峰\",\"加油站经理\",\"加油站员工\",\"林夕晨\"],\"objects\":[\"临时工作合同\",\"名贵衣裙\"],\"places\":[\"郊区加油站\",\"集装箱房\"]},{\"key\":\"c504\",\"id\":504,\"title\":\"莫空的一天\",\"kind\":\"main\",\"volume\":4,\"start\":1978,\"end\":1981,\"summary\":\"莫空通宵写作后离开阁楼，看见隔壁新邻居像个男学生。他随意乘公交、按任意转向步行，刻意享受不知道下一刻的生活，在旧城区工地观察菜地、池塘与生命。带走几只蝌蚪后，他偶然走到苏雨晴住处，未打扰她，只把蝌蚪放入流动小河，寄望它们去更远地方。\",\"turn\":\"莫空寻找未知与流动生活，救蝌蚪具有拯救封闭世界生命的象征意味。\",\"time\":\"\",\"people\":[\"莫空\",\"苏雨晴\",\"林夕晨\",\"阁楼新邻居\",\"蝌蚪\"],\"objects\":[\"写作电脑\",\"纸杯与蝌蚪\"],\"places\":[\"莫空阁楼\",\"旧城区工地\",\"集装箱房外小河\"]},{\"key\":\"c505\",\"id\":505,\"title\":\"加油站的晚班\",\"kind\":\"main\",\"volume\":4,\"start\":1982,\"end\":1985,\"summary\":\"苏雨晴第一次在加油站值通宵班，既怕郊外黑暗又困倦，凌晨趴台睡去。下班后她等天亮人多才回家，险些困得失足，被狗惊醒后又由张思凡骑车送回。林夕晨替她盖毯拉窗帘。她明白高收入以疲惫换来，却愿为攒手术钱把长远愿望拆成可完成的小目标。\",\"turn\":\"独立生活的代价具体化，朋友照料与阶段目标支撑她继续工作。\",\"time\":\"首次通宵班，凌晨三点至上午\",\"people\":[\"苏雨晴\",\"张思凡\",\"林夕晨\",\"哈士奇与流浪猫狗\",\"加油站员工\"],\"objects\":[\"收银台\",\"电瓶车\",\"毛毯\"],\"places\":[\"郊区加油站\",\"回村小路\",\"集装箱房\"]},{\"key\":\"c506\",\"id\":506,\"title\":\"电话联络感情\",\"kind\":\"main\",\"volume\":4,\"start\":1986,\"end\":1989,\"summary\":\"张思凡致电忙于武汉工作的方莜莜，两人从生疏重新聊回亲密，得知她六月将见网恋对象。她们谈感情面对家庭与社会压力能否坚持、离开与放手的难处，也承认自己无法预知选择。听着电话，苏雨晴思念父母，暂想两三年后回去，羡慕林夕晨看似更容易的未来。\",\"turn\":\"异地友情需要主动维系；张思凡毕业投奔孙昊、苏雨晴返家仍为计划。\",\"time\":\"六月来访计划之前\",\"people\":[\"张思凡\",\"方莜莜\",\"苏雨晴\",\"林夕晨\",\"孙昊\",\"安念\"],\"objects\":[\"电话\"],\"places\":[\"集装箱房\",\"武汉方莜莜住处\"]},{\"key\":\"c507\",\"id\":507,\"title\":\"去给安念过生日（一）\",\"kind\":\"main\",\"volume\":4,\"start\":1990,\"end\":1993,\"summary\":\"方莜莜为安念六月十九日生日筹备见面，十七日周五下班后赶武汉火车站，却遇书内临时证件查验且找不到身份证。她回家翻找、赴已关门社区均失败，焦急中几次奔波。安念建议车站补临时证件，她又赶往车站，期待的旅程刚开始便受阻。\",\"turn\":\"身份证遗失拖延出发，焦虑使简单手续演变成反复奔波。\",\"time\":\"2005年6月17日星期五\",\"people\":[\"方莜莜\",\"安念\",\"领导\",\"车站售票员\"],\"objects\":[\"身份证\",\"行李与必需药物\",\"户口本\",\"手机\"],\"places\":[\"武汉住处\",\"武汉火车站\",\"社区办公室\"]},{\"key\":\"c508\",\"id\":508,\"title\":\"去给安念过生日（二）\",\"kind\":\"main\",\"volume\":4,\"start\":1994,\"end\":1998,\"summary\":\"方莜莜到车站才知办临时证件人员已下班，只能翌日再走。安念用短信和玩笑安慰，旧日铁友杨豪伟也因群消息来电。回忆揭示他曾在得知她女性化选择后转为支持，关系一度暧昧，后来换工作分隔。她不由比较二人的关心，又试着把对杨豪伟的感情归为友情。\",\"turn\":\"杨豪伟重新进入感情线，方莜莜的情感判断出现摇摆。\",\"time\":\"6月17日夜\",\"people\":[\"方莜莜\",\"安念\",\"杨豪伟\",\"杨豪伟前女友\"],\"objects\":[\"临时身份证申请表\",\"群消息\",\"电话短信\"],\"places\":[\"武汉火车站\",\"公交车\",\"方莜莜家\"]},{\"key\":\"c509\",\"id\":509,\"title\":\"去给安念过生日（三）\",\"kind\":\"main\",\"volume\":4,\"start\":1999,\"end\":2002,\"summary\":\"十八日清晨方莜莜终于拿到临时身份证，却发现买票已不再查验，哭笑不得。杨豪伟细细叮嘱旅途与识人，安念则询问车次、定时叫醒她。她在列车上补眠后于下午到杭州城站，挤过人潮与一名乘客的地域歧视，联系安念寻找出口，紧张期待真正见面。\",\"turn\":\"旅程顺利抵达，两种不同的关心持续影响她的比较。\",\"time\":\"6月18日、约17:15到杭州\",\"people\":[\"方莜莜\",\"安念\",\"杨豪伟\",\"车站乘客\"],\"objects\":[\"临时身份证\",\"火车票\",\"手机闹钟\"],\"places\":[\"武汉火车站\",\"武汉至杭州列车\",\"杭州城站\"]},{\"key\":\"c510\",\"id\":510,\"title\":\"去给安念过生日（四）\",\"kind\":\"main\",\"volume\":4,\"start\":2003,\"end\":2006,\"summary\":\"安念在杭州车站认出方莜莜，她见到的青年比想象胖，却坦言仍很高兴，两人很快自在地调笑。骑电瓶车回家途中她主动拥住他，他介绍母亲已知她身份并欢迎来访。方莜莜选择住他家省钱，在旧厂宿舍区见到亲切的母亲，进入杂乱却干净的房间，一起打开电脑。\",\"turn\":\"网恋由想象进入真实相处，母亲知身份但未明确知恋爱关系。\",\"time\":\"6月18日晚前\",\"people\":[\"方莜莜\",\"安念\",\"安念母亲\"],\"objects\":[\"电瓶车\",\"电脑\",\"双层床\",\"动漫手办\"],\"places\":[\"杭州城站\",\"安念家旧厂宿舍区\"]},{\"key\":\"c511\",\"id\":511,\"title\":\"去给安念过生日（五）\",\"kind\":\"main\",\"volume\":4,\"start\":2007,\"end\":2010,\"summary\":\"安念陪方莜莜玩拳皇后被母亲叫去煎牛排，母子相互打趣的自在家庭氛围让她羡慕，也反衬自己与严父、继母的距离。晚餐用现成酱料搭配牛排，安念吃掉焦的一份和剩菜，显出幽默与节俭。方莜莜逐渐放松，关心他别勉强吃太多，亲密感在家常晚餐中加深。\",\"turn\":\"温暖家常使方莜莜卸下拘谨，更愿与安念靠近。\",\"time\":\"6月18日晚\",\"people\":[\"方莜莜\",\"安念\",\"安念母亲\",\"方莜莜父亲与继母\"],\"objects\":[\"《拳皇》\",\"牛排与三种酱料\"],\"places\":[\"安念家厨房餐桌\"]},{\"key\":\"c512\",\"id\":512,\"title\":\"去给安念过生日（六）\",\"kind\":\"main\",\"volume\":4,\"start\":2011,\"end\":2015,\"summary\":\"方莜莜与安念同床，发现他紧张却克制，没有擅自越界。她主动开启关于恋爱经历的谈话并邀请亲近，二人慢慢放松、彼此试探，最后握手睡去。次晨在母亲忙早餐的声音中醒来，两人因昨夜的靠近而羞涩，网恋逐渐长成真实的信任与亲密。\",\"turn\":\"安念尊重界限，方莜莜在关系中较主动，二人未发生进一步性行为。\",\"time\":\"6月18日夜至19日晨\",\"people\":[\"方莜莜\",\"安念\",\"安念母亲\"],\"objects\":[\"掌上游戏机\",\"双层床\"],\"places\":[\"安念卧室\"]},{\"key\":\"c513\",\"id\":513,\"title\":\"去给安念过生日（七）\",\"kind\":\"main\",\"volume\":4,\"start\":2016,\"end\":2019,\"summary\":\"六月十九日生日当天，方莜莜吃过安家早餐，羡慕母子自在争论后随安念游西湖。她珍惜牵手相伴，二人为留下纪念拍了四张照片，各保留对方单照和合影。随后经吴山广场逛河坊街，安念为她买喜欢的小物，日常消费体现关心，也让节俭的她心疼。\",\"turn\":\"照片成为首次相聚的重要纪念，相伴比景点更吸引她。\",\"time\":\"6月19日星期日\",\"people\":[\"方莜莜\",\"安念\",\"安念母亲\",\"摄影师\"],\"objects\":[\"四张西湖照片\",\"河坊街小商品\"],\"places\":[\"安念家\",\"西湖\",\"吴山广场\",\"河坊街\"]},{\"key\":\"c514\",\"id\":514,\"title\":\"去给安念过生日（八）\",\"kind\":\"main\",\"volume\":4,\"start\":2020,\"end\":2023,\"summary\":\"游河坊街时杨豪伟来电关心，方莜莜担心他吃醋，又难拒其在杭州吃饭的邀约，带安念赴会。她要求在杨豪伟面前只称安念为普通朋友，暴露自己对旧友的依恋；安念察觉却配合、不追问。四人上车，杨豪伟现女友明显不悦，原本二人生日约会转为尴尬四人行。\",\"turn\":\"方莜莜对旧友与恋人的感情冲突显形，安念选择克制照顾。\",\"time\":\"6月19日中午前\",\"people\":[\"方莜莜\",\"安念\",\"杨豪伟\",\"杨豪伟现女友\"],\"objects\":[\"猫狗糖人\",\"手机短信\",\"杨豪伟轿车\"],\"places\":[\"河坊街\",\"古荡路附近\"]},{\"key\":\"c515\",\"id\":515,\"title\":\"请出示本人身份证\",\"kind\":\"main\",\"volume\":4,\"start\":2024,\"end\":2027,\"summary\":\"杨豪伟带女友、方莜莜与安念吃西餐，熟记方莜莜口味的照顾加重女友不悦，安念努力保持礼貌。饭后又去高档网络会所，方莜莜愿意继续留下。办上网时收银员因证件男性照片与她外表不符拒绝，安念想解释却被拉住，身份暴露的困境打断游玩。\",\"turn\":\"证件与外貌差异造成现实障碍，四人关系仍紧绷。\",\"time\":\"6月19日下午\",\"people\":[\"方莜莜\",\"安念\",\"杨豪伟\",\"杨豪伟现女友\",\"网吧收银员\"],\"objects\":[\"身份证件\",\"牛排\",\"网费\"],\"places\":[\"西餐厅\",\"网络会所\"]},{\"key\":\"c516\",\"id\":516,\"title\":\"到底是什么感情\",\"kind\":\"main\",\"volume\":4,\"start\":2028,\"end\":2031,\"summary\":\"方莜莜首先求助杨豪伟，他向会所经理解释她身份后才获准上网，但旁人眼光仍刺痛人。四人沉默地玩魔兽争霸，安念看出她对旧友的依恋却不使其难堪。离开后雨中共伞步行，方莜莜开始坦白混乱感情，称彼此是情侣并要求真心回应，安念终于承认吃醋。\",\"turn\":\"情侣开始直接谈嫉妒与依赖，安念体谅不等于没有受伤。\",\"time\":\"6月19日下午至晚间\",\"people\":[\"方莜莜\",\"安念\",\"杨豪伟\",\"杨豪伟现女友\",\"会所经理与收银员\"],\"objects\":[\"身份证件\",\"《魔兽争霸》\",\"雨伞\"],\"places\":[\"网络会所\",\"回家雨路\"]},{\"key\":\"c517\",\"id\":517,\"title\":\"公交卡不见了\",\"kind\":\"main\",\"volume\":4,\"start\":2032,\"end\":2035,\"summary\":\"雨中安念表示若方莜莜更爱旧友便尊重选择，她却觉得这像放弃责任，要求坦诚。他们谈无法保证的未来，最终互说爱意。回家发现借母亲的公交卡丢失，两人下楼找回，紧张转为有惊无险。之后共享姨娘订的朴素水果蛋糕，方莜莜记起安念曾送自己的蛋糕。\",\"turn\":\"明确互诉爱意，生日在小波折与亲密交谈中完成。\",\"time\":\"6月19日晚\",\"people\":[\"方莜莜\",\"安念\",\"安念母亲\",\"安念姨娘\"],\"objects\":[\"雨伞\",\"母亲的公交卡\",\"生日水果蛋糕\"],\"places\":[\"雨中街道\",\"安念家楼下与家中\"]},{\"key\":\"c518\",\"id\":518,\"title\":\"目送着离去\",\"kind\":\"main\",\"volume\":4,\"start\":2036,\"end\":2040,\"summary\":\"方莜莜为多陪安念一天请假，担心原声破坏形象，他表示接受完整的她。第二夜两人更加亲密仍保持克制。二十日一起在网吧度过，晚间安念送站时坦言自己也曾向往女性身份，后来选择现状。两人先走错东站，幸而提前出发赶到城站，依依目送告别。\",\"turn\":\"生日之旅结束，异地恋确认；安念过去身份探索被披露。\",\"time\":\"6月19日夜至20日夜\",\"people\":[\"方莜莜\",\"安念\",\"方莜莜领导\"],\"objects\":[\"请假电话\",\"火车票\",\"电瓶车\"],\"places\":[\"安念家\",\"杭州网吧\",\"杭州东站\",\"杭州城站\"]},{\"key\":\"c519\",\"id\":519,\"title\":\"官二代的骚扰\",\"kind\":\"main\",\"volume\":4,\"start\":2041,\"end\":2044,\"summary\":\"曲奇与咖啡偷偷跟苏雨晴到加油站，陪她在白班幻想自由与未来。一位被称二少的男子买烟、无视禁烟要求并纠缠邀约，经理认出他是挂名副经理后借喝酒解围。同事称其为市长次子，依靠家庭权势游荡享乐；苏雨晴厌恶其摆阔，新的职场骚扰隐患出现。\",\"turn\":\"二少对苏雨晴起意，经理暂时解围；家庭职位来自书内同事说法。\",\"time\":\"夏季白班\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"二少\",\"加油站经理与同事\"],\"objects\":[\"中华香烟\",\"奔驰钥匙\"],\"places\":[\"郊区加油站\"]},{\"key\":\"c520\",\"id\":520,\"title\":\"一万块钱一个晚上\",\"kind\":\"main\",\"volume\":4,\"start\":2045,\"end\":2048,\"summary\":\"二少纠缠整日，经理帮腔迫使苏雨晴赴高档餐厅。她对豪车、排场和炫耀毫不心动，离开时二少以一万元换一夜，她把钱甩回去后独自离开。气愤之外，她担忧失去工作或遭报复。张思凡到车站接她，听完经过也只能先劝避开，生活安稳受到权势骚扰威胁。\",\"turn\":\"她坚决拒绝金钱侮辱，但暂无应对二少权势的办法。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"二少\",\"加油站经理\",\"张思凡\",\"曲奇\",\"咖啡\"],\"objects\":[\"一万元现金\",\"奔驰车\"],\"places\":[\"小城大厦餐厅\",\"公交总站\"]},{\"key\":\"c521\",\"id\":521,\"title\":\"陪酒（上）\",\"kind\":\"main\",\"volume\":4,\"start\":2049,\"end\":2052,\"summary\":\"林夕晨第一人称揭示寡言无表情是遮掩痛苦、避免影响苏雨晴的方式。她虽珍惜恋人相伴，仍须精心打扮去见一位秃顶富商，谎称外出事务。原有积蓄本可做矫正手术，却因父亲患病另有用途；她乘上富商的奔驰，被迫承受越来越难忍的要求来维持收入。\",\"turn\":\"林夕晨外出真正原因揭晓，保护恋人的沉默与谋生困境相连。\",\"time\":\"夏季休息日\",\"people\":[\"林夕晨\",\"苏雨晴\",\"秃顶富商\",\"林夕晨父亲\",\"曲奇\",\"黄色土狗\"],\"objects\":[\"富商所赠衣裙\",\"奔驰车\",\"狗尾巴草\"],\"places\":[\"集装箱房\",\"乡间小路\",\"公交总站\"]},{\"key\":\"c522\",\"id\":522,\"title\":\"陪酒（下）\",\"kind\":\"main\",\"volume\":4,\"start\":2053,\"end\":2056,\"summary\":\"林夕晨被富商带到郊外别墅陪酒接待生意伙伴，承受被物化和性剥削，靠酒意熬过过程。她解释稿费不足同时负担父亲治疗与全家生活，姐妹因父亲长期偏心不愿照料，自己虽想退出仍无法断钱。醒后她收下款项，梦中与苏雨晴相拥却无法消除现实负担。\",\"turn\":\"金钱暂缓家病却深化剥削与自责；父亲疗养和家庭供养持续。\",\"time\":\"与c521同日\",\"people\":[\"林夕晨\",\"秃顶富商\",\"富商生意伙伴\",\"林夕晨父母与姐姐们\",\"苏雨晴\"],\"objects\":[\"红酒\",\"生活费现金\"],\"places\":[\"郊区别墅区\"]},{\"key\":\"c523\",\"id\":523,\"title\":\"林夕晨第一视角\",\"kind\":\"main\",\"volume\":4,\"start\":2057,\"end\":2060,\"summary\":\"回程中林夕晨反思自由、压抑与自身复杂动机：她既希望父亲康复，也盼停止汇款、尽早完成手术退出包养。回家苏雨晴因读悲伤小说而害怕别离，主动抱住她、问能否永远相伴。林夕晨给出安慰承诺，却因自己隐瞒的经历深觉不配；被问酒味时转移话题。\",\"turn\":\"两人的深爱与信息不对等并存，“永远”是安慰而非命运保证。\",\"time\":\"同日傍晚\",\"people\":[\"林夕晨\",\"苏雨晴\",\"林夕晨父亲\"],\"objects\":[\"木桩小路\",\"悲伤文学小说\",\"酒味\"],\"places\":[\"回家小路\",\"集装箱房\"]},{\"key\":\"c524\",\"id\":524,\"title\":\"平静的生活，是因为有人帮你挡住了风雨，定住了波澜\",\"kind\":\"main\",\"volume\":4,\"start\":2061,\"end\":2064,\"summary\":\"二少再次以权势威胁苏雨晴赴饭局，她勉强应下但坚持乘出租车保持距离。餐厅另一边，她多年未见的大舅苏书记（原章误称大伯，c573更正）与二少父亲王市长谈升迁，认出外甥女后暗示不得乱来。王市长立即承诺照顾，潜在风波在苏雨晴毫不知情中被长辈挡下，揭开她安稳背后的隐形保护。\",\"turn\":\"大舅暗中施压平息骚扰，苏雨晴仍以为无后台；旧称大伯已由作者更正。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"二少\",\"苏书记（大舅，早先误称大伯）\",\"王市长\",\"加油站员工\"],\"objects\":[\"出租车\",\"饭局\"],\"places\":[\"中式餐厅\"]},{\"key\":\"c525\",\"id\":525,\"title\":\"突然的到来\",\"kind\":\"main\",\"volume\":4,\"start\":2065,\"end\":2068,\"summary\":\"二少多日不再纠缠，苏雨晴不明缘故。六月将尽，冉空城上车后才告知下午抵达，她仓促请假，惊讶经理和在场二少都痛快放行。她回家换厚实中性衣物掩饰身体变化、调整声线后接站。长高的冉空城仍把她当旧日好友，用女孩玩笑迎接，她既激动又怕秘密暴露。\",\"turn\":\"朋友到来迫使身份问题进入现实，二少已明显忌惮她。\",\"time\":\"六月、来访首日星期六\",\"people\":[\"苏雨晴\",\"冉空城\",\"林夕晨\",\"二少\",\"加油站经理\"],\"objects\":[\"运动背心与外套\",\"手机短信\"],\"places\":[\"加油站办公室\",\"集装箱房\",\"小城市火车站\"]},{\"key\":\"c526\",\"id\":526,\"title\":\"你最近过的怎么样\",\"kind\":\"main\",\"volume\":4,\"start\":2069,\"end\":2073,\"summary\":\"冉空城询问苏雨晴近况，仍以为她转学到本地；她继续隐瞒离家打工。公园聊天渐恢复熟悉感，他带来全班同学录与一盒发卡，解释一些旧同学已道歉、仍记挂她，并提到跳级的班长金晶。苏雨晴读留言感动，熟练戴上胡萝卜发卡，让冉空城对她的女性气质愈发惊讶。\",\"turn\":\"同学录重建校园记忆；所谓善意戏弄属人物解释，不能否认既有伤害。\",\"time\":\"来访首日下午\",\"people\":[\"苏雨晴\",\"冉空城\",\"金晶\",\"旧同学\"],\"objects\":[\"同学录\",\"三层发卡盒\",\"胡萝卜发卡\",\"餐巾纸\"],\"places\":[\"小城市公园\"]},{\"key\":\"c527\",\"id\":527,\"title\":\"软软的，凉凉的\",\"kind\":\"main\",\"volume\":4,\"start\":2074,\"end\":2077,\"summary\":\"旧友轻松互逗，冉空城注意到苏雨晴更开朗，也被她冰凉柔软的手与拥抱触动，却以“只是男孩好友”压下异样。两人在步行街给陶坯上色，她细描哆啦A梦，他把足球涂得五彩。傍晚替他找旅馆后约次日海边，苏雨晴在他向往独住的自由时想起自己对家的思念。\",\"turn\":\"冉空城有吸引与自我压抑，尚未承认恋爱感情。\",\"time\":\"来访首日下午至晚间\",\"people\":[\"苏雨晴\",\"冉空城\"],\"objects\":[\"胡萝卜发卡\",\"哆啦A梦陶坯\",\"彩色足球陶坯\"],\"places\":[\"小城市步行街\",\"旅馆\"]},{\"key\":\"c528\",\"id\":528,\"title\":\"湿身\",\"kind\":\"main\",\"volume\":4,\"start\":2078,\"end\":2081,\"summary\":\"翌日苏雨晴费力叫醒冉空城，两人去海边堆沙堡和海龟。冉空城玩闹把她带进浅水、意外碰触身体，引发她不适与身份冲突。她终于坦白一直想作为女孩生活、正在服药，坚决不愿回头。冉空城先担忧身体与后悔，确认她决定后仍认她为最好的朋友，并祝她幸福。\",\"turn\":\"苏雨晴向圈外最重要旧友坦白身份，得到支持与接纳。\",\"time\":\"来访第二日星期日\",\"people\":[\"苏雨晴\",\"冉空城\"],\"objects\":[\"沙堡与海龟\",\"被海水打湿的衣服\"],\"places\":[\"小城市海滩\"]},{\"key\":\"c529\",\"id\":529,\"title\":\"打开天窗说亮话\",\"kind\":\"main\",\"volume\":4,\"start\":2082,\"end\":2085,\"summary\":\"坦白后的二人在海边笑开，苏雨晴进一步问冉空城是否曾有恋爱式喜欢，他认真答一直视她为好友，表明自己偏爱顺性别女性。她接受边界，也说自己爱人并不先看性别。她仍隐瞒离家事实，转谈金晶跳级、将来学业与旧事，最后为投其所好约去电玩城。\",\"turn\":\"旧暗恋获明确答复，身份被接受但并未建立情侣关系。\",\"time\":\"来访第二日傍晚前\",\"people\":[\"苏雨晴\",\"冉空城\",\"金晶\"],\"objects\":[\"晒干的衣物\"],\"places\":[\"小城市海滩\",\"电玩城（计划）\"]},{\"key\":\"c530\",\"id\":530,\"title\":\"张思凡毕业了\",\"kind\":\"main\",\"volume\":4,\"start\":2086,\"end\":2089,\"summary\":\"冉空城逗留数日离开，张思凡又宣布毕业后将去孙昊处，九月土地到期也无法续租，苏雨晴须另找住所。林夕晨画下夕阳道别的人群陪她感伤。加油站首月工资另附千元奖金，引发同事恶意猜测；苏雨晴却为手术基金接近目标而振作，同时注意林夕晨常寄大笔钱回家。\",\"turn\":\"张思凡即将离开、搬家将至；奖励暗含家族保护，来钱误解增多。\",\"time\":\"夏季毕业季、租约至九月\",\"people\":[\"苏雨晴\",\"张思凡\",\"林夕晨\",\"冉空城\",\"孙昊\",\"加油站同事\",\"土地出租人\"],\"objects\":[\"夕阳告别画\",\"工资与千元奖金\",\"汇款信封\"],\"places\":[\"集装箱房\",\"郊区加油站\"]},{\"key\":\"c531\",\"id\":531,\"title\":\"林夕晨的家事（上）\",\"kind\":\"main\",\"volume\":4,\"start\":2090,\"end\":2093,\"summary\":\"林夕晨独自在家笨拙做蔬菜汤，照料聚来的猫狗，珍惜平淡生活。代收店通知家信已到，她担心父亲肿瘤恶化却仍去取信。途中她看见咖啡毛色变白、活动减少，预感宠物终将告别，并担心苏雨晴会受打击。她顺路买猫狗粮与玩具，慷慨照顾动物而自己节俭。\",\"turn\":\"家信与咖啡衰老同时预告生活负担和失去；并未在此死亡。\",\"time\":\"\",\"people\":[\"林夕晨\",\"曲奇\",\"咖啡\",\"流浪猫狗\",\"林夕晨父亲\"],\"objects\":[\"家信\",\"蔬菜汤\",\"猫狗粮与玩具\"],\"places\":[\"集装箱房\",\"代收信件杂货店\",\"超市\"]},{\"key\":\"c532\",\"id\":532,\"title\":\"林夕晨的家事（下）\",\"kind\":\"main\",\"volume\":4,\"start\":2094,\"end\":2097,\"summary\":\"大姐艰难写成的信说明父亲劳作后病情加重，母亲坚持住院，所需钱更多。林夕晨考虑手术与长期费用，回想曾拒绝更残忍的富商朋友，如今将其当作绝境备用，却仍盼先给父亲治疗。她到加油站探望苏雨晴，分巧克力、带曲奇咖啡玩，共挤一椅获得短暂慰藉。\",\"turn\":\"经济压力再升级，更危险的交易被提出但此时未接受。\",\"time\":\"父亲上周再次就医\",\"people\":[\"林夕晨\",\"林夕晨大姐\",\"林夕晨父母与姐姐们\",\"秃顶富商的虐待型朋友\",\"苏雨晴\",\"曲奇\",\"咖啡\"],\"objects\":[\"大姐的家信\",\"巧克力\"],\"places\":[\"公交车\",\"郊区加油站\"]},{\"key\":\"c533\",\"id\":533,\"title\":\"只剩下两个人\",\"kind\":\"main\",\"volume\":4,\"start\":2098,\"end\":2101,\"summary\":\"张思凡正式离开投奔孙昊，集装箱只余苏雨晴与林夕晨。苏雨晴看衰老咖啡想到离别，接报平安电话时仍压下挽留，也担心孙昊为人。空冰箱提醒她必须自己当家，她将找房等计划写进日记。张思凡留下游戏机与电动车，苏雨晴笨拙载恋人进城采购，孤单中又体会二人生活。\",\"turn\":\"同住群体缩为二人，照料责任正式转交，找新房提上日程。\",\"time\":\"距九月租约到期约两个月\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"孙昊\",\"曲奇\",\"咖啡\"],\"objects\":[\"日记本\",\"最后一罐雪碧\",\"游戏机\",\"电动车\"],\"places\":[\"集装箱房\",\"进城道路\"]},{\"key\":\"c534\",\"id\":534,\"title\":\"胸部的感觉\",\"kind\":\"main\",\"volume\":4,\"start\":2102,\"end\":2105,\"summary\":\"林夕晨视角写苏雨晴紧张学骑电动车载她赴世纪联华，两人在周年促销人潮中互相照顾。她想说鼓励的话却发现长期寡言已难表达，面具成了束缚。采购间苏雨晴为身体变化挑新内衣、羞涩征求意见，林夕晨耐心协助，二人亲近，也暴露她内心远比外表活跃。\",\"turn\":\"林夕晨情感丰富的内心与沉默外貌形成反差，同居互助加深。\",\"time\":\"张思凡离开后采购当日\",\"people\":[\"林夕晨\",\"苏雨晴\",\"超市顾客\"],\"objects\":[\"电动车\",\"新内衣\",\"周年促销券\"],\"places\":[\"世纪联华超市与试衣间\"]},{\"key\":\"c535\",\"id\":535,\"title\":\"同居的感觉\",\"kind\":\"main\",\"volume\":4,\"start\":2106,\"end\":2109,\"summary\":\"两人买下衣物、食品、记事本等许多用品，才遇到电动车如何载货的问题，最终分配重量缓慢安全回家。林夕晨回忆父亲珍爱的凤凰自行车与童年偏爱；夜路相依、狗群迎接让她感到真正同居的甜蜜，也不舍将离开郊外。安顿采购后她继续赶画稿，期待与苏雨晴相伴。\",\"turn\":\"生活琐事成为亲密体验，搬家将同时失去自然环境与动物陪伴。\",\"time\":\"采购当日夜晚\",\"people\":[\"林夕晨\",\"苏雨晴\",\"林夕晨父亲\",\"哈士奇与土狗\"],\"objects\":[\"漂亮记事本\",\"小台灯\",\"食材\",\"电动车\",\"凤凰牌自行车（回忆）\"],\"places\":[\"世纪联华\",\"夜间郊路\",\"集装箱房\"]},{\"key\":\"c536\",\"id\":536,\"title\":\"以后每天都一起洗澡\",\"kind\":\"main\",\"volume\":4,\"start\":2110,\"end\":2113,\"summary\":\"共浴与同寝使苏雨晴、林夕晨的身体亲密进一步发展，两人互诉爱意，但苏也多次表达羞涩、犹豫及停止的要求。次晨苏明确提出希望不要再像昨夜那样，林答应；苏赶着上班，林扶稳她并提醒骑车、吃早饭。甜蜜和边界协商并存，不能把犹豫一律当作默认同意。\",\"turn\":\"亲密关系深化，苏提出边界，林作出回应。\",\"time\":\"采购后当夜及次晨\",\"people\":[\"苏雨晴\",\"林夕晨\"],\"objects\":[\"浴缸\",\"电动车\"],\"places\":[\"集装箱房\"]},{\"key\":\"c537\",\"id\":537,\"title\":\"暂未同居\",\"kind\":\"main\",\"volume\":4,\"start\":2114,\"end\":2117,\"summary\":\"张思凡已搬到孙昊所在城市，却因孙以学生宿舍不便为由，仍独住狭小出租屋，暂未求职，动用原为手术积攒的钱。她看见孙在小说读者群中广泛调情而吃醋，又顾虑管束太多。孙强烈反对她穿男装约会，随后在熟悉的校园废弃迷宫与她亲近，并答应不再乱撩。\",\"turn\":\"“投奔恋人”尚未带来同居；群聊调情、男装禁忌和熟悉隐秘约会处埋下疑问。\",\"time\":\"搬往孙昊城市后、暑期\",\"people\":[\"张思凡\",\"孙昊\"],\"objects\":[\"电脑\",\"小说读者群\",\"女装\"],\"places\":[\"张思凡的新出租屋\",\"孙昊学校\",\"废弃迷宫\"]},{\"key\":\"c538\",\"id\":538,\"title\":\"住在一起\",\"kind\":\"main\",\"volume\":4,\"start\":2118,\"end\":2122,\"summary\":\"2005年八月中旬，方莜莜辞去武汉工作，安念进入自主实习期，两人相约赴宁波共同生活。拖着行李探索炎热街道后，他们通过中介租下便宜单间，再买钢丝床与原有小床拼接。简陋拥挤的小家令两人充满期待；方主动讨论亲密关系，安则以婚姻和责任为由迟疑。\",\"turn\":\"武汉与杭州的异地恋转为宁波共同生活，爱情开始接受现实开销与责任考验。\",\"time\":\"2005年8月中旬\",\"people\":[\"方莜莜\",\"安念\",\"房屋中介\"],\"objects\":[\"行李\",\"钢丝床\",\"出租广告\"],\"places\":[\"宁波\",\"宁波出租单间\"]},{\"key\":\"c539\",\"id\":539,\"title\":\"苏雨晴和林夕晨的小窝\",\"kind\":\"main\",\"volume\":4,\"start\":2123,\"end\":2125,\"summary\":\"九月将至，苏雨晴逐渐适应加油站工作，二少仍未再纠缠。集装箱租期结束，张思凡预先找好买家，连同家具处置所得留给两人。林找到月租八百元、两人平分的海景小房，留下空调、热水器和木桌；曲奇与咖啡随迁。新居有海景、阳台厨房和窄床，但失去原来的狗群与旷野生活。\",\"turn\":\"两人迁入海景房；住房为何便宜尚未揭开，积蓄仍受生活开销牵制。\",\"time\":\"2005年九月将至\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"曲奇\",\"咖啡\"],\"objects\":[\"集装箱\",\"空调\",\"热水器\",\"实木桌\",\"小冰箱\"],\"places\":[\"海景出租屋\",\"集装箱房\",\"夜市\"]},{\"key\":\"c540\",\"id\":540,\"title\":\"苏雨晴的小回忆\",\"kind\":\"main\",\"volume\":4,\"start\":2126,\"end\":2129,\"summary\":\"夜市书摊已换了中年摊主，苏雨晴因找不到原先普通却亲切的年轻人而失落。她回想张仍同住时与卖书少年讨价还价、一起收摊避开城管，并跳上他的三轮车逃离的偶遇；事后少年道谢独自离开，她自行返回，与带回肯德基的张会合。林将她从旧日幻想唤回，两人继续买灯。\",\"turn\":\"短暂相逢成为苏珍藏的幻想；少年身份和离开原因本章均未交代。\",\"time\":\"搬家后夜市，插叙张离开前\",\"people\":[\"苏雨晴\",\"林夕晨\",\"张思凡\",\"卖书少年\",\"城管\",\"夜市新摊主\"],\"objects\":[\"旧书\",\"盗版光盘\",\"三轮车\",\"饮用水\",\"小台灯\"],\"places\":[\"夜市书摊\",\"陌生小路\"]},{\"key\":\"c541\",\"id\":541,\"title\":\"安念和方莜莜的日常（一）\",\"kind\":\"main\",\"volume\":4,\"start\":2130,\"end\":2133,\"summary\":\"在宁波找工作之前，安念与方莜莜拿纸地图逐处游玩，用五角星标记去过的地方，只剩郊外未探索。方想开奶茶店，摆脱求职时证件和外貌不符的限制；安建议先在店中学习，自己去码头挣钱减重，再共同经营。两人讨论租金、独立和女装愿望，怀抱创业憧憬；回望式叙述却预示这份相伴可能变化。\",\"turn\":\"奶茶店成为共同未来方案，但资金、工作身份及长久相伴尚无保证。\",\"time\":\"宁波同居初期、尚未入职\",\"people\":[\"安念\",\"方莜莜\"],\"objects\":[\"纸地图\",\"五角星标记\",\"零食\"],\"places\":[\"宁波\",\"宁波大学科技学院校区\"]},{\"key\":\"c542\",\"id\":542,\"title\":\"安念和方莜莜的日常（二）\",\"kind\":\"main\",\"volume\":4,\"start\":2134,\"end\":2137,\"summary\":\"方莜莜做简单早餐，两人带满零食和罐头到宁波郊外踏青，看田地、施工和山边住宅，畅想山居生活。他们谈到钱与女性身份何者更重要，显出侧重差异，又用树枝当手杖攀上陡坡。山顶分享食物时，方在树上刻下两人的名字、日期及永远在一起的愿望，把出游变成对未来的约定。\",\"turn\":\"刻字约定加强伴侣共同愿景，理想生活与现实劳动形成对照。\",\"time\":\"宁波同居初期一次郊游\",\"people\":[\"安念\",\"方莜莜\"],\"objects\":[\"蒸饺\",\"罐头\",\"树枝手杖\",\"刻字许愿树\"],\"places\":[\"宁波郊外\",\"山顶\"]},{\"key\":\"c543\",\"id\":543,\"title\":\"安念和方莜莜的日常（三）\",\"kind\":\"main\",\"volume\":4,\"start\":2138,\"end\":2141,\"summary\":\"初秋，两人结束游城生活。方莜莜以男装进入奶茶店，从早九点做到晚九点；安念则从早六点在码头搬货，希望挣钱并减肥。工头带队承接船货，日常伙食粗劣、劳动沉重。李船长赶来催促，虽态度傲慢，却因报酬高让工人重新振作。安拼命完成工作，领钱买小摆件回家，方还未下班。\",\"turn\":\"爱情愿景转入长工时现实；两人时刻错开，安开始积累身体疲惫。\",\"time\":\"2005年初秋\",\"people\":[\"安念\",\"方莜莜\",\"码头工头\",\"李船长\",\"码头工人\",\"奶茶店女同事\"],\"objects\":[\"货箱\",\"盒饭\",\"小摆件\"],\"places\":[\"宁波码头\",\"奶茶店\",\"宁波出租单间\"]},{\"key\":\"c544\",\"id\":544,\"title\":\"安念和方莜莜的日常（四）\",\"kind\":\"main\",\"volume\":4,\"start\":2142,\"end\":2145,\"summary\":\"安念晚间疲惫早睡，方莜莜很晚才归，亲密相处被不同班次压缩。安因天气变化到码头才知停工，工头忘了通知，便带他出海钓鱼。两人钓到一面银色、一面虹彩的奇鱼；工头提起祖辈传说，许下与女儿有关但未被完整听见的愿望，安许愿与方永远相伴，然后将鱼放生。\",\"turn\":\"奇鱼与树上誓言呼应；愿望是否灵验及工头女儿具体处境均未交代。\",\"time\":\"两人入职后，天气致码头停工的一天\",\"people\":[\"安念\",\"方莜莜\",\"码头工头\",\"工头女儿（提及）\"],\"objects\":[\"闹钟手机\",\"鱼竿\",\"小船\",\"虹彩许愿鱼\"],\"places\":[\"宁波出租单间\",\"码头外礁石\"]},{\"key\":\"c545\",\"id\":545,\"title\":\"张思凡和孙昊的日常（上）\",\"kind\":\"main\",\"volume\":4,\"start\":2146,\"end\":2149,\"summary\":\"张思凡仍未求职，去瑜伽班练体态，并努力遮掩身体特征。女教师训练严厉，其他学员的好奇触碰使她窘迫，她也拒绝结伴吃饭以自认忠于孙昊。电话中的孙气息异常，解释正与朋友玩牌，末尾又似有女子声音；张压下疑心，约定傍晚看电影，仍盼他冬季毕业后正式同居。\",\"turn\":\"张的忠诚和期待与可疑电话形成信息差，尚不知道孙的另一段关系。\",\"time\":\"入秋，孙昊毕业前\",\"people\":[\"张思凡\",\"孙昊\",\"瑜伽女教师\",\"瑜伽女学员\"],\"objects\":[\"瑜伽服\",\"手机\"],\"places\":[\"瑜伽班\",\"张思凡的新出租屋\"]},{\"key\":\"c546\",\"id\":546,\"title\":\"张思凡和孙昊的日常（下）\",\"kind\":\"main\",\"volume\":4,\"start\":2150,\"end\":2153,\"summary\":\"孙昊迟到后用拥抱和恐怖片约会安抚张思凡。张闻到他身上的香水味，孙拿出小香水瓶称是给她试用的礼物，又安排烛光晚餐，随后借朋友打架需去派出所之名离开。叙述转向孙，明确揭示他当天与莉莉亲密来往，香味来自她；他接着给莉莉打电话，买花上门，重复同样的浪漫说辞。\",\"turn\":\"孙同时交往及撒谎获得叙事确认；张被礼物解释安抚，尚不知背叛。\",\"time\":\"c545约定的当晚\",\"people\":[\"张思凡\",\"孙昊\",\"莉莉\"],\"objects\":[\"香水瓶\",\"电影票\",\"蜡烛\",\"花束\",\"手机\"],\"places\":[\"电影院\",\"咖啡厅\",\"莉莉住处\"]},{\"key\":\"c547\",\"id\":547,\"title\":\"新房子感觉怎么样？\",\"kind\":\"main\",\"volume\":4,\"start\":2154,\"end\":2157,\"summary\":\"林夕晨回到供养她的富商别墅，忆及此前寄居与陪伴富商的生活。古筝断弦后，富商带她买新琴，谈话揭露海景房本是他的产业，林坚持交租以减少亏欠。她提手术，富商表明身体改变后将停止供养，又要她介绍漂亮男孩；她想到苏雨晴后立刻拒绝。在琴店，她挑中无名制作者寄售的素木古筝，弹《高山流水》，期待弹给苏听。\",\"turn\":\"住房与经济依赖真相揭开；林保护苏却继续隐瞒，手术愿望与供养条件发生冲突。\",\"time\":\"迁入海景房之后\",\"people\":[\"林夕晨\",\"富商\",\"古筝店老板\",\"苏雨晴（想及）\"],\"objects\":[\"断弦旧古筝\",\"素木古筝\",\"海景房房租\"],\"places\":[\"富商别墅\",\"古筝专卖店\",\"富商汽车\"]},{\"key\":\"c548\",\"id\":548,\"title\":\"讨好\",\"kind\":\"main\",\"volume\":4,\"start\":2158,\"end\":2161,\"summary\":\"二少向苏雨晴送高级午饭，经理也主动提出雨天送她回家，她仍疑惑、戒备。叙述明确父母早知其工作生活，并请苏书记照顾；二少已知她是省委书记疼爱的侄女，讨好出于惧怕影响父亲仕途。苏雨中似见林跟着别人，回家发现新古筝；林称是客户赠礼，掩下紧张。\",\"turn\":\"家人暗中保护得到明确确认，苏仍误以为可能被父母抛弃；林的隐瞒越来越贴近生活。\",\"time\":\"2005年秋季雨天\",\"people\":[\"苏雨晴\",\"林夕晨\",\"二少\",\"加油站经理\",\"苏雨晴父母\",\"苏雨晴的大舅\",\"王市长\"],\"objects\":[\"高级盒饭\",\"电动车\",\"古筝\"],\"places\":[\"加油站\",\"雨中街道\",\"海景出租屋\"]},{\"key\":\"c549\",\"id\":549,\"title\":\"五倍酬劳\",\"kind\":\"main\",\"volume\":4,\"start\":2162,\"end\":2165,\"summary\":\"码头接到要求一天完成数日货量、给五倍报酬的大单，安念从清晨搬到晚九点，累得近乎虚脱；工头怀疑该船走私并运送偷渡客，但未获证实。船长额外加钱，每人实领五百。方因他不接电话担心，回家后两人相依，商量奶茶学艺将成、再等一两个月寻店，并约次日共同休息。\",\"turn\":\"挣钱与身体代价同时显现，开店计划趋于具体；船的非法活动仍仅属猜测。\",\"time\":\"码头工作一段时间后\",\"people\":[\"安念\",\"方莜莜\",\"码头工头\",\"大单船长\",\"码头工人\",\"疑似偷渡客\"],\"objects\":[\"货箱\",\"集装箱\",\"五百元报酬\",\"手机未接来电\"],\"places\":[\"宁波码头\",\"货船\",\"宁波出租单间\"]},{\"key\":\"c550\",\"id\":550,\"title\":\"安念暴走\",\"kind\":\"main\",\"volume\":4,\"start\":2166,\"end\":2169,\"summary\":\"难得共同休假，安念和女装的方莜莜乘拥挤公交去大卖场。陌生男子持续性骚扰方，反在她反击后公开羞辱其性别身份，乘客也转而歧视受害者。安念由克制转为暴怒，打伤对方并拖下车，直到方担心出人命才停手。两人离开，公交司机和围观者始终未有效制止侵害。\",\"turn\":\"安以暴力保护伴侣，方得以脱身但担心后果；后续追责本章未交代。\",\"time\":\"c549后的休假日早晨\",\"people\":[\"安念\",\"方莜莜\",\"公交骚扰男子\",\"公交司机\",\"围观乘客\"],\"objects\":[\"眼镜\",\"破损衣服\"],\"places\":[\"宁波公交车\",\"路边\"]},{\"key\":\"c551\",\"id\":551,\"title\":\"颈环\",\"kind\":\"main\",\"volume\":4,\"start\":2170,\"end\":2173,\"summary\":\"事后安念恢复平静，向方莜莜表示不会认同他人的羞辱，她既受安慰又惊讶于他首次打架的激烈。为减轻外貌被指认的压力，安买黑纱蝴蝶结铃铛颈环，再搭配猫耳发箍与发卡；方回赠连衣裙，以未来能穿下它鼓励安减重。创伤后的陪伴很快转回嬉笑购物，但社会排斥并未消失。\",\"turn\":\"衣饰兼具保护与亲密信物作用；安的女装愿望成为两人的共同玩笑和目标。\",\"time\":\"公交事件后同日\",\"people\":[\"安念\",\"方莜莜\",\"用品店老板\"],\"objects\":[\"黑纱铃铛颈环\",\"猫耳发箍\",\"猫耳发卡\",\"连衣裙\"],\"places\":[\"宁波街道\",\"用品店\",\"饰品服装店\"]},{\"key\":\"c552\",\"id\":552,\"title\":\"爱你永不变\",\"kind\":\"main\",\"volume\":4,\"start\":2174,\"end\":2177,\"summary\":\"三组伴侣围绕“永远”呈现不同状态：孙昊熟练向张思凡承诺永不变，她连别人留下的痕迹也误认作自己；海景房中林夕晨弹筝、画下苏雨晴，听她畅想未来领养女儿，只谨慎回答会在一起很久；影院里的安念则说爱会加深，可能逐渐成为亲情。并置使言辞、行动与未来的不确定性彼此映照。\",\"turn\":\"相同的永伴愿望背后，分别存在欺骗、隐忧和共同生活理想。\",\"time\":\"2005年秋\",\"people\":[\"孙昊\",\"张思凡\",\"林夕晨\",\"苏雨晴\",\"安念\",\"方莜莜\",\"曲奇\"],\"objects\":[\"古筝\",\"苏雨晴素描\",\"电影\"],\"places\":[\"张思凡出租屋\",\"海景出租屋\",\"电影院\"]},{\"key\":\"c553\",\"id\":553,\"title\":\"重阳节\",\"kind\":\"main\",\"volume\":4,\"start\":2178,\"end\":2181,\"summary\":\"书内十月十一日重阳节，苏雨晴趁国庆后调休与林夕晨登一座荒凉无名山。途中蛇袭击苏，曲奇扑救，又保护在草丛探路的咖啡。山顶石头布满青苔，泥土与腐木渗出红液，令苏联想到血与万人坑，两人决定离开；叙述另提出矿物染色的可能，未证实鬼神或埋尸之说。\",\"turn\":\"宠物护主再次突出；红土荒山留下疑问，原因只给可能解释。\",\"time\":\"书内2005年10月11日重阳节\",\"people\":[\"苏雨晴\",\"林夕晨\",\"曲奇\",\"咖啡\"],\"objects\":[\"青苔石阶\",\"蛇\",\"红色土壤与腐木\"],\"places\":[\"小城市无名石山\",\"百流山（比较提及）\"]},{\"key\":\"c554\",\"id\":554,\"title\":\"猛烈的台风\",\"kind\":\"main\",\"volume\":4,\"start\":2182,\"end\":2185,\"summary\":\"台风袭击海景房，两人相拥避风，苏讲科幻小说中记忆上传和模拟世界的故事。梦里她重返破旧公园，穿裙子的小男孩展示“上帝的盒子”，从太阳系缩放至她与林睡着的房间。苏顺手拔起屋外模型树；次晨现实中的树竟处于相同位置，她震惊后以台风巧合自解，开始怀疑人生是否被无形力量推动。\",\"turn\":\"梦与现实出现可对应的物理痕迹，仍未确认盒子与世界的本体关系。\",\"time\":\"重阳节后的一场台风，当夜至次晨\",\"people\":[\"苏雨晴\",\"林夕晨\",\"梦中小男孩\"],\"objects\":[\"上帝的盒子\",\"录音机钟声\",\"景观树\",\"科幻小说\"],\"places\":[\"海景出租屋\",\"梦中破旧公园\",\"盒中模拟世界\"]},{\"key\":\"c555\",\"id\":555,\"title\":\"去势手术（上）\",\"kind\":\"main\",\"volume\":4,\"start\":2186,\"end\":2189,\"summary\":\"十月底工资到账，苏雨晴攒够一万一千元，提出辞职便获迅速批准，经理另付补贴，她仍不知家族影响。回家见林异常疲倦，却尊重其沉默不再追问。次晨苏说明准备去孔雀处接受身体手术，按预计八千费用、三千生活预留安排积蓄；林答应照料，却因自己手术迟迟无法实现而走神。\",\"turn\":\"离家后首个重要身体目标资金到位；停止收入与林的隐性压力成为后续条件。\",\"time\":\"2005年10月底\",\"people\":[\"苏雨晴\",\"林夕晨\",\"加油站经理\",\"孔雀（拟联系）\"],\"objects\":[\"一万一千元积蓄\",\"辞职补贴\",\"电饭煲\",\"房租与生活预算\"],\"places\":[\"加油站\",\"海景出租屋\"]},{\"key\":\"c556\",\"id\":556,\"title\":\"去势手术（中）\",\"kind\":\"main\",\"volume\":4,\"start\":2190,\"end\":2193,\"summary\":\"手术前一天苏雨晴与林夕晨去游乐园尽情游玩，翌日到孔雀私人诊所。面对不可逆变化、与家庭关系及未来道路，她虽恐惧，仍确认自身决定；孔雀讲另一位患者后悔的经历再询问，随后实施手术。苏术后从昏沉中醒来感到疼痛。诊所过程含不当言行与医学叙述，不能将其当成规范医疗示范。\",\"turn\":\"苏自愿完成去势手术，进入康复阶段；她的认同和选择并未因此后悔。\",\"time\":\"c555后预约手术日\",\"people\":[\"苏雨晴\",\"林夕晨\",\"孔雀\",\"孔雀所述后悔患者\"],\"objects\":[\"手术器材\",\"纱布\"],\"places\":[\"游乐园\",\"孔雀私人诊所\"]},{\"key\":\"c557\",\"id\":557,\"title\":\"去势手术（下）\",\"kind\":\"main\",\"volume\":4,\"start\":2194,\"end\":2197,\"summary\":\"苏雨晴术后疼痛但明显感到卸下负担，在诊所多休息两天后由林陪同回家。富商开奔驰来接，林向苏称他是客户，又用阑尾手术说法遮掩；苏接受帮助仍感到疑惑。回家后林照顾饮食和日常。富商私下以高额报酬诱使林带苏参与其圈子的性交易，林再次明确拒绝，保护与隐瞒同时加深。\",\"turn\":\"手术完成并获得照护，苏首次直接接触富商而不知真相；林拒绝出卖伴侣。\",\"time\":\"手术后数日及居家康复期\",\"people\":[\"苏雨晴\",\"林夕晨\",\"孔雀\",\"富商\"],\"objects\":[\"奔驰车\",\"纱布\",\"鸡汤\"],\"places\":[\"孔雀私人诊所\",\"海景出租屋\",\"富商汽车\"]},{\"key\":\"c558\",\"id\":558,\"title\":\"各自的家人\",\"kind\":\"main\",\"volume\":4,\"start\":2198,\"end\":2202,\"summary\":\"叙事转向各家父母：林父病重仍饮酒、拒医并想亲自收麦，责骂女儿、不愿接受女婿帮助，又盼儿子过年返乡；林母反驳他的重男轻女。张父母以大学毕业的孩子为荣，准备年终交创业款。另一组父亲和继母讨论生女儿及叫旧子回家。苏父母已知女儿近况，父亲愿支持她坚持的性别选择，却仍决定等三年期限届满再接回。\",\"turn\":\"苏的家庭已发生她未知的态度变化；林父的病、偏见和返乡要求持续施压。\",\"time\":\"2005年秋收后、讨论年关与2006年\",\"people\":[\"林夕晨父母\",\"林夕晨大姐及姐夫\",\"张思凡父母\",\"未署名父亲与继母\",\"苏雨晴父母\",\"苏冬凌\",\"苏雨晴的大舅\"],\"objects\":[\"家书\",\"医药与汇款\",\"创业款\"],\"places\":[\"林夕晨故乡山村\",\"张思凡家乡村落\",\"苏雨晴父母家\"]},{\"key\":\"c559\",\"id\":559,\"title\":\"捉个正着\",\"kind\":\"main\",\"volume\":4,\"start\":2203,\"end\":2206,\"summary\":\"十一月，孙昊连续一周推说忙毕业不见面，张思凡借酒排遣，被搭讪时拒绝，翌日发热仍为约会细心打扮。孙让她到跃龙宾馆八〇六，她却误上六楼，听见六〇六中孙与另一女子谈论昨夜亲密。爱与愤怒使她无法离开；房门打开，孙当场见到她，长期疑点终于成为无法回避的事实。\",\"turn\":\"张亲自撞破背叛，约会转成对质；是否分手尚待下一章。\",\"time\":\"2005年11月\",\"people\":[\"张思凡\",\"孙昊\",\"宾馆房中女子\",\"酒吧搭讪男子\"],\"objects\":[\"酒瓶\",\"手机\",\"宾馆房号\"],\"places\":[\"酒吧\",\"张思凡出租屋\",\"跃龙宾馆606与806\"]},{\"key\":\"c560\",\"id\":560,\"title\":\"玩玩而已\",\"kind\":\"main\",\"volume\":4,\"start\":2207,\"end\":2210,\"summary\":\"被撞破后，孙昊冷淡承认交往只是为猎奇，称已厌倦，拒绝张思凡提出的修复机会，还以钱和性别羞辱践踏其感情。张扇他耳光后离开，回家陷入悲痛、发热与自毁念头，随后重新审视身份与未来。苏雨晴来电问候时，张只在长久沉默后说“不做女人了”，没有解释背叛经过。\",\"turn\":\"恋爱正式结束；张在创伤下选择改变人生方向，苏仅知其决定。\",\"time\":\"c559对质当日及次日\",\"people\":[\"张思凡\",\"孙昊\",\"宾馆女子\",\"苏雨晴\"],\"objects\":[\"所谓分手费\",\"手机\"],\"places\":[\"跃龙宾馆606\",\"张思凡出租屋\"]},{\"key\":\"c561\",\"id\":561,\"title\":\"不做女人了\",\"kind\":\"main\",\"volume\":4,\"start\":2211,\"end\":2214,\"summary\":\"张思凡迅速处置女性化用品，剪成平头，将衣物、化妆品和药物埋在曾与孙约会的校园迷宫，当晚乘火车回南方家乡。他回想早先扮演理想女友、后来为孙投入女性身份的心路，认定现在更愿以男性生活。父母热情接纳，并告知已筹十几万元供年后创业。此为张个人自我理解，不能推广为其他人的性别经验。\",\"turn\":\"张以男性身份回归家庭并准备创业，退出原来的转变道路；孙线在本段结束。\",\"time\":\"2005年11月，分手后随即返乡\",\"people\":[\"张思凡\",\"理发师\",\"张思凡父母\",\"孙昊（回想）\"],\"objects\":[\"夹克与牛仔裤\",\"剪落长发\",\"埋藏衣妆药品\",\"火车票\",\"父母创业款\"],\"places\":[\"理发店\",\"校园废弃迷宫\",\"返乡火车\",\"张思凡家乡\"]},{\"key\":\"c562\",\"id\":562,\"title\":\"方莜莜和安念的奶茶店\",\"kind\":\"main\",\"volume\":4,\"start\":2215,\"end\":2218,\"summary\":\"安念通过半个多月联络超市管理者，与方莜莜租下废弃保安亭，办手续并刷成粉蓝色，改成小奶茶店。两人合并积蓄购设备，除奶茶还卖烤肠、炸鸡等小食。开业低调，客人不多，安坚持自己学习操作却屡次炸焦食物，方笑着帮助、阻止他硬吃。首日收入有限，两人仍相信生意会逐渐好转。\",\"turn\":\"奶茶店从愿望变为共同事业，初期盈利不足但合作关系稳定。\",\"time\":\"两人合并工作积蓄后；原文“半年”与8月起点不严密\",\"people\":[\"安念\",\"方莜莜\",\"超市管理者\",\"首日顾客\"],\"objects\":[\"废保安亭\",\"营业手续\",\"粉蓝油漆\",\"封杯机\",\"电炸锅\",\"记账本\"],\"places\":[\"宁波超市门口奶茶店\"]},{\"key\":\"c563\",\"id\":563,\"title\":\"古筝伴奏\",\"kind\":\"main\",\"volume\":4,\"start\":2219,\"end\":2221,\"summary\":\"十一月已过大半，苏雨晴术后获准适量活动，每日与林夕晨去海边晒太阳。林带古筝反复调试、谱成一支兼有忧伤与快乐的新曲，苏跟着轻哼，吸引路人倾听；林将它命名《鹰》，未解释缘由。苏打算年前找临时工作补充积蓄，考虑促销又担心口才，林表示有钱并以亲吻回应相伴。\",\"turn\":\"《鹰》成为两人共享的音乐记忆；苏希望恢复收入，林隐忧仍未说出。\",\"time\":\"2005年11月下旬\",\"people\":[\"苏雨晴\",\"林夕晨\",\"海边听众\"],\"objects\":[\"古筝\",\"原创曲《鹰》\",\"游戏机\",\"画板\"],\"places\":[\"海边沙滩\"]},{\"key\":\"c564\",\"id\":564,\"title\":\"电瓶车相撞\",\"kind\":\"main\",\"volume\":4,\"start\":2222,\"end\":2225,\"summary\":\"奶茶店经营近一个月后客流渐旺，两人也遇到找错钱、收假钞的烦恼。方莜莜突然腹痛头晕，安念代做全部工作，让她先回家。她坚持省钱骑电动车，却在路口因卡车遮挡与另一电动车相撞，人未明显受伤，对方索赔不让走。接到电话的安立即关店奔赴现场，将伴侣安危放在营业之前。\",\"turn\":\"方身体不适与交通纠纷叠加，安暂停生意前去支持。\",\"time\":\"奶茶店经营近一个月后\",\"people\":[\"安念\",\"方莜莜\",\"相撞电动车中年车主\",\"顾客\"],\"objects\":[\"假钞\",\"电动车钥匙\",\"货运三轮车（进货）\",\"手机\"],\"places\":[\"奶茶店\",\"宁波第二个十字路口\"]},{\"key\":\"c565\",\"id\":565,\"title\":\"气势压倒\",\"kind\":\"main\",\"volume\":4,\"start\":2226,\"end\":2229,\"summary\":\"交警录像确认碰撞双方都有责任，但中年车主仍向病中的方莜莜索要五千元。安先礼貌核实、劝和，对方持续辱骂并准备动手后，他以激烈言语和殴打逼退对方，带方回家。没有继续营业，他给方煮姜粥、加肉松并陪伴休息。方感到受保护，后续索赔或法律结果本段未出现。\",\"turn\":\"两人脱离现场并休息，安保护心与易升级冲突的处事方式同时显现。\",\"time\":\"c564当日下午\",\"people\":[\"安念\",\"方莜莜\",\"电动车中年车主\",\"交警\"],\"objects\":[\"监控录像\",\"电动车\",\"姜粥与肉松\"],\"places\":[\"十字路口\",\"宁波出租单间\"]},{\"key\":\"c566\",\"id\":566,\"title\":\"遍体凌伤\",\"kind\":\"main\",\"volume\":4,\"start\":2230,\"end\":2233,\"summary\":\"村长代写的家书说林父肿瘤恶变，需次年二月前手术，费用至少十万，林仅有两三万积蓄。秃顶富商要求她带苏换钱，也提出高息借款；林动摇一夜，见苏信任的笑容后放弃。她转而接受介绍，赴另一名施虐富商处承受高价侵害，计划三次凑足钱。第二次遭多人严重虐待后，她带晚餐回家，隐瞒伤势倒头睡去。\",\"turn\":\"林守住不牺牲苏的底线，却将自身置于更严重侵害中，救父与自我保存陷入困局。\",\"time\":\"2005年末，父亲手术期限为2006年2月前\",\"people\":[\"林夕晨\",\"苏雨晴\",\"林夕晨父母\",\"村长\",\"秃顶富商\",\"臃肿施虐富商\",\"施虐富商同伴\"],\"objects\":[\"家书\",\"十万元手术款\",\"带回的晚餐\"],\"places\":[\"海景出租屋\",\"施虐富商住处\"]},{\"key\":\"c567\",\"id\":567,\"title\":\"忧心忡忡\",\"kind\":\"main\",\"volume\":4,\"start\":2234,\"end\":2237,\"summary\":\"第二个小城市圣诞节到来，苏雨晴发现林夕晨蜷缩发冷、噩梦惊醒，袖口露出明显淤痕；林以摔跤解释，苏不信却暂不追问。两人带着不适去商场，林行走、手臂碰触都疼痛发颤，苏术后也不能久走。最终在路边买圣诞衣帽，气氛比昔日合租清冷，苏愈发珍惜身边最后的陪伴。\",\"turn\":\"林的受伤无法完全遮掩，苏担忧加深，却尚未知施虐与救父筹款真相。\",\"time\":\"2005年12月25日\",\"people\":[\"苏雨晴\",\"林夕晨\"],\"objects\":[\"圣诞树\",\"空调\",\"圣诞衣帽\",\"外带早餐\"],\"places\":[\"海景出租屋\",\"商场\",\"路边摊\"]},{\"key\":\"c568\",\"id\":568,\"title\":\"偷看林夕晨洗澡\",\"kind\":\"main\",\"volume\":4,\"start\":2238,\"end\":2241,\"summary\":\"圣诞夜，林夕晨反常拒绝共浴。苏雨晴因担心而偷看，发现她全身多处淤伤和伤口、清洗时痛苦难支；随后明确询问，希望共同承担困难。林先说摔跤，被指出背上也有伤后改称美容按摩，苏联想到母亲经历，终于半信半疑接受。窥见伤势并没有带来坦诚，反而形成新的善意却错误的解释。\",\"turn\":\"苏已见严重伤势却被按摩说辞安抚，林继续独自承受；“美容疗效”不能当医学结论。\",\"time\":\"2005年12月25日晚\",\"people\":[\"苏雨晴\",\"林夕晨\",\"苏雨晴母亲（回忆）\"],\"objects\":[\"电视功能手机\",\"热水器\",\"浴室拉门\"],\"places\":[\"海景出租屋浴室\"]},{\"key\":\"c569\",\"id\":569,\"title\":\"促销员的工作（上）\",\"kind\":\"main\",\"volume\":4,\"start\":2242,\"end\":2245,\"summary\":\"元旦后，苏雨晴为年关开销寻临时工作，在大润发门前应聘咖啡促销。招聘者简单面谈后录用，她以寒假高中生身份签约，工作至除夕，底薪八百加销量提成。重返超市，她遇到寒假兼职的周超、仍在工作的夏仕尼及主管张燕，熟人唤起旧日记忆；真正站上地堆时，她又为主动叫卖胆怯。\",\"turn\":\"苏获得独立临时收入机会，再次面对羞怯与离校身份隐瞒。\",\"time\":\"2006年元旦后、春节前\",\"people\":[\"苏雨晴\",\"促销招聘负责人\",\"周超\",\"夏仕尼\",\"张燕\",\"王海峰（回想）\",\"翁锡芽（提及）\",\"陈淑艳（提及）\"],\"objects\":[\"临时促销合同\",\"雀巢咖啡地堆\",\"招聘广告\"],\"places\":[\"大润发超市\",\"酒柜\"]},{\"key\":\"c570\",\"id\":570,\"title\":\"促销员的日常（下）\",\"kind\":\"main\",\"volume\":4,\"start\":2246,\"end\":2249,\"summary\":\"促销地堆设在冷柜旁的僻处，苏雨晴最初只敢等人试饮，销量很低。海边别墅的美丽少女来买酸奶，她鼓勇推介咖啡，对方温和购买大盒，使她有信心向更多人开口。晚间周超请她吃烧烤，闲谈大学生活；苏羡慕求学机会，又用复读的谎言遮掩实际离校经历，友情使她轻松，也触动失学遗憾。\",\"turn\":\"第一次成功推销带来勇气；别墅少女支持与大学话题分别推动社交成长和内心遗憾。\",\"time\":\"c569入职当日\",\"people\":[\"苏雨晴\",\"雯雯\",\"张燕\",\"周超\",\"烧烤摊主\"],\"objects\":[\"咖啡试饮纸杯\",\"咖啡壶\",\"赠品方糖\",\"烧烤\"],\"places\":[\"大润发冷柜旁地堆\",\"旧合租房方向烧烤摊\"]},{\"key\":\"c571\",\"id\":571,\"title\":\"夕子姐姐，为什么要这么做？！\",\"kind\":\"main\",\"volume\":4,\"start\":2250,\"end\":2252,\"summary\":\"年前下班回家，苏雨晴亲眼看见林夕晨被臃肿富商带上车，对方公开提及金钱性交易并诱邀苏。苏震惊追问，林只劝她回去、请求不要伤害她。富商趁苏混乱将她推入车内，许诺只让她旁观并加钱；林因救父筹款无法离去，苏则执意留下，希望阻止伴侣继续。车辆抵达湖边别墅，隐瞒终于被撕开。\",\"turn\":\"苏被卷入危险并确认林受供养交易，却还不知道筹款救父的全部原因。\",\"time\":\"2006年春节前、促销工作期间夜晚\",\"people\":[\"苏雨晴\",\"林夕晨\",\"臃肿施虐富商\"],\"objects\":[\"黑色轿车\",\"高额报酬承诺\"],\"places\":[\"小区后门\",\"夜间公路\",\"湖边别墅\"]},{\"key\":\"c572\",\"id\":572,\"title\":\"我来代替\",\"kind\":\"main\",\"volume\":4,\"start\":2253,\"end\":2256,\"summary\":\"湖边别墅内，壮汉将苏雨晴束缚，迫她旁观林夕晨遭严重虐待。为阻止伤害，苏要求代替林，施虐者借“自愿”之名也侵害她，两人先后昏迷。秃顶富商带保镖与相机闯入，指责老李违背约定，对方反揭其意在竞争利益；对峙中武警冲入包围众人。苏的选择处于胁迫情境，不能当成自由同意。\",\"turn\":\"苏以保护林为由被迫卷入侵害；武警及时介入，救援来源待下一章揭明。\",\"time\":\"c571当夜\",\"people\":[\"苏雨晴\",\"林夕晨\",\"老李\",\"秃顶富商\",\"保镖\",\"施虐壮汉\",\"武警\"],\"objects\":[\"束缚椅\",\"相机\"],\"places\":[\"湖边别墅地下室\"]},{\"key\":\"c573\",\"id\":573,\"title\":\"苏雨晴大舅的震怒\",\"kind\":\"main\",\"volume\":4,\"start\":2257,\"end\":2260,\"summary\":\"武警抓走现场人员，将苏雨晴、林夕晨送医；救援来自大舅获报信，同行邋遢男子被称莫家家主，拒绝等苏醒来便离去。秃顶富商原本并非为警方取证，主要想谋商业利益。医院救治后两人无生命危险，大舅要求王副局长严办李任飞并通知苏父母，父母对接回女儿再起分歧。苏在昏沉梦中与林相伴，醒来庆幸彼此尚在。\",\"turn\":\"两人获救存活，家族保护从暗处走向苏的视野；李任飞被拘，具体刑期未交代。\",\"time\":\"别墅事件当夜至翌日\",\"people\":[\"苏雨晴\",\"林夕晨\",\"苏书记（大舅）\",\"莫家家主\",\"李任飞\",\"秃顶富商\",\"王副局长\",\"苏雨晴父母\",\"医生与护士\"],\"objects\":[\"急救车\",\"高级病房\",\"电话\"],\"places\":[\"湖边别墅\",\"医院\",\"急救车\"]},{\"key\":\"c574\",\"id\":574,\"title\":\"我……还不想回去\",\"kind\":\"main\",\"volume\":4,\"start\":2261,\"end\":2264,\"summary\":\"醒来后苏雨晴认出大舅，仍不愿返家；大舅谎称父母不知，尊重她表面的选择，给每月十万额度的卡及联系方式。叙述补出苏父母同姓、两支远房家族婚姻旧事。林终于坦白父亲癌症需钱，还差五万，苏毫不犹豫交卡帮她，并支持她带款回乡探望父母。受伤后的两人第一次共同面对救父压力，林却仍担心家人接受不了自己。\",\"turn\":\"资金困局获得帮助，林决定返乡；家人态度与苏期待之间仍有危险落差。\",\"time\":\"c573翌日上午\",\"people\":[\"苏雨晴\",\"林夕晨\",\"苏雨晴的大舅\",\"苏雨晴父母\",\"护士\"],\"objects\":[\"十万元月额度卡\",\"大舅联系电话\",\"早餐\"],\"places\":[\"医院高级病房\"]},{\"key\":\"c575\",\"id\":575,\"title\":\"暂时的分别\",\"kind\":\"main\",\"volume\":4,\"start\":2265,\"end\":2268,\"summary\":\"2006年1月20日，两人伤势恢复后，苏请假送林夕晨乘K1103返乡。林带着救父钱与年后回来的约定，漫长车程仍挡不住两人依依不舍。送别后苏不愿回空屋，走到公墓买纸花祭胡玉牛，为昔日疏远而愧疚，盼其不再受苦。章末说明公墓所立是衣冠冢，骨灰另葬村边。\",\"turn\":\"暂别实际上成为两人现实中的最后相见；此时双方仍真诚期待年后重聚。\",\"time\":\"2006年1月20日\",\"people\":[\"苏雨晴\",\"林夕晨\",\"胡玉牛（追思）\",\"胡玉牛父母（提及）\"],\"objects\":[\"K1103车票\",\"救父款\",\"纸花\",\"胡玉牛墓碑\",\"梅花\"],\"places\":[\"小城市火车站\",\"小城市公墓\"]},{\"key\":\"c576\",\"id\":576,\"title\":\"孔雀被抓\",\"kind\":\"main\",\"volume\":4,\"start\":2269,\"end\":2272,\"summary\":\"林离开后，苏雨晴独居思念，从手机新闻得知孔雀因无照手术及伤害案被捕。群聊称未成年小云术后后悔、父母起诉，并回忆孔雀资助小琳、免费帮助叶子；关于动机的说法来自群成员。其他私下手术者暂时停业。苏再联系张思凡，他明确已停止女性化并谈身体恢复，态度较从前疏淡。\",\"turn\":\"孔雀被捕改变社群支持条件，张的生活方向已经改变；苏身边旧联系进一步疏远。\",\"time\":\"2006年1月20日后、春节前\",\"people\":[\"苏雨晴\",\"孔雀\",\"小云及父母\",\"小琳\",\"叶子\",\"QQ群成员\",\"张思凡\"],\"objects\":[\"电视手机\",\"旧笔记本电脑\",\"无线网卡\",\"好想做个女孩子QQ群\"],\"places\":[\"海景出租屋\",\"网络群聊\",\"孔雀诊所（新闻）\"]},{\"key\":\"c577\",\"id\":577,\"title\":\"林夕晨的长途旅行\",\"kind\":\"main\",\"volume\":4,\"start\":2273,\"end\":2276,\"summary\":\"林夕晨在长途坐席列车上抱着苏准备的零食和礼物，短信因山区信号稀薄难以往返。近乡之际，她回想父亲曾单独带她乘绿皮车、托关系读好高中和粗糙手掌的疼爱，又想到这种照顾建立在“唯一儿子”的期待上。最小姐姐为求学被打、被断食的旧事，使她对以女性面貌返家越发不安。\",\"turn\":\"父爱的条件性与姐妹遭遇形成危险预示，林仍怀期待继续返乡。\",\"time\":\"2006年1月20日起两天长途行程\",\"people\":[\"林夕晨\",\"苏雨晴\",\"林夕晨父亲\",\"林夕晨最小姐姐\",\"村长（回忆）\"],\"objects\":[\"长途坐票\",\"背包零食\",\"短信\",\"绿皮火车（回忆）\",\"返乡礼物\"],\"places\":[\"返乡列车\",\"林夕晨童年山村（回忆）\"]},{\"key\":\"c578\",\"id\":578,\"title\":\"新年之前\",\"kind\":\"main\",\"volume\":4,\"start\":2277,\"end\":2281,\"summary\":\"除夕前奶茶店最后营业日，安念与方莜莜清理存货、相伴过夜，次日分别乘车回杭州和武汉。安回家与父母嬉笑，母亲关心瘦身和饮食，父亲把他的电脑弄乱，熟悉琐事让家显得温暖。方返家途中遇多年未见表哥，被唤旧名宇悠；表哥热情提行李、忆童年游戏，她把男友说成女友，仍被亲情触动。\",\"turn\":\"两对返乡路径对照：安拥有自然亲密的家庭，方仍隐藏身份与恋情。\",\"time\":\"2006年除夕前一日至除夕\",\"people\":[\"安念\",\"方莜莜\",\"安念父母\",\"方莜莜表哥\"],\"objects\":[\"返乡车票\",\"奶茶店存货\",\"游戏电脑与重装光盘\",\"行李\"],\"places\":[\"宁波奶茶店\",\"宁波车站\",\"杭州安念家\",\"武汉返家路\"]},{\"key\":\"c579\",\"id\":579,\"title\":\"一个人的春节\",\"kind\":\"main\",\"volume\":4,\"start\":2282,\"end\":2285,\"summary\":\"苏雨晴首次独自过除夕，上午采购迟了，只买到零散蔬菜，再添肉、鱼和速冻食品。她给曲奇做鱼、陪咖啡吃饭，哼歌料理以缓解空虚，却不断想起父母、方莜莜传授厨艺、张思凡早年扶持及林的陪伴。烟花越热闹，屋内越显孤寂；她仍安慰自己林过几天就会回来。\",\"turn\":\"宠物成为仅有的现场陪伴，苏在未知死讯时继续等待与伴侣重聚。\",\"time\":\"2006年除夕\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"林夕晨（思念）\",\"方莜莜（回忆）\",\"张思凡（回忆）\",\"苏雨晴父母（思念）\"],\"objects\":[\"除夕食材\",\"鲫鱼\",\"速冻食品\",\"电磁炉\"],\"places\":[\"菜场\",\"海景出租屋阳台厨房\"]},{\"key\":\"c580\",\"id\":580,\"title\":\"相亲\",\"kind\":\"main\",\"volume\":4,\"start\":2286,\"end\":2289,\"summary\":\"返乡后的张思凡在父母安排下与邻村董花火相亲。董比他至少大三岁，外地工作、爽朗主动，见他发冷便换有暖炉的座位，也支持其互联网创业设想。张仍为既往药物经历和身体状况担忧，未坦白过去，只想敷衍试见；董却直接表达好感，提出交往培养感情，挽他下楼，两人的新关系开始。\",\"turn\":\"张获得新恋爱机会，但身体与旧情经历仍未说明，关系只是开始试交往。\",\"time\":\"2006年春节返乡期间\",\"people\":[\"张思凡\",\"董花火\",\"张思凡父母\",\"董花火母亲\"],\"objects\":[\"菊花茶\",\"暖炉\",\"糕点\"],\"places\":[\"张思凡家楼顶\"]},{\"key\":\"c581\",\"id\":581,\"title\":\"不接受\",\"kind\":\"main\",\"volume\":4,\"start\":2290,\"end\":2293,\"summary\":\"林夕晨抵达雪封山村，旧路唤起最小姐姐被剥夺求学、十七岁被安排出嫁的记忆。母亲见她女性装扮十分惊讶，要求赶在父亲醒来前换男装；林解释身体检查与女性认同，母亲仍不接受，称作男人才有地位。父亲下楼认出她后脸色剧变，返家带来的希望迅速被家庭旧观念压迫。\",\"turn\":\"生理说明与情感诉求均未得到母亲理解，父亲的暴力冲突即将爆发。\",\"time\":\"林返乡到达当日清晨，春节前\",\"people\":[\"林夕晨\",\"林夕晨父母\",\"最小姐姐\",\"摩托车司机\"],\"objects\":[\"返乡行李\",\"童年石凳\",\"女装\"],\"places\":[\"林夕晨故乡山村\",\"林家两层土屋\"]},{\"key\":\"c582\",\"id\":582,\"title\":\"死吧死吧死吧！\",\"kind\":\"main\",\"volume\":4,\"start\":2294,\"end\":2297,\"summary\":\"林坚持自己的女性身份，父亲殴打她并锁入柴房，逼她改口；母亲试图阻止却被推开，随后整日无人送食水。林在旧伤、饥寒、绝望中精神崩溃，留下扭曲画痕，夜间逃出后杀害父母，再自杀。临终恢复片刻清醒，后悔无法挽回，并向苏告别。正文明确林与双亲死亡，这一结局不能理解为解脱或团聚的实现。\",\"turn\":\"筹款救父返乡以家庭暴力、杀亲和自杀告终；林与苏的重聚愿望彻底破灭。\",\"time\":\"返乡当日持续至深夜，春节前\",\"people\":[\"林夕晨\",\"林夕晨父母\",\"苏雨晴（临终想及）\"],\"objects\":[\"救父纸钞\",\"柴房墙上抽象画\",\"行李包\"],\"places\":[\"林家柴房\",\"林家住宅\"]},{\"key\":\"c583\",\"id\":583,\"title\":\"林夕晨的画\",\"kind\":\"main\",\"volume\":4,\"start\":2298,\"end\":2301,\"summary\":\"大年初一，苏雨晴仍收不到林的回复，翻看留家的画稿以解思念。她发现《家》雪村图，以及与温暖油画对应的扭曲抽象画，父亲骑车、城市、海滩人物在另一个版本中都显得可怖；她疑惑后仍归作涂鸦。孔雀案已有十年刑期并赔尽积蓄的结果，群内关注渐散。苏再发短信无回音，只好独自出门。\",\"turn\":\"读者已知林死亡而苏仍等待；画作成为复杂内心的残留证据，孔雀案获得刑罚结局。\",\"time\":\"2006年大年初一\",\"people\":[\"苏雨晴\",\"林夕晨（作品）\",\"孔雀\",\"小云父母\",\"孔雀律师\",\"QQ群成员\"],\"objects\":[\"《家》画作\",\"三幅油画与对应抽象画\",\"短信\",\"论坛群聊\"],\"places\":[\"海景出租屋\",\"空荡街道\"]},{\"key\":\"c584\",\"id\":584,\"title\":\"死讯\",\"kind\":\"main\",\"volume\":4,\"start\":2302,\"end\":2305,\"summary\":\"空城步行街上，苏雨晴接到显示“夕子姐姐”的电话，本以为等来重聚消息，警方却通知林杀害父母后自杀，死亡已超过三天。她无法接受，回忆初见、取暖、上一年初一相恋和海景房生活，在悲恸中昏倒。邋遢男子抱她离开长椅的场景由此展开，后两章将揭示为梦境叙事。\",\"turn\":\"警方正式将死讯带给苏；爱人死亡成为现实认知，梦中告别即将展开。\",\"time\":\"2006年大年初一白天\",\"people\":[\"苏雨晴\",\"来电警员\",\"林夕晨（回忆）\",\"莫空（后证梦境）\",\"胡玉牛（回忆）\"],\"objects\":[\"来电手机\",\"罐装咖啡\",\"街边长椅\"],\"places\":[\"步行街\",\"梦中河堤\"]},{\"key\":\"c585\",\"id\":585,\"title\":\"去面对（上）\",\"kind\":\"main\",\"volume\":4,\"start\":2306,\"end\":2309,\"summary\":\"梦境延续：莫空守在河堤，等苏雨晴醒后递八宝粥，听她表达想再见爱人的悲痛。苏质疑陌生人擅自带走自己，也担忧无证件不能远行；他未承诺复活，只问是否想见最后一面，她哭着肯定后被邀出发。c586末揭示全段为长椅梦中告别，苏未实际赴山村，林未复活。\",\"turn\":\"c586末揭为长椅梦中告别：苏未实际赴山村，林未复活；莫空提供梦中引导。\",\"time\":\"大年初一昏睡梦境\",\"people\":[\"苏雨晴\",\"莫空\",\"林夕晨（想及）\"],\"objects\":[\"八宝粥\",\"香烟\"],\"places\":[\"梦中河堤\"]},{\"key\":\"c586\",\"id\":586,\"title\":\"去面对（下）\",\"kind\":\"main\",\"volume\":4,\"start\":2310,\"end\":2313,\"summary\":\"梦中莫空称大舅早备机票，带无证件的苏顺利乘专机般航班、出租车与摩托抵达林家。她抱住遗体哭泣，莫空以蓝光使林短暂回应；林诉说爱意，劝苏即使失去自己也继续经历生活。林化作星光、世界崩塌，苏醒来仍在原长椅，已是月夜。整个赴乡及“复活”是梦中告别，现实里没有成行或复生。\",\"turn\":\"c586末揭示长椅梦中告别，苏未实际赴山村、林未复活；莫空是否干预梦境仍是疑问。\",\"time\":\"大年初一白天至月夜的昏睡梦境\",\"people\":[\"苏雨晴\",\"梦中莫空\",\"梦中林夕晨\",\"梦中林夕晨父母遗体\"],\"objects\":[\"梦中机票\",\"蓝光\",\"星光\"],\"places\":[\"梦中机场与飞机\",\"梦中林家\",\"现实步行街长椅\"]},{\"key\":\"c587\",\"id\":587,\"title\":\"替她好好活下去\",\"kind\":\"main\",\"volume\":4,\"start\":2314,\"end\":2317,\"summary\":\"苏回家仍在梦与现实间挣扎，翌晨幻见林在床边，电话却已关机。论坛转载新闻的地点、细节与照片确认死者就是夕子，且与她梦中场景相同。她一度考虑追随爱人死亡，却因自身想活、尚有愿望，以及梦中林的劝慰而停下。保存林的记忆、代她体验余下人生，成为继续生活的支点。\",\"turn\":\"苏确认死讯后经历自杀危机但未实施，选择活下去并记住林。\",\"time\":\"大年初二\",\"people\":[\"苏雨晴\",\"林夕晨（梦中话语与幻影）\",\"曲奇\",\"咖啡\",\"论坛发帖者\"],\"objects\":[\"受撞手机\",\"论坛新闻与照片\"],\"places\":[\"海景出租屋\",\"阳台\"]},{\"key\":\"c588\",\"id\":588,\"title\":\"莫空和秋易\",\"kind\":\"main\",\"volume\":4,\"start\":2318,\"end\":2321,\"summary\":\"莫空在雪后天台堆雪人，遇高中生邻居秋易，以笔名莫成自我介绍。秋父母已去世，靠遗产并赚生活费独居，两人结伴扫墓。莫空到胡玉牛衣冠冢点庙中蜡烛，感叹自己警示未被听取，并谈一条未实现的幸福可能。柳韵带白花来，嘴上责骂、称最后一次探望，离开时却落泪，悲伤并未因报复消失。\",\"turn\":\"莫空与秋易建立邻里联系；胡的另一种未来仅为莫空所述可能，柳韵仍受失落牵动。\",\"time\":\"2006年春节后雪日\",\"people\":[\"莫空\",\"秋易\",\"果果姐（房东，提及）\",\"胡玉牛（追思）\",\"柳韵\",\"守墓老人\"],\"objects\":[\"雪人\",\"纽扣眼睛\",\"庙中蜡烛\",\"白色鲜花\"],\"places\":[\"天台阁楼\",\"小城市公墓\"]},{\"key\":\"c589\",\"id\":589,\"title\":\"大黑狗\",\"kind\":\"main\",\"volume\":4,\"start\":2322,\"end\":2325,\"summary\":\"扫墓归来，莫空向秋易编讲朋友故事，并未真实说明胡玉牛。小区楼下两人发现瘦弱受伤的大黑狗，莫空认出它是天语遥旧日喂养的狗，因主人出事、旧团伙散去而失去照料。秋坚持尽力帮助，触动原本淡漠的莫空，两人回屋找香肠、小鱼干等食物，再到楼下喂它，新的陪伴开始萌芽。\",\"turn\":\"秋的善意推动莫空实际援助，失主动物线与新人物线在此交会。\",\"time\":\"c588扫墓后\",\"people\":[\"莫空\",\"秋易\",\"黑皇\",\"天语遥（回想）\"],\"objects\":[\"泡沫盒\",\"香肠\",\"小鱼干\",\"饼干\"],\"places\":[\"公墓返程\",\"阁楼小区楼下\"]},{\"key\":\"c590\",\"id\":590,\"title\":\"黑皇\",\"kind\":\"main\",\"volume\":4,\"start\":2326,\"end\":2329,\"summary\":\"吃过食物的大黑狗跟上天台，秋易决定收养，以缓解彼此孤独；莫空为它取名黑皇，狗从流浪得到稳定住处。莫空回房删除刚写的万余字章节，凝望窗外许久，动机未明。夜深曲奇像老友一样来访，接受小鱼干，莫空向它问“她”近况，暗示他与宠物及苏的生活有未明联系。\",\"turn\":\"黑皇正式获收养；删稿和曲奇夜访加深莫空作为观察、干预者的谜团。\",\"time\":\"c589后当日至深夜\",\"people\":[\"秋易\",\"莫空\",\"黑皇\",\"曲奇\"],\"objects\":[\"狗的新名字\",\"Word文稿\",\"小鱼干\",\"旧时家族大狗（回忆）\"],\"places\":[\"天台阁楼\",\"莫空房间\"]},{\"key\":\"c591\",\"id\":591,\"title\":\"颓废\",\"kind\":\"main\",\"volume\":4,\"start\":2330,\"end\":2333,\"summary\":\"苏抱着林留下的等身毛绒熊长久失眠、少进食，连宠物也挨饿；曲奇带咖啡外出觅食，还给她带鱼回来。两只动物的亲昵唤起她的责任感，她想到父母、表哥和未完成愿望，决心继续活着。睡过一整天后她艰难下楼吃早餐，钱不够添食时莫空再次出现，替她点嵌糕豆浆并温和相陪。\",\"turn\":\"求生决定仍需落实到吃饭睡眠；宠物和现实中的莫空帮助苏恢复基本生活。\",\"time\":\"丧讯后数日\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"莫空\",\"早餐店老板\"],\"objects\":[\"林的毛绒熊\",\"宠物带回的鱼\",\"白粥豆浆\",\"嵌糕\"],\"places\":[\"海景出租屋\",\"楼下早餐店\"]},{\"key\":\"c592\",\"id\":592,\"title\":\"树苗\",\"kind\":\"main\",\"volume\":4,\"start\":2334,\"end\":2337,\"summary\":\"早餐后莫空点明苏曾想离开世界，又否认受她父母雇派，竟复述梦中林的告别话，使她怀疑他能进入梦境。他带苏看水泥缝中屡被踩踏仍存活的小树苗，安静听她从离家讲到身份困境与失去林的经历。苏把羞耻、自卑说出口，莫空鼓励坦诚面对内心，为她提供不带排斥的倾听。\",\"turn\":\"梦中信息与现实人物对应，超自然关联加强；苏找到讲述经历与重建信心的出口。\",\"time\":\"c591早餐后\",\"people\":[\"苏雨晴\",\"莫空\",\"林夕晨（梦中话语）\"],\"objects\":[\"水泥缝树苗\",\"早餐\"],\"places\":[\"早餐店\",\"旧河堤\"]},{\"key\":\"c593\",\"id\":593,\"title\":\"当知道真正的我的时候，你还会用司空见惯的笑脸和我说话吗？\",\"kind\":\"main\",\"volume\":4,\"start\":2338,\"end\":2341,\"summary\":\"河边长谈后莫空告诉苏，她的前方比想象中光明。两人即兴合唱，苏想到冉空城虽曾承诺不变、后来联系渐少，问出得知真实自己后是否仍会被温柔相待的疑虑。莫空坚定回应，鼓励她保持内心坦诚。她感谢后离开，重新感受春日生机；莫空独自回味歌词，态度温柔，关系意义仍未完全揭开。\",\"turn\":\"苏在被理解的对话中暂时恢复希望；冉的疏远与莫空的接纳形成对照。\",\"time\":\"c592同日中午前后\",\"people\":[\"苏雨晴\",\"莫空\",\"冉空城（回想）\"],\"objects\":[\"即兴歌曲\",\"石子水漂\",\"河边栏杆节拍\"],\"places\":[\"旧河堤\"]},{\"key\":\"c594\",\"id\":594,\"title\":\"恢复平静了的日子\",\"kind\":\"main\",\"volume\":4,\"start\":2342,\"end\":2345,\"summary\":\"苏重新做饭照顾宠物、清理屋子，把林的遗物珍重装进上锁行李箱，继续怀念但开始恢复日常。翌日出门仍习惯向林告别，随后意识到只剩自己。为充实生活她寻找安静且适合的工作，避开需证件的中介，看到宠物店招人便进去；面对十八岁以上要求，她再次谎称成年，实际只有虚岁十七。\",\"turn\":\"苏把纪念和生活区分开，主动寻找有兴趣的新工作。\",\"time\":\"2006年春节后初春\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"宠物店女店主\"],\"objects\":[\"林夕晨遗物行李箱\",\"宠物食物\",\"招聘广告\"],\"places\":[\"海景出租屋\",\"招工街道\",\"宠物店\"]},{\"key\":\"c595\",\"id\":595,\"title\":\"宠物店（上）\",\"kind\":\"main\",\"volume\":4,\"start\":2346,\"end\":2349,\"summary\":\"店主风音喜欢苏照料的曲奇、罕见紫色咖啡，热情录用她，首月两千、之后两千五，并包两餐及宠物口粮。签合同时风音突然询问性别，苏紧张后仍填女；风音道歉不再追问。苏第一天逗奶猫、观察喂食，得知风音原是白领、父母在国外，与妹妹同住。工作带来真实兴趣，也埋下身份被识出的不安。\",\"turn\":\"苏找到愿意接纳其宠物的雇主，兴趣与收入结合；风音已对其经历有所猜测。\",\"time\":\"入职首日\",\"people\":[\"苏雨晴\",\"风音\",\"曲奇\",\"咖啡\",\"风音妹妹（提及）\"],\"objects\":[\"劳动合同\",\"逗猫棒\",\"奶瓶\",\"宠物口粮\"],\"places\":[\"风音宠物店\"]},{\"key\":\"c596\",\"id\":596,\"title\":\"宠物店（下）\",\"kind\":\"main\",\"volume\":4,\"start\":2350,\"end\":2353,\"summary\":\"宠物店首日忙碌中，苏雨晴感到照顾动物的满足。傍晚风音妹妹风羽蓝从补习班来送饭，姐妹嬉笑，她与苏礼貌结识；随后男友辉来接她约会。风音虽开玩笑吃醋，仍大方放行。苏羡慕这份家人与恋人同在的温暖，也想起林，萌生留长发、扎双马尾的念头。\",\"turn\":\"苏接触新的温暖关系网，思念转为可延续的生活细节。\",\"time\":\"入职首日傍晚\",\"people\":[\"苏雨晴\",\"风音\",\"风羽蓝\",\"辉\",\"曲奇\",\"咖啡\"],\"objects\":[\"工作晚餐\",\"雪碧\",\"校服\"],\"places\":[\"风音宠物店\"]},{\"key\":\"c597\",\"id\":597,\"title\":\"遛狗的工作\",\"kind\":\"main\",\"volume\":4,\"start\":2354,\"end\":2357,\"summary\":\"入职第三天，苏学习剪爪、打理宠物，曲奇抗拒剪爪便作罢；风音负责为顾客的贵宾犬豆豆洗澡。郑太太来电请人遛萨摩耶大白，风音把原由小蓝做的任务交给苏，画路线、让她自留五十元酬劳。苏到清河小区别墅接狗，看到郑太太将大白视为家人，对方温顺回应，新任务开始。\",\"turn\":\"苏得到独立遛狗责任及额外收入，宠物与家人的主题延伸到新顾客。\",\"time\":\"宠物店入职第三天，上午9:30起\",\"people\":[\"苏雨晴\",\"风音\",\"郑太太\",\"郑太太儿子\",\"豆豆主人\",\"大白\",\"豆豆\",\"曲奇\",\"咖啡\"],\"objects\":[\"手绘路线图\",\"牵引绳\",\"宠物剪甲器\"],\"places\":[\"宠物店\",\"清河小区10栋1001\"]},{\"key\":\"c598\",\"id\":598,\"title\":\"解开束缚后的奔跑\",\"kind\":\"main\",\"volume\":4,\"start\":2358,\"end\":2361,\"summary\":\"曲奇、咖啡与大白相处友好，苏误以为大白会听话，解开牵引后它立刻奔跑，她担心丢狗赔钱拼命追赶，累得心肺不适。三只动物见她倒在草地便回头关心，大白随后放慢脚步领路，最终到河边找到熟悉的风羽蓝。一次过度追逐暴露苏的体弱，也让自由与照护责任发生具体冲突。\",\"turn\":\"大白没有失踪，苏恢复后继续同行；解绳导致的失控不可当养宠操作建议。\",\"time\":\"c597遛狗过程中\",\"people\":[\"苏雨晴\",\"大白\",\"曲奇\",\"咖啡\",\"风羽蓝\"],\"objects\":[\"项圈与牵引绳\"],\"places\":[\"清河小区草地\",\"小区旁河边\"]},{\"key\":\"c599\",\"id\":599,\"title\":\"逃课的少男少女\",\"kind\":\"main\",\"volume\":4,\"start\":2362,\"end\":2365,\"summary\":\"河边风羽蓝其实逃补习课与金家辉约会，苏识趣带大白走远，却因眼前情侣重新思念林并强烈想回学校。她翻看旧手机仅存的五十张照片，林弹筝、旧合租伙伴与房内景物唤回两年得失。到点她重新系好狗绳送回大白，郑太太满意，付一百元含额外小费，遛狗任务顺利完成。\",\"turn\":\"新工作带来肯定，校园与亲密关系的遗憾继续存在，旧照片成为重要记忆载体。\",\"time\":\"c597同日中午12:30前后\",\"people\":[\"苏雨晴\",\"风羽蓝\",\"金家辉\",\"郑太太\",\"大白\",\"曲奇\",\"咖啡\",\"旧合租伙伴（照片）\"],\"objects\":[\"五十张手机照片\",\"旧手机\",\"一百元报酬\"],\"places\":[\"清河小区河边\",\"郑太太家门口\"]},{\"key\":\"c600\",\"id\":600,\"title\":\"你果然是男孩子\",\"kind\":\"main\",\"volume\":4,\"start\":2366,\"end\":2369,\"summary\":\"晚间风音与苏共餐，询问离家和求学经历，苏含糊应对。风音随后越界触碰其私密部位，使她恐惧身份暴露；得知苏想做女孩并使用药物后，风音表示接受，承认举动突然并鼓励她。她还说明妹妹风羽蓝具有双性发育特征，已做手术，男友知情。苏既羡慕又感激被接纳，但接纳不能抵消身体边界被侵犯。\",\"turn\":\"苏向新雇主坦白身份后继续获支持；小蓝身份与既有陶人祝福线形成重要可核对联系。\",\"time\":\"遛狗当日夜晚、2006年初春\",\"people\":[\"苏雨晴\",\"风音\",\"风羽蓝（提及）\",\"金家辉（提及）\"],\"objects\":[\"晚餐\",\"服装杂志\",\"花花公子杂志\"],\"places\":[\"风音宠物店\"]},{\"key\":\"c601\",\"id\":601,\"title\":\"夏日炎炎\",\"kind\":\"main\",\"volume\":5,\"start\":2371,\"end\":2374,\"summary\":\"2006年初夏，雨晴在宠物店逐渐恢复平静，风音给予理解和帮助。她带大白在河边树下避暑，读高中语文书，重新怀念求学生活；曲奇陪着已经衰老的咖啡。午睡又进入公园梦，试图带少年离开却不断绕回秋千，并经历梦中醒来，暴露出仍未摆脱的内在束缚。\",\"turn\":\"重返校园的愿望萌生，咖啡衰老与公园牢笼持续铺垫。\",\"time\":\"2006年6月\",\"people\":[\"苏雨晴\",\"风音\",\"大白\",\"曲奇\",\"咖啡\",\"梦中少年\"],\"objects\":[\"高中语文书\",\"秋千\"],\"places\":[\"宠物店\",\"河边大树\",\"梦中公园\"]},{\"key\":\"c602\",\"id\":602,\"title\":\"2006 年的台风\",\"kind\":\"main\",\"volume\":5,\"start\":2375,\"end\":2378,\"summary\":\"台风将至，风音让雨晴提前下班。她收起阳台物品，独自面对第三个夏天的风雨，回忆第一年合租伙伴及第二年夕晨相伴的温暖。她已逐渐走出夕晨去世后的失控悲痛，并蓄发寄托怀念；咖啡对爱吃的食物也提不起精神，衰老征兆更加明显。\",\"turn\":\"独居的清冷与咖啡的衰弱并置，下一次失去即将到来。\",\"time\":\"2006年初夏台风日\",\"people\":[\"苏雨晴\",\"风音\",\"曲奇\",\"咖啡\",\"林夕晨\"],\"objects\":[\"咖啡纸盒窝\",\"面包虫干\"],\"places\":[\"宠物店\",\"海边出租屋\"]},{\"key\":\"c603\",\"id\":603,\"title\":\"咖啡死了（上）\",\"kind\":\"main\",\"volume\":5,\"start\":2379,\"end\":2382,\"summary\":\"台风夜雨晴早睡，再梦见雪中的公园与篝火旁的少年；少年说等天亮自然能离开。曲奇焦急叫醒她，带她发现咖啡已失去呼吸与心跳。她无法接受又一位家人离去，致电仍在店里的风音，抱着纸盒冲入暴雨，希望获得最后一次挽救的机会。\",\"turn\":\"咖啡已死亡；雨晴仍把赴宠物店求救当作最后希望。\",\"time\":\"2006年台风夜\",\"people\":[\"苏雨晴\",\"曲奇\",\"咖啡\",\"风音\",\"梦中少年\"],\"objects\":[\"咖啡纸盒窝\",\"白色连衣裙\",\"梦中篝火\"],\"places\":[\"出租屋\",\"梦中公园\",\"台风街道\"]},{\"key\":\"c604\",\"id\":604,\"title\":\"咖啡死了（下）\",\"kind\":\"main\",\"volume\":5,\"start\":2383,\"end\":2386,\"summary\":\"雨晴在台风中奔跑跌倒，纸盒脱手，咖啡遗体落入排水道被冲走；她又被风卷起的铁桶击昏。莫空、邻居秋易和黑狗黑皇发现并救她到秋易家。醒来后她拒绝留宿，借伞返回寻找无果，接受咖啡自然死亡却遗憾无法安葬，最后穿湿衣疲惫地睡倒在地。\",\"turn\":\"咖啡遗体遗失；莫空的救助重新进入雨晴生活，受寒引发后续病情。\",\"time\":\"2006年台风夜\",\"people\":[\"苏雨晴\",\"咖啡\",\"曲奇\",\"莫空\",\"秋易\",\"黑皇\"],\"objects\":[\"纸盒\",\"铁桶\",\"黑色雨伞\"],\"places\":[\"台风街道\",\"排水道\",\"秋易家\",\"出租屋\"]},{\"key\":\"c605\",\"id\":605,\"title\":\"发烧\",\"kind\":\"main\",\"volume\":5,\"start\":2387,\"end\":2390,\"summary\":\"雨晴在湿衣与地板上睡了一夜，醒来身体极度不适。风音电话询问并准假，她坚持自行去医院，艰难乘车后险些摔倒。莫空及时扶住她，陪她挂专家号、填写病历。孤身生病的无助被实际照料打破，她在牵手同行中感到意外的安心。\",\"turn\":\"疾病使雨晴接受莫空帮助，二人的信任开始迅速加深。\",\"time\":\"台风翌日\",\"people\":[\"苏雨晴\",\"莫空\",\"风音\",\"曲奇\",\"出租车司机\"],\"objects\":[\"病历本\"],\"places\":[\"出租屋\",\"出租车\",\"小城市医院\"]},{\"key\":\"c606\",\"id\":606,\"title\":\"贫血低烧\",\"kind\":\"main\",\"volume\":5,\"start\":2391,\"end\":2394,\"summary\":\"候诊时雨晴出现强烈既视感，仿佛预见旁人摔倒和医生叫号；她还因莫空帮助别人而失落。小说中的中医诊断贫血、着凉并提示其他健康问题。莫空付款取药，承诺代煎，并解释自己受她大舅安排照顾她。雨晴既感动又介意这是否只是工作，回家途中已期待被他特别对待。\",\"turn\":\"莫空受大舅委托的说法解除警惕，也让雨晴纠结照顾是否出于感情。\",\"time\":\"台风翌日\",\"people\":[\"苏雨晴\",\"莫空\",\"中医\",\"摔倒的女人\",\"苏雨晴的大舅\"],\"objects\":[\"病历本\",\"中药\",\"薄荷糖\",\"家门钥匙\"],\"places\":[\"小城市医院\",\"出租屋\"]},{\"key\":\"c607\",\"id\":607,\"title\":\"中药的香味\",\"kind\":\"main\",\"volume\":5,\"start\":2395,\"end\":2398,\"summary\":\"莫空在雨晴家煎药、煮粥、清扫并照顾她休息。雨晴由此想起亲人的保护，萌生回家的念头，也越来越希望他长久留下。莫空外出采购至傍晚归来，带回食品、猫罐头和进口药物，又泡出与她童年相似的蜂蜜果茶；钥匙的变化预示他已经准备持续来照料。\",\"turn\":\"照料唤醒家庭记忆，雨晴在依赖中对莫空萌生感情。\",\"time\":\"病后休养日\",\"people\":[\"苏雨晴\",\"莫空\",\"曲奇\",\"苏雨晴的母亲\",\"苏雨晴的大舅\"],\"objects\":[\"中药\",\"白粥\",\"蜂蜜果茶\",\"进口雌激素\",\"复制钥匙\",\"猫罐头\"],\"places\":[\"出租屋\"]},{\"key\":\"c608\",\"id\":608,\"title\":\"无微不至的照顾\",\"kind\":\"main\",\"volume\":5,\"start\":2399,\"end\":2402,\"summary\":\"莫空的果茶和饮食照顾让雨晴想起母亲为她学习营养知识的往事。翌晨他用配好的钥匙再次送来早餐，病情好转的雨晴穿上夕晨送的校服去上班，莫空一路护送。她主动问晚上是否还来，随后因喜欢莫空而对夕晨心生愧疚；风音则鼓励她面对新的感情。\",\"turn\":\"新的依恋与对亡者忠诚之间形成雨晴的心理冲突。\",\"time\":\"病后第二日\",\"people\":[\"苏雨晴\",\"莫空\",\"风音\",\"曲奇\",\"苏雨晴的母亲\",\"林夕晨\"],\"objects\":[\"复制钥匙\",\"夕晨赠校服\",\"蜂蜜果茶\"],\"places\":[\"出租屋\",\"宠物店\"]},{\"key\":\"c609\",\"id\":609,\"title\":\"曲奇的世界\",\"kind\":\"main\",\"volume\":5,\"start\":2403,\"end\":2406,\"summary\":\"本章以拟人化的曲奇视角重述咖啡死亡：它先察觉老友衰弱，最终唤醒雨晴求助。咖啡离去使它更珍惜朋友，它把莫空视作可靠的人，并希望两人相伴，以免雨晴孤独。曲奇与黑皇交流时听说另一只黄白猫异常聪明，留下跨故事的动物线索。\",\"turn\":\"咖啡与曲奇的深厚情谊得到补叙；曲奇希望保护雨晴，却未料她会先离世。\",\"time\":\"\",\"people\":[\"曲奇\",\"咖啡\",\"苏雨晴\",\"莫空\",\"秋易\",\"黑皇\",\"黄白猫\"],\"objects\":[\"咖啡纸盒窝\"],\"places\":[\"出租屋\",\"小城市\"]},{\"key\":\"c610\",\"id\":610,\"title\":\"田螺先生？\",\"kind\":\"main\",\"volume\":5,\"start\":2407,\"end\":2410,\"summary\":\"雨晴下班失望地没见到莫空，却在家发现他早已备好晚餐。莫空连曲奇喜欢干燥猫粮都清楚，像田螺先生般自然地进入生活。他答应照顾到她回家，雨晴反而把归期推迟到头发能扎双马尾时。夜里她重新感到独居空旷，翌晨又迎来他准备的早餐。\",\"turn\":\"雨晴开始期待持续陪伴，对回家与分离产生新的矛盾。\",\"time\":\"2006年6月，计划八九月回家\",\"people\":[\"苏雨晴\",\"莫空\",\"曲奇\",\"风音\"],\"objects\":[\"晚餐\",\"猫粮\",\"钥匙\",\"进口药物\"],\"places\":[\"宠物店\",\"出租屋\"]},{\"key\":\"c611\",\"id\":611,\"title\":\"夜晚的楼顶天台\",\"kind\":\"main\",\"volume\":5,\"start\":2411,\"end\":2414,\"summary\":\"莫空逐渐每天接雨晴下班，风音时常打趣两人的关系。雨晴既享受照顾又害怕将来失去，主动提出去他的天台住处看看。途中疲惫又扭脚，莫空背她上楼并处理伤处；她在安全感、羞怯与对夕晨的愧疚间摇摆，随后期待一起露天烧烤。\",\"turn\":\"主动探访使关系更亲密，莫空通过实际行动回应她的脆弱。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"莫空\",\"风音\",\"秋易\"],\"objects\":[\"红花油\",\"膏药\",\"铁桶烧烤架\"],\"places\":[\"夜间街道\",\"莫空楼顶阁楼\"]},{\"key\":\"c612\",\"id\":612,\"title\":\"铁桶烧烤\",\"kind\":\"main\",\"volume\":5,\"start\":2415,\"end\":2418,\"summary\":\"雨晴在莫空天台吃铁桶烧烤，发现他独居时常吃方便面，却为她准备细致丰盛的食物。她把简陋天台感受为城市里的桃源，幸福更多来自陪伴。暴雨突然来临，莫空收拾并坚持送她回家；雨晴没说出口想留宿，却主动让他靠近伞下，两人的身体与感情距离进一步缩短。\",\"turn\":\"雨中共伞让含蓄依恋转为双方可以感知的亲近。\",\"time\":\"台风后约一周多\",\"people\":[\"苏雨晴\",\"莫空\"],\"objects\":[\"铁桶烧烤架\",\"方便面袋\",\"小冰箱\",\"蔬菜汤\",\"雨伞\"],\"places\":[\"莫空楼顶天台\",\"雨中街道\"]},{\"key\":\"c613\",\"id\":613,\"title\":\"和风羽蓝一起看店\",\"kind\":\"main\",\"volume\":5,\"start\":2419,\"end\":2422,\"summary\":\"2006年7月2日，风音出门约会，风羽蓝代为开宠物店。雨晴熟练承担清洁和照顾动物的工作，从羽蓝的生疏看到自己过去的模样，也为店里淘汰成年花枝鼠的做法难过。两人忙完后准备吃金家辉送来的披萨，在阅读、猫陪伴和阳光中分享平淡午后。\",\"turn\":\"雨晴已从初入社会的怯弱者成长为能独当一面的店员。\",\"time\":\"2006年7月2日\",\"people\":[\"苏雨晴\",\"风羽蓝\",\"风音\",\"金家辉\",\"莫空\",\"曲奇\"],\"objects\":[\"宠物笼具\",\"杂志\",\"披萨\"],\"places\":[\"宠物店\"]},{\"key\":\"c614\",\"id\":614,\"title\":\"星探\",\"kind\":\"main\",\"volume\":5,\"start\":2423,\"end\":2426,\"summary\":\"金家辉送披萨来，与风羽蓝谈到高中毕业及和朋友同读大学的约定，触动雨晴重返学校的愿望。自称深井娱乐公司星探的男子邀两位女孩演戏，两人均拒绝，身份真伪未证实。风音狼狈归店，称因约会对象拒绝她而打了对方，令在场三人错愕，也表现她冲动强势的一面。\",\"turn\":\"拒绝出名守住普通生活，校园话题再次加深雨晴的归家愿望。\",\"time\":\"2006年7月2日\",\"people\":[\"苏雨晴\",\"风羽蓝\",\"金家辉\",\"风音\",\"星探\",\"风音约会对象\"],\"objects\":[\"披萨\",\"星探名片\"],\"places\":[\"宠物店\"]},{\"key\":\"c615\",\"id\":615,\"title\":\"扎一个双马尾\",\"kind\":\"main\",\"volume\":5,\"start\":2427,\"end\":2430,\"summary\":\"头发终于长过肩，雨晴用黑檀木梳、黑发绳和小花发卡扎起双马尾，既兴奋又怀念曾替夕晨梳发的亲密。早餐间莫空承认自己留在小城市是因为她，并补充不是工作缘故；随后告知7月15日是生日，邀请她晚间去游乐园。一个多月相伴已成为她生活中不可缺的一部分。\",\"turn\":\"双马尾成为怀念与新生活的共同标志，莫空首次明确排除纯工作动机。\",\"time\":\"2006年7月15日早晨\",\"people\":[\"苏雨晴\",\"莫空\",\"林夕晨\",\"曲奇\"],\"objects\":[\"黑檀木梳\",\"黑发绳\",\"小花发卡\",\"嵌糕\"],\"places\":[\"出租屋\",\"通勤街道\"]},{\"key\":\"c616\",\"id\":616,\"title\":\"莫空的生日\",\"kind\":\"main\",\"volume\":5,\"start\":2431,\"end\":2434,\"summary\":\"莫空生日当晚，两人到郊区游乐园乘摩天轮、吃简单小食。雨晴期待告白却又害羞；游玩后仍执意给他寻找生日蛋糕，终于买到剩下的小奶油蛋糕并插上蜡烛。莫空表示有她便足够，她也坦承相伴让自己开心，含蓄完成心意确认。\",\"turn\":\"双方以生日陪伴和简短话语确认恋爱心意。\",\"time\":\"2006年7月15日晚\",\"people\":[\"苏雨晴\",\"莫空\"],\"objects\":[\"奶油小蛋糕\",\"生日蜡烛\",\"贡丸\"],\"places\":[\"小城市郊区游乐园\",\"摩天轮\"]},{\"key\":\"c617\",\"id\":617,\"title\":\"我……想回家\",\"kind\":\"main\",\"volume\":5,\"start\":2435,\"end\":2438,\"summary\":\"莫空送雨晴一条红色猫眼石银手链作护身符，她回赠珍爱的泰国佛珠。得到无条件接纳及归家后仍会相伴的保证，雨晴下定决心回父母家。翌晨她辞去宠物店工作，与莫空亲昵称呼彼此，带上夕晨遗物和曲奇出发，也在心里承诺携夕晨的那份继续快乐生活。\",\"turn\":\"互换信物确立关系，回家决定终结三年漂泊。\",\"time\":\"2006年7月16日\",\"people\":[\"苏雨晴\",\"莫空\",\"风音\",\"林夕晨\",\"曲奇\"],\"objects\":[\"猫眼石银手链\",\"泰国佛珠\",\"两张火车票\",\"夕晨遗物\",\"行李箱\"],\"places\":[\"出租屋\",\"小城市\"]},{\"key\":\"c618\",\"id\":618,\"title\":\"杭州\",\"kind\":\"main\",\"volume\":5,\"start\":2439,\"end\":2442,\"summary\":\"归途上曲奇随两人同行，莫空证实三年前列车上那位邻座就是自己，只称最初是偶遇。雨晴梦到能够生育并给孩子取名语默，醒后莫空知道此名，解释她说了梦话。抵达杭州，她拿出保留三年、已经生锈的家门钥匙；同一条铁路从逃离路线变成带着爱与希望的回家路。\",\"turn\":\"首程列车伏笔回收，语默之名首次在梦中埋下收养女儿的线索。\",\"time\":\"2006年7月16日\",\"people\":[\"苏雨晴\",\"莫空\",\"曲奇\",\"梦中的孩子\"],\"objects\":[\"家门钥匙\",\"行李箱\",\"火车票\"],\"places\":[\"小城市火车站\",\"归途列车\",\"杭州城站\"]},{\"key\":\"c619\",\"id\":619,\"title\":\"车祸？\",\"kind\":\"main\",\"volume\":5,\"start\":2443,\"end\":2446,\"summary\":\"两人乘公交返回杭州家中，莫空突然带雨晴和行李跳车，随后轿车撞上公交并引发爆炸。他称是自己家族的人追杀自己。车内乘客却在第二次爆炸前全部逃出，无人员伤亡；雨晴怀疑他有超常力量，他仅以运气解释。惊险过后两人步行继续归家。\",\"turn\":\"莫家威胁首次正面暴露；莫空超常能力仅有暗示，身份尚待说明。\",\"time\":\"2006年7月16日\",\"people\":[\"苏雨晴\",\"莫空\",\"公交司机\",\"乘客\",\"莫家追杀者\"],\"objects\":[\"行李箱\",\"公交车\",\"撞击轿车\",\"夕晨遗物\"],\"places\":[\"杭州公交路段\"]},{\"key\":\"c620\",\"id\":620,\"title\":\"回家\",\"kind\":\"main\",\"volume\":5,\"start\":2447,\"end\":2450,\"summary\":\"雨晴用旧钥匙打开家门，发现母亲正照顾新生的弟弟苏冬凌。母亲激动拥抱她，以女儿相称并表达无论怎样都是自己的孩子。莫空自称未来女婿并送自制香水。母亲说明父母早知她的住处，为避免强制带回激化矛盾才暗中照看，原准备接她回来，三年的家庭隔阂开始解除。\",\"turn\":\"母亲公开接纳女儿身份，雨晴从惧怕被拒绝转为获接纳的感动。\",\"time\":\"2006年7月16日\",\"people\":[\"苏雨晴\",\"莫空\",\"苏雨晴的母亲\",\"苏冬凌\",\"苏榕槐\"],\"objects\":[\"旧钥匙\",\"自制香水\"],\"places\":[\"杭州家中\"]},{\"key\":\"c621\",\"id\":621,\"title\":\"爸爸妈妈\",\"kind\":\"main\",\"volume\":5,\"start\":2451,\"end\":2455,\"summary\":\"母亲介绍冬凌与姐姐相认，化解雨晴担心自己被取代的心结。父亲赶回家后温柔拥抱她，接纳莫空的陪伴。晚餐中父母了解莫空写小说、认识女儿三年等情况，欣赏他的谈吐与见识，逐渐认可这段关系。莫空仍选择自行租屋，约好翌日再来，雨晴感到亲情与爱情同时归位。\",\"turn\":\"父亲接纳完成家庭和解，父母基本认可莫空为未来女婿。\",\"time\":\"2006年7月16日下午至晚间\",\"people\":[\"苏雨晴\",\"莫空\",\"苏雨晴父母\",\"苏冬凌\"],\"objects\":[\"莫空赠父亲的小礼盒\"],\"places\":[\"杭州家中\"]},{\"key\":\"c622\",\"id\":622,\"title\":\"做好准备了吗？\",\"kind\":\"main\",\"volume\":5,\"start\":2456,\"end\":2459,\"summary\":\"雨晴洗浴后发现母亲准备了与当年被父亲烧毁的第一套女装近乎相同的白裙，房间也早增添女装与玩偶，意识到父母长期的歉意和准备。父亲主动敲门询问她是否已决定以女性身份生活，继而告知手术、身份变更、迁往台湾及重新上学均已筹划，全家将陪她开始新生活。\",\"turn\":\"烧裙创伤以补买同款回收；父母由阻止者转为转变与迁居的支持者。\",\"time\":\"返家当晚\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"莫空\",\"曲奇\"],\"objects\":[\"补买的白色连衣裙\",\"女装衣柜\",\"毛绒玩具\",\"旧钥匙\"],\"places\":[\"杭州家中\"]},{\"key\":\"c623\",\"id\":623,\"title\":\"南屏山\",\"kind\":\"main\",\"volume\":5,\"start\":2460,\"end\":2463,\"summary\":\"雨晴带莫空游西湖、南屏山净慈寺，并抽得上上签，期待手术及台湾新生活。莫空承诺同行，透露自己曾是莫家家主，因厌倦争斗离开，族人因忌惮他才追杀。两人在清静处坦诚交谈，雨晴愈加自在；父母的安排与莫空的陪伴让未来看似顺遂。\",\"turn\":\"莫空家主身份揭晓，并将迁台与躲开家族争斗联系起来。\",\"time\":\"返家翌日\",\"people\":[\"苏雨晴\",\"莫空\"],\"objects\":[\"上上签\",\"签筒\"],\"places\":[\"西湖\",\"南屏山\",\"净慈寺\"]},{\"key\":\"c624\",\"id\":624,\"title\":\"心理测试\",\"kind\":\"main\",\"volume\":5,\"start\":2464,\"end\":2467,\"summary\":\"回家后的雨晴安睡到中午，与依恋自己的弟弟逐渐亲近。父亲带她到同学开设的心理诊所做手术前评估，医生通过轻松交谈了解她长期的女性认同，并同意开具相关证明。父亲再问是否准备好，她承认变化来得突然，却充满幸福与期待。\",\"turn\":\"手术所需评估在小说情节中通过，家庭支持转入实际办理阶段。\",\"time\":\"返家后第三日左右\",\"people\":[\"苏雨晴\",\"苏冬凌\",\"苏雨晴父母\",\"心理医生\"],\"objects\":[\"心理评估证明\",\"手机贪吃蛇\"],\"places\":[\"杭州家中\",\"心理诊所\"]},{\"key\":\"c625\",\"id\":625,\"title\":\"最终的一步（上）\",\"kind\":\"main\",\"volume\":5,\"start\":2468,\"end\":2471,\"summary\":\"父亲花半个月完备手续并调整证件年龄，最终选择带全家赴芝加哥接受手术。莫空因未办签证留在国内，送她到机场并等待归来。飞行途中雨晴反思三年漂泊，也看见父母为自己劳心而衰老。她对身份转换保持坚定，同时带着手术前的紧张和期待。\",\"turn\":\"漫长愿望进入实施阶段，雨晴暂别莫空接受家人陪护。\",\"time\":\"2006年夏；返家约半个月后\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"苏冬凌\",\"莫空\"],\"objects\":[\"手续证明\",\"身份证\",\"机票\"],\"places\":[\"杭州机场\",\"赴美飞机\"]},{\"key\":\"c626\",\"id\":626,\"title\":\"最终的一步（下）\",\"kind\":\"main\",\"volume\":5,\"start\":2472,\"end\":2475,\"summary\":\"全家抵达芝加哥并适应时差，父亲奔走办理医院手续，母亲协助沟通。小说将手术医院设为西北纪念医院。雨晴确认只接受与性别转换有关的手术，拒绝额外丰胸等项目；各项检查与准备完成后，她在父母鼓励下进入手术室，等待已久的改变正式开始。\",\"turn\":\"手术开始；原文医疗程序只按情节记录，不作为现实指南。\",\"time\":\"2006年夏赴美后\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"苏冬凌\",\"医生\"],\"objects\":[\"手术资料\"],\"places\":[\"芝加哥\",\"酒店\",\"西北纪念医院\"]},{\"key\":\"c627\",\"id\":627,\"title\":\"破蛹成蝶（上）\",\"kind\":\"main\",\"volume\":5,\"start\":2476,\"end\":2479,\"summary\":\"手术过程中雨晴意识朦胧，叙述以破茧比喻她为身份与生活付出的代价。醒前她仿佛听到莫空安慰的声音，翌晨在母亲陪伴的病房清醒，确认手术已经完成。她兴奋地迎接新生活，同时需要长时间卧床恢复，父母用书、游戏与测试版诺基亚手机陪她度过等待。\",\"turn\":\"身份转换的重大愿望实现；莫空声音为意识模糊时的感受，非赴美事实。\",\"time\":\"手术翌日\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"苏冬凌\",\"梦中莫空\",\"医生\"],\"objects\":[\"绷带\",\"诺基亚测试手机\",\"软糖\"],\"places\":[\"西北纪念医院病房\"]},{\"key\":\"c628\",\"id\":628,\"title\":\"破蛹成蝶（下）\",\"kind\":\"main\",\"volume\":5,\"start\":2480,\"end\":2483,\"summary\":\"在芝加哥恢复约一个月后，雨晴终于能够短时间行走，全家乘飞机回国。异国停留让她更怀念家乡，也因未见莫空而不安。回杭州时莫空及时出现并提醒她保护术后身体，父母欣赏他的守候。身体恢复虽仍在继续，家人接纳与伴侣等待让她感到前所未有的安稳。\",\"turn\":\"术后平安回国，莫空兑现等待承诺。\",\"time\":\"手术后约一个月\",\"people\":[\"苏雨晴\",\"莫空\",\"苏雨晴父母\",\"苏冬凌\"],\"objects\":[\"机票\",\"行李\"],\"places\":[\"芝加哥医院\",\"杭州萧山机场\",\"杭州家中\"]},{\"key\":\"c629\",\"id\":629,\"title\":\"通模具\",\"kind\":\"main\",\"volume\":5,\"start\":2484,\"end\":2487,\"summary\":\"父亲与莫空饮酒庆祝雨晴归来，雨晴送恋人到小区门口，仍被提醒别走太远。回家后她第一次仔细面对术后身体，为终于接近长期愿望而满足，也意识到改变并不消除所有差异。她开始自行承担后续康复护理，新的生活仍伴随着身体恢复的日常限制。\",\"turn\":\"手术后的喜悦进入持续护理阶段，避免把手术写成毫无代价的瞬间完成。\",\"time\":\"返国当晚\",\"people\":[\"苏雨晴\",\"莫空\",\"苏雨晴父母\"],\"objects\":[\"术后护理模具\",\"素色睡裙\"],\"places\":[\"杭州家中\",\"小区门口\"]},{\"key\":\"c630\",\"id\":630,\"title\":\"生命的过客\",\"kind\":\"main\",\"volume\":5,\"start\":2488,\"end\":2491,\"summary\":\"雨晴因术后护理和曲奇暂住莫空处而失眠，收到久未联系的冉空城短信，得知他已有女友，并坦然认清旧日情愫主要是好感。翌日莫空带曲奇归来，她在重聚与家人照料中休养。父母告知即将返回苏家本部办理身份事务，让她对旧日家族环境重新不安。\",\"turn\":\"冉空城感情线明确退为普通朋友，苏家冲突将进入解决阶段。\",\"time\":\"2006年9月前后\",\"people\":[\"苏雨晴\",\"莫空\",\"曲奇\",\"冉空城\",\"苏雨晴父母\",\"苏冬凌\"],\"objects\":[\"术后模具\",\"山寨手机\",\"短信\"],\"places\":[\"杭州家中\"]},{\"key\":\"c631\",\"id\":631,\"title\":\"大家族\",\"kind\":\"main\",\"volume\":5,\"start\":2492,\"end\":2495,\"summary\":\"一家乘车前往苏州郊区苏家镇。叙述交代母系台湾村落原亦为苏家分支，父母属远房亲戚，大舅长期在大陆任职。雨晴厌恶家族的等级、争产与面子规则，担忧女装露面连累父母；母亲却坚持支持她。曲奇再由莫空照顾，家族产业归属也为后续脱离谈判埋下原因。\",\"turn\":\"大陆苏家与台湾支系关系被说明，家庭支持将面对宗族权力。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"苏冬凌\",\"莫空\",\"曲奇\",\"苏雨晴的大舅\"],\"objects\":[\"奔驰车\"],\"places\":[\"杭州至苏州\",\"苏家镇\"]},{\"key\":\"c632\",\"id\":632,\"title\":\"侮辱和嘲笑\",\"kind\":\"main\",\"volume\":5,\"start\":2496,\"end\":2499,\"summary\":\"苏家别墅的沈阿姨对雨晴变化疑惑，家族欢迎宴上敌对成员更公开羞辱她与父母。苏榕槐一改以往周旋态度，直接斥退挑衅者，无意维持虚假客气。族长和长老晚间与他谈话后神色难看，他却轻松起来，并告知翌日办理台湾身份，是否改名也由女儿自己决定。\",\"turn\":\"父亲公开保护女儿并挑战家族关系，脱离宗族的决定逐渐明朗。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"苏榕槐\",\"苏雨晴的母亲\",\"苏冬凌\",\"沈阿姨\",\"族长\",\"长老\",\"敌对族人\"],\"objects\":[\"户籍资料\"],\"places\":[\"苏家镇别墅\",\"家族宴会厅\"]},{\"key\":\"c633\",\"id\":633,\"title\":\"脱离家族\",\"kind\":\"main\",\"volume\":5,\"start\":2500,\"end\":2503,\"summary\":\"父母提出新名苏默冉，但雨晴最终保留苏雨晴，认为新生活无需抹去过去。苏榕槐经过整夜谈判，带全家放弃苏家身份和继承权，交回原产业，争取到一千万财产与台湾小公司。雨晴为父母和弟弟的损失愧疚，父亲则强调自己早想离开争斗环境，全家告别苏家镇。\",\"turn\":\"苏家压力通过主动退出解决；生活资源减少但仍富足，绝非破产。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"苏榕槐\",\"苏雨晴的母亲\",\"苏冬凌\",\"族长\",\"长老\",\"沈阿姨\"],\"objects\":[\"户籍迁移资料\",\"家族确认书\",\"资产交接文件\"],\"places\":[\"苏家镇\",\"办理户籍的办公室\"]},{\"key\":\"c634\",\"id\":634,\"title\":\"新的身份证\",\"kind\":\"main\",\"volume\":5,\"start\":2504,\"end\":2507,\"summary\":\"完成杭州工作交接后，全家迁往台湾花莲，曲奇也被专门托运；莫空因另有事务暂留大陆，承诺稍后会来。雨晴办理记为女性的新身份证，证件出生年从1989调整为1991，随后回到母系苏家村。村民和外婆亲切接纳她的变化，与大陆宗族的排斥形成鲜明对照。\",\"turn\":\"新的法定身份与宽容居住环境确立；原文年龄和年份存在后续不一致。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"苏冬凌\",\"莫空\",\"曲奇\",\"外婆\",\"苏家村村民\"],\"objects\":[\"新身份证\",\"航空笼\"],\"places\":[\"杭州机场\",\"台湾花莲\",\"苏家村\"]},{\"key\":\"c635\",\"id\":635,\"title\":\"重新开始的生活（上）\",\"kind\":\"main\",\"volume\":5,\"start\":2508,\"end\":2511,\"summary\":\"全家入住外祖父母旧私塾改建的住宅，父亲已提前完成装修。雨晴带来玩偶、衣服、夕晨遗物及朋友赠品等四箱行李，大表哥特意翘班回来，虽爱拿她打趣，却明确欢迎多一个妹妹并帮忙搬运。熟悉的嬉闹使多年未见的亲情迅速恢复，她开始亲手整理自己的新房间。\",\"turn\":\"亲属以日常相处消除身份尴尬，旧物随迁居保留过去的人际记忆。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"大表哥\",\"苏雨晴父母\",\"外公\",\"外婆\",\"张思凡\",\"林夕晨\"],\"objects\":[\"四箱行李\",\"毛绒玩具\",\"夕晨遗物\",\"张思凡赠唇膏\",\"陶瓷杯\",\"生日礼物\"],\"places\":[\"苏家村\",\"旧私塾改建住宅\"]},{\"key\":\"c636\",\"id\":636,\"title\":\"重新开始的生活（下）\",\"kind\":\"main\",\"volume\":5,\"start\":2512,\"end\":2515,\"summary\":\"雨晴整理完房间后踏实入睡，母亲为她留饭。入学手续暂定下一学期开始，期间将由家教补上课程及繁体字，她获得短暂休息。十月的海边清晨里，她与母亲、弟弟吃早餐和散步，父亲忙于接收台湾公司，三位表哥也各有学业工作，新生活正式安定下来。\",\"turn\":\"住所与学习安排落实，家人各自展开在台湾的生活。\",\"time\":\"迁台后的十月；原文年份顺序待核\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"苏冬凌\",\"曲奇\",\"三位表哥\"],\"objects\":[\"新房家具\",\"课业资料\"],\"places\":[\"苏家村住宅\",\"海边村庄\"]},{\"key\":\"c637\",\"id\":637,\"title\":\"母亲孩童时的回忆\",\"kind\":\"main\",\"volume\":5,\"start\":2516,\"end\":2519,\"summary\":\"母亲带雨晴和冬凌重游村庄，讲述荒田、旧祠堂、已故长辈以及小时候和兄长们调皮玩耍的往事。下午雨晴遇到变得腼腆的三表哥，对方欣喜接纳她成为妹妹。她送出红黑色贝壳，兑现童年弄坏他藏品后许下的补偿约定，两人重新找回熟悉的亲密。\",\"turn\":\"母系亲属历史补充，贝壳兑现旧约成为跨越年岁的亲情物证。\",\"time\":\"迁台后的秋季；含母亲童年回忆\",\"people\":[\"苏雨晴\",\"苏雨晴的母亲\",\"苏冬凌\",\"三表哥\",\"三位舅舅\",\"已故村族长\"],\"objects\":[\"红黑贝壳\",\"旧星纹贝壳\"],\"places\":[\"苏家村\",\"废弃祠堂\",\"村墓地\"]},{\"key\":\"c638\",\"id\":638,\"title\":\"迎着朝阳\",\"kind\":\"main\",\"volume\":5,\"start\":2520,\"end\":2523,\"summary\":\"清晨雨晴独自到海边看日出，意外迎来终于抵台的莫空。两人拥抱重逢，他把大衣披给她并再次保证不会离开。莫空计划自己搭建小木屋，原来也是父母安排的家教；他当场用沙滩作字板教授历史与繁体字，恋人陪伴和重返校园的准备由此合在一起。\",\"turn\":\"莫空兑现同行承诺，家教身份揭晓，二人在台湾重启共同生活。\",\"time\":\"迁台后莫空抵达的清晨\",\"people\":[\"苏雨晴\",\"莫空\",\"苏雨晴的母亲\"],\"objects\":[\"莫空大衣\",\"沙滩字迹\"],\"places\":[\"苏家村海滩\",\"外婆家\"]},{\"key\":\"c639\",\"id\":639,\"title\":\"表哥们的恶趣味\",\"kind\":\"main\",\"volume\":5,\"start\":2524,\"end\":2527,\"summary\":\"三个表哥早晨来找雨晴玩，经母亲允许去叫醒她，却未先敲门便进入卧室。大表哥翻看私人物品，二表哥偷吃牛肉干，三表哥局促不安；发现术后护理模具后误会用途，惊醒雨晴。原著以闹剧写亲近，却同时显露亲属相处中的隐私边界被侵犯。\",\"turn\":\"亲密玩闹越界引起惊吓，必须由雨晴解释护理物件的真实作用。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"三位表哥\",\"苏雨晴的母亲\",\"曲奇\"],\"objects\":[\"牛肉干\",\"术后护理模具\",\"私人物品\"],\"places\":[\"苏家村住宅卧室\"]},{\"key\":\"c640\",\"id\":640,\"title\":\"下身插棒棒的邪恶少女\",\"kind\":\"main\",\"volume\":5,\"start\":2528,\"end\":2531,\"summary\":\"雨晴赶表哥们出房并说明模具只是术后护理用品，大表哥仍继续打趣，招来她羞恼追打。熟悉的亲情恢复，却不能再照搬童年时毫无边界的相处。几人决定骑车去花莲吃小吃，雨晴坐二表哥车后座；莫空发短信祝她玩得开心，显示他早知这次出游安排。\",\"turn\":\"用品误会得到解释，雨晴开始在新身份下重新协商亲密边界。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"三位表哥\",\"莫空\",\"苏雨晴的母亲\"],\"objects\":[\"术后护理模具\",\"自行车\",\"台湾新手机\"],\"places\":[\"苏家村住宅\",\"赴花莲道路\"]},{\"key\":\"c641\",\"id\":641,\"title\":\"美食街\",\"kind\":\"main\",\"volume\":5,\"start\":2532,\"end\":2535,\"summary\":\"兄妹四人骑车来到花莲美食街，回忆童年合钱分食、表哥们总把更多留给雨晴的经历。如今钱足够了，却无法重现当年滋味。随后他们重访衰落的游戏厅，老板仍认得旧客并免费给游戏币，大家故意热闹游玩，既享受重聚也感受到成长和时代变化带来的失落。\",\"turn\":\"童年地点尚在而氛围已变，怀旧支线以珍惜当下相聚回应流逝。\",\"time\":\"正文此章明确写2007年\",\"people\":[\"苏雨晴\",\"三位表哥\",\"游戏厅老板\",\"表姐\"],\"objects\":[\"自行车\",\"游戏币\",\"街机\"],\"places\":[\"花莲美食街\",\"旧游戏厅\"]},{\"key\":\"c642\",\"id\":642,\"title\":\"莫空的小木屋\",\"kind\":\"main\",\"volume\":5,\"start\":2536,\"end\":2540,\"summary\":\"雨晴夜访莫空刚建好的小木屋，惊讶布局仿照自己初到小城市的出租房。莫空煮汤圆，复现她昔日贫困时用电水壶做夜宵的记忆，两人安静相伴并谈婚后领养女儿。雨晴想要女孩，莫空提出沿用她梦中取过的名字莫语默；读心与预知疑问仍被他以心理学和梦话解释。\",\"turn\":\"重建旧居把漂泊记忆转为安全归属，领养莫语默的计划提前埋下。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"莫空\",\"曲奇\",\"村中黄狗\"],\"objects\":[\"小木屋\",\"汤圆\",\"手电筒\"],\"places\":[\"苏家村道路\",\"莫空小木屋\"]},{\"key\":\"c643\",\"id\":643,\"title\":\"2008 年的春节（上）\",\"kind\":\"main\",\"volume\":5,\"start\":2541,\"end\":2544,\"summary\":\"2008年除夕早晨，雨晴感慨新年与即将复学，仍在心里惦记夕晨。莫空特意从城里买煎饺，大表哥误吃引发一场嬉闹，好在另有一盒。白色异瞳母猫糯米到访，与曲奇亲密相处；雨晴为它取名，也欣慰老朋友有了伴侣，人的相爱与动物相伴在节日里并置。\",\"turn\":\"雨晴在热闹家庭中悼念夕晨；曲奇与糯米的伴侣关系正式登记。\",\"time\":\"2008年2月6日除夕\",\"people\":[\"苏雨晴\",\"莫空\",\"大表哥\",\"曲奇\",\"糯米\",\"林夕晨\"],\"objects\":[\"煎饺\",\"毛线帽\"],\"places\":[\"苏家村住宅\"]},{\"key\":\"c644\",\"id\":644,\"title\":\"2008 年的春节（下）\",\"kind\":\"main\",\"volume\":5,\"start\":2545,\"end\":2548,\"summary\":\"全村到雨晴家吃年夜饭，年轻人聚在楼上玩诈牌，以唱歌为罚而不赌钱。雨晴不善掩饰、大表哥善于虚张声势，莫空始终没输。午夜众人放烟花迎新年，大表哥弄坏玻璃又想让三弟背锅，引起笑闹。雨晴从独自在外过年到被亲友围绕，真切感到团聚的温暖。\",\"turn\":\"孤独春节记忆被团聚的新年覆盖；大表哥外号“大白菜”源于名中采字。\",\"time\":\"2008年2月6日晚至7日凌晨\",\"people\":[\"苏雨晴\",\"莫空\",\"三位表哥\",\"表姐\",\"村民\"],\"objects\":[\"扑克牌\",\"红包\",\"烟花\",\"星星棒\"],\"places\":[\"苏家村住宅\",\"院子\"]},{\"key\":\"c645\",\"id\":645,\"title\":\"花莲高中\",\"kind\":\"main\",\"volume\":5,\"start\":2549,\"end\":2552,\"summary\":\"春节后雨晴以插班生身份进入花莲高中，高中准备与莫空家教使她能跟上课程。莫空骑摩托送她上学，她大胆亲近后进入陌生课堂，以画画打发空隙，并通过双马尾与画笔保留夕晨影响。男同学对新同学好奇议论，她害羞却逐渐开始适应普通女生的校园生活。\",\"turn\":\"多年离校后复学成功，普通校园生活成为新阶段的核心愿望。\",\"time\":\"2008年春节后；开学第三日\",\"people\":[\"苏雨晴\",\"莫空\",\"同班男生\",\"班长\",\"学习委员\",\"林夕晨\"],\"objects\":[\"摩托车\",\"圆珠笔\",\"画本\"],\"places\":[\"苏家村至花莲\",\"花莲高中\"]},{\"key\":\"c646\",\"id\":646,\"title\":\"400 米短跑\",\"kind\":\"main\",\"volume\":5,\"start\":2553,\"end\":2556,\"summary\":\"第一次体育课，雨晴为避免显得脱群勉强跑完四百米，结果心口与腹部不适。同桌杨灵主动关心并请老师免除后续跑步，虽然误认她处于生理期，仍以善意化解她的尴尬。雨晴承认忘记同桌名字，杨灵不以为忤，开始介绍班级趣事，两人由此熟悉。\",\"turn\":\"杨灵成为雨晴新校园的第一个明确朋友；病弱体质持续限制活动。\",\"time\":\"入学初期\",\"people\":[\"苏雨晴\",\"杨灵\",\"体育老师\",\"同班学生\"],\"objects\":[\"运动免课证明\"],\"places\":[\"花莲高中操场\"]},{\"key\":\"c647\",\"id\":647,\"title\":\"自带的便当\",\"kind\":\"main\",\"volume\":5,\"start\":2557,\"end\":2560,\"summary\":\"午间杨灵请求交换便当，雨晴欣然答应，并愿送她一个家中多余的保温饭盒。杨灵回报以清洗餐盒、分享牛奶和介绍朋友，使雨晴逐渐融入班级。女生们好奇每日接送她的成熟男子是谁，雨晴最终坦诚莫空是男友，引出关于年龄与恋爱的交谈。\",\"turn\":\"交换食物与小礼物建立友谊，雨晴公开介绍恋人身份。\",\"time\":\"入学初期同日午间\",\"people\":[\"苏雨晴\",\"杨灵\",\"莫空\",\"苏雨晴的母亲\",\"女同学\",\"班主任\",\"数学老师\"],\"objects\":[\"保温饭盒\",\"便当\",\"糖果\",\"牛奶\"],\"places\":[\"花莲高中教室\"]},{\"key\":\"c648\",\"id\":648,\"title\":\"依赖\",\"kind\":\"main\",\"volume\":5,\"start\":2561,\"end\":2564,\"summary\":\"女同学得知雨晴与莫空年龄相差较大，虽惊讶仍尊重她的选择并体贴转移话题。放学后莫空骑车接她，两人交流当天经历；外婆准备点心，莫空答应以后做便当。晚间一起写作业、玩魔兽世界，雨晴意识到自己越来越依赖他，他承诺长久相伴，恋情逐步融入家庭日常。\",\"turn\":\"校园友谊与恋爱日常并行，互相信任也使雨晴更习惯将困难交给莫空。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"莫空\",\"杨灵\",\"女同学\",\"外公\",\"外婆\",\"曲奇\"],\"objects\":[\"摩托车\",\"南瓜饼\",\"便当\",\"作业本\",\"魔兽世界\"],\"places\":[\"花莲高中\",\"外婆家\"]},{\"key\":\"c649\",\"id\":649,\"title\":\"回小城市看看（上）\",\"kind\":\"main\",\"volume\":5,\"start\":2565,\"end\":2568,\"summary\":\"复学后的暑假，雨晴与莫空回小城市探访旧地。张思凡号码已空、方莜莜停机，宠物店也变成小吃店；许多故人难以再寻。她终于拨通天语遥的电话，约在公园见面，却发现天语遥坐轮椅、目光呆滞，由夏归月照护。重游带来的怀念转为对故人遭际的震动。\",\"turn\":\"旧友失联与店面更换显示时间改变；天语遥的长期病况重新出现。\",\"time\":\"2008年暑假，复学约半年后\",\"people\":[\"苏雨晴\",\"莫空\",\"张思凡\",\"方莜莜\",\"风音\",\"天语遥\",\"夏归月\"],\"objects\":[\"旧电话号码\",\"磁石\"],\"places\":[\"小城市\",\"原宠物店\",\"中山路公园\"]},{\"key\":\"c650\",\"id\":650,\"title\":\"回小城市看看（下）\",\"kind\":\"main\",\"volume\":5,\"start\":2569,\"end\":2573,\"summary\":\"夏归月说明天语遥病后无法自理，父母与她轮流照顾；天语遥见莫空念出小黑，随后短暂叫出月月并试图道谢，但并未完全清醒。雨晴和莫空回旧天台遇到秋易、黑皇；两名男子谈第三十九个轮回、觉醒与改写历史，见雨晴后称在测试小说对话，超自然真相依然留有遮掩。\",\"turn\":\"天语遥仅出现好转希望；轮回与历史改动成为正文的重要悬念，未完整解释。\",\"time\":\"2008年暑假\",\"people\":[\"苏雨晴\",\"莫空\",\"天语遥\",\"夏归月\",\"天语遥父母\",\"秋易\",\"黑皇\",\"小黑\"],\"objects\":[\"轮椅\",\"天语遥手机\",\"莫空记事本\",\"阁楼钥匙\"],\"places\":[\"中山路公园小天坛\",\"莫空旧天台阁楼\"]},{\"key\":\"c651\",\"id\":651,\"title\":\"孤儿院（一）\",\"kind\":\"main\",\"volume\":5,\"start\":2574,\"end\":2577,\"summary\":\"两人遍访叶族博物馆、流庆寺与旧出租屋地段，发现面馆随拆迁消失、旧大润发换成沃尔玛。新闻提及汶川地震与预言，雨晴感慨人们遗忘痛苦却仍盼群体获得接纳。海边旧聚会地唤起夕晨记忆；莫空以经验解释预知，翌日带她去富阳孤儿院，领养愿望重新浮现。\",\"turn\":\"旧地重访结束，旅程转向照顾下一代；雨晴梦见婚姻、领养与自身死亡。\",\"time\":\"原文称汶川地震后一个多月；与暑假口径并列\",\"people\":[\"苏雨晴\",\"莫空\",\"林夕晨\",\"老虎\"],\"objects\":[\"电视新闻\",\"海边帐篷\"],\"places\":[\"叶族博物馆\",\"流庆寺\",\"旧农民房\",\"原大润发超市\",\"海边别墅\",\"富阳\"]},{\"key\":\"c652\",\"id\":652,\"title\":\"孤儿院（二）\",\"kind\":\"main\",\"volume\":5,\"start\":2578,\"end\":2581,\"summary\":\"在富阳金盈儿童福利院，雨晴意外遇到恢复男性社会生活并已婚的张思凡。双方默契不提过去；张思凡因无法生育，与宽容的妻子董花火来领养孩子。夫妻看中林清雾，但这对双胞胎兄妹彼此不愿分开，又争着让对方得到新家庭，收养因此停滞。\",\"turn\":\"张思凡婚姻与不育支线交代；双胞胎分离成为收养的核心难题。\",\"time\":\"2008年暑假\",\"people\":[\"苏雨晴\",\"莫空\",\"张思凡\",\"董花火\",\"林清雾\",\"莫语默\",\"院长\",\"王老师\"],\"objects\":[\"收养资料\",\"婚戒\"],\"places\":[\"富阳金盈儿童福利院\"]},{\"key\":\"c653\",\"id\":653,\"title\":\"孤儿院（三）\",\"kind\":\"main\",\"volume\":5,\"start\":2582,\"end\":2585,\"summary\":\"福利院坚持尊重孩子意愿，董花火仍舍不得放弃林清雾。雨晴原只想陪孩子玩，在老鹰捉小鸡时看到哥哥扑地保护妹妹，更喜爱这对姓林的孩子。林清云诉说不想离开哥哥，雨晴求莫空帮忙却暂未得到办法；孩子们还提到曾带他们游玩、买衣的雯雯姐姐。\",\"turn\":\"亲密相处使雨晴产生真实牵挂，收养选择由抽象愿望变为具体伦理难题。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"莫空\",\"张思凡\",\"董花火\",\"林清雾\",\"莫语默\",\"雯雯姐姐\",\"福利院老师\"],\"objects\":[\"姓名纸条\",\"玩耍道具\"],\"places\":[\"金盈儿童福利院\"]},{\"key\":\"c654\",\"id\":654,\"title\":\"孤儿院（四）\",\"kind\":\"main\",\"volume\":5,\"start\":2586,\"end\":2589,\"summary\":\"两对来访者都决定在福利院过夜，雨晴与莫空谈到将来领养女儿，也坦然享受彼此陪伴。翌日双胞胎带雨晴参观山洞秘密基地，那里住着两只成犬与一窝幼犬，洞口还能眺望景色；莫空因洞口太小留在外面。孩子把珍藏世界分享给客人，信任进一步加深。\",\"turn\":\"孩子与雨晴的关系深化，未来亲子联结在共同游戏中形成。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"莫空\",\"林清雾\",\"莫语默\",\"张思凡\",\"董花火\",\"教太极的老人\",\"大黄与犬群\"],\"objects\":[\"访客硬板床\",\"洞中稻草\"],\"places\":[\"福利院\",\"山洞秘密基地\"]},{\"key\":\"c655\",\"id\":655,\"title\":\"孤儿院（五）\",\"kind\":\"main\",\"volume\":5,\"start\":2590,\"end\":2593,\"summary\":\"雨晴看清云独自玩过家家，想起自己童年的孤独；洞外莫空则劝清雾考虑由两家分别收养。他表示愿领养妹妹，却拒绝同收二人，称他们一起的未来不好。雨晴不愿为了自己的母亲愿望拆散兄妹，坚持孩子也可选择留在一起，莫空表示尊重她，决定暂未达成。\",\"turn\":\"雨晴明确把兄妹意愿置于自身愿望之前；莫空所说不良未来没有具体揭示。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"莫空\",\"林清雾\",\"莫语默\",\"张思凡\",\"董花火\"],\"objects\":[\"收养资料\"],\"places\":[\"山洞\",\"金盈儿童福利院办公室\"]},{\"key\":\"c656\",\"id\":656,\"title\":\"孤儿院（六）\",\"kind\":\"main\",\"volume\":5,\"start\":2594,\"end\":2597,\"summary\":\"清雾同意若妹妹也获家庭便接受领养，清云仍不舍。雨晴感觉一小段时间像被剪去，随后妹妹已含泪同意，具体说服过程未写清。三天后手续批准，张思凡与董花火收养哥哥，莫空与雨晴收养妹妹；旧友互祝新生活。清云赴台后改名莫语默，逐渐适应家庭，仍须面对与哥哥分离的伤心。\",\"turn\":\"收养完成，两家以双胞胎保持联系；过程中的记忆空白保留莫空能力悬念。\",\"time\":\"手续审批三天后\",\"people\":[\"苏雨晴\",\"莫空\",\"张思凡\",\"董花火\",\"林清雾\",\"莫语默\",\"福利院老师\"],\"objects\":[\"收养文件\",\"通关证明\",\"新户籍\"],\"places\":[\"金盈儿童福利院\",\"赴台航程\",\"台湾\"]},{\"key\":\"c657\",\"id\":657,\"title\":\"莫语默，我们的女儿\",\"kind\":\"main\",\"volume\":5,\"start\":2598,\"end\":2601,\"summary\":\"苏雨晴与莫空带领养女儿莫语默回到台湾，才知道资料与收养安排早获父母配合。苏榕槐邀请莫空从公司基层做起，并托付女儿的幸福。语默享受新家的零食仍惦记哥哥，雨晴陪她游玩、洗浴并承诺不会抛弃她，逐渐学会母亲的耐心。\",\"turn\":\"收养关系正式融入家庭，雨晴从被照顾者开始学习照顾孩子。\",\"time\":\"\",\"people\":[\"苏雨晴\",\"莫空\",\"莫语默\",\"苏榕槐\",\"苏雨晴的母亲\",\"苏冬凌\",\"三位表哥\"],\"objects\":[\"零食\",\"收养资料\"],\"places\":[\"台湾\",\"苏家村住宅\"]},{\"key\":\"c658\",\"id\":658,\"title\":\"一年又一年\",\"kind\":\"main\",\"volume\":5,\"start\":2602,\"end\":2605,\"summary\":\"领养后三年过去，莫语默读小学一年级，雨晴也在花莲高中迎来毕业。她珍惜来之不易的校园平静，为与杨灵等同学分别而落泪，谢绝聚会后去接女儿。莫空已深入接手苏父公司事务，一家虽未举行婚礼，已形成稳定的夫妻与亲子生活。\",\"turn\":\"高中阶段结束，女儿成长与事业发展将故事推向婚姻。\",\"time\":\"领养后三年；2011年高中毕业前后\",\"people\":[\"苏雨晴\",\"莫语默\",\"莫空\",\"杨灵\",\"苏榕槐\"],\"objects\":[\"毕业书包\"],\"places\":[\"花莲高中\",\"莫语默的小学\"]},{\"key\":\"c659\",\"id\":659,\"title\":\"在哪里举办婚礼\",\"kind\":\"main\",\"volume\":5,\"start\":2606,\"end\":2609,\"summary\":\"高中毕业的雨晴带语默到父亲公司探望莫空。苏榕槐任董事长，莫空已任总经理，公司经营继续扩张。雨晴因害怕再次离别暂不愿读大学；莫空询问婚礼愿望，她选择苏家村海边的西式婚礼。毕业礼物与一家三口骑摩托回家的日常，让她感到愿望正逐一实现。\",\"turn\":\"婚礼地点与形式确定，莫空开始筹办。\",\"time\":\"2011年高中毕业后\",\"people\":[\"苏雨晴\",\"莫空\",\"莫语默\",\"苏榕槐\"],\"objects\":[\"智能手机\",\"化妆品\",\"角色服装\",\"小樱魔术卡\",\"摩托车\"],\"places\":[\"花莲公司\",\"苏家村海边\"]},{\"key\":\"c660\",\"id\":660,\"title\":\"被解开了的梦\",\"kind\":\"main\",\"volume\":5,\"start\":2610,\"end\":2613,\"summary\":\"筹婚期间雨晴再度梦见旧公园，却找不到秋千上的少年。她意识到阻隔自由的是自己的执念，转身走出空气墙，在夜市遇到少年及林夕晨。雨晴清楚夕晨现实中已经死亡，却仍请求她以后在梦中陪伴，随后讲述这几年的生活；梦境成为释怀与悼念的空间。\",\"turn\":\"公园梦的束缚解除；夕晨出现明确属于梦境，不能记作复活。\",\"time\":\"2011年婚礼前\",\"people\":[\"苏雨晴\",\"梦中少年\",\"林夕晨\"],\"objects\":[\"秋千\",\"空气墙\",\"羊肉串\"],\"places\":[\"梦中公园\",\"梦中夜市\"]},{\"key\":\"c661\",\"id\":661,\"title\":\"婚礼（上）\",\"kind\":\"main\",\"volume\":5,\"start\":2614,\"end\":2616,\"summary\":\"2011年7月23日，莫空在苏家村海边举办从白天延续至夜晚的婚礼，邀请村民与亲友。雨晴花整天试婚纱和化妆，望着镜中自己想到夕晨，感慨旧愿实现。她的父母担任伴郎伴娘，苏冬凌和莫语默当花童，新娘在花车里期待夜幕与仪式。\",\"turn\":\"婚礼正式布置完成，父母以公开参与肯定女儿的身份与选择。\",\"time\":\"2011年7月23日\",\"people\":[\"苏雨晴\",\"莫空\",\"苏雨晴父母\",\"苏冬凌\",\"莫语默\",\"化妆师\",\"村民\"],\"objects\":[\"婚纱\",\"花车\",\"手机\"],\"places\":[\"苏家村海滩\",\"苏家住宅\"]},{\"key\":\"c662\",\"id\":662,\"title\":\"婚礼（下）\",\"kind\":\"main\",\"volume\":5,\"start\":2617,\"end\":2620,\"summary\":\"衰老的曲奇钻进花车陪伴新娘，它已在台湾与白猫繁衍后代。雨晴在母亲搀扶下走入会场，与莫空当众互诉承诺。神父主持誓词，父母声明女儿自愿出嫁，两个孩子送上刻有双方名字的戒指。雨晴克服当众亲吻的羞怯，完成海边婚礼。\",\"turn\":\"莫空与雨晴正式结为夫妻；曲奇老去预示时间流逝。\",\"time\":\"2011年7月23日晚\",\"people\":[\"苏雨晴\",\"莫空\",\"曲奇\",\"白猫\",\"莫语默\",\"苏冬凌\",\"苏雨晴父母\",\"神父\"],\"objects\":[\"婚戒\",\"圣经\",\"婚纱\"],\"places\":[\"苏家村海滩\"]},{\"key\":\"c663\",\"id\":663,\"title\":\"这就是爱情\",\"kind\":\"main\",\"volume\":5,\"start\":2621,\"end\":2624,\"summary\":\"海边婚礼进入敬酒与游戏，杨灵等同学向雨晴祝福，孩子们争取奖品。雨晴因兴奋饮酒后不适，莫空将她带回半年前建成的新居。二人在婚后亲密相处中确认共同生活的归属，次日被要出去玩的语默叫醒；甜蜜同时夹带雨晴身体状况不佳的提示。\",\"turn\":\"夫妻生活开启，叙述继续铺垫雨晴的健康隐患。\",\"time\":\"2011年7月23日晚至24日上午\",\"people\":[\"苏雨晴\",\"莫空\",\"莫语默\",\"苏冬凌\",\"杨灵\",\"苏雨晴父母\"],\"objects\":[\"婚纱\",\"奖品\",\"新婚大床\"],\"places\":[\"苏家村海滩\",\"莫空新建别墅\"]},{\"key\":\"c664\",\"id\":664,\"title\":\"一家三口\",\"kind\":\"main\",\"volume\":5,\"start\":2625,\"end\":2628,\"summary\":\"新婚次日亲友到新居祝贺，三位表哥插科打诨。莫空和雨晴带语默去游乐园，以亲子出游代替两人蜜月。语默活泼大胆，雨晴更有母亲的细心，却再次出现腹部不适。晚上一家依偎看电视、逗曲奇，并约定做竹筒饭，平常生活成为幸福的主要画面。\",\"turn\":\"家庭日常达到圆满，身体疼痛成为终局前的伏笔。\",\"time\":\"2011年婚礼次日\",\"people\":[\"苏雨晴\",\"莫空\",\"莫语默\",\"曲奇\",\"苏雨晴父母\",\"苏冬凌\",\"三位表哥\"],\"objects\":[\"竹筒饭\",\"手帕\",\"冰淇淋\"],\"places\":[\"新婚别墅\",\"游乐园\"]},{\"key\":\"c665\",\"id\":665,\"title\":\"来生缘（大结局）\",\"kind\":\"main\",\"volume\":5,\"start\":2629,\"end\":2632,\"summary\":\"婚后雨晴反复疼痛并重病住院，小说写她同时面临肾衰竭、先天性心脏病与白血病。父母准备捐肾，莫空参与配型及救治，但手术未能挽救她。2016年4月4日家人将她安葬在海边山头；曲奇守墓拒食，三天后去世并葬在旁边。莫空承诺继续照顾语默，正文以存者承受失去收束。\",\"turn\":\"正文悲剧终局：雨晴死亡，曲奇随后死亡，莫空与养女继续生活。\",\"time\":\"2016年春病逝；正文明确4月4日安葬\",\"people\":[\"苏雨晴\",\"莫空\",\"莫语默\",\"曲奇\",\"苏雨晴父母\",\"苏冬凌\",\"医生\"],\"objects\":[\"墓碑\",\"骨灰\"],\"places\":[\"医院\",\"海边山头墓地\"]},{\"key\":\"x001\",\"id\":1,\"title\":\"如果有来世，我想做个女孩子\",\"kind\":\"side\",\"volume\":null,\"start\":2634,\"end\":2637,\"summary\":\"死后外传中，雨晴的灵魂目睹家人悲恸，在将要消散时被九尾神太阴借占卜卡牌召见。太阴不能使她或夕晨复活，却答应让她来世成为女孩子。雨晴转生到2010年的龙凤胎家庭，获名叶洛夜，兄弟名秋叶，随后前世记忆全部消失。这是超自然外传续接，不能覆盖正文的死亡事实。\",\"turn\":\"外传以失去前世记忆的转生回收来世愿望，时间倒退属于超自然设定。\",\"time\":\"正文死亡之后的外传；转生年份2010\",\"people\":[\"苏雨晴\",\"太阴\",\"叶洛夜\",\"秋叶\",\"叶洛夜父母\",\"莫空\",\"林夕晨\"],\"objects\":[\"占卜卡牌\"],\"places\":[\"医院\",\"灵魂空间\",\"转生医院\"]},{\"key\":\"x002\",\"id\":2,\"title\":\"方莜莜和安念的故事（一）\",\"kind\":\"fang\",\"volume\":null,\"start\":2639,\"end\":2642,\"summary\":\"方莜莜过年回父家，父亲仍难接受她的身份，却已有忧虑与牵挂，她决定不再断绝联系。安念到车站接她，两人互相体谅。初八奶茶咖啡店复工，朋友橘子代班；他也是二人在海宁定居时结识的房东，熟悉彼此秘密后成了好友。新一年的日常由恋人陪伴、旧家庭和解的微小希望展开。\",\"turn\":\"父女关系出现松动，安念与橘子成为她稳定的新生活支持。\",\"time\":\"大年初八；海宁定居一年多后\",\"people\":[\"方莜莜\",\"安念\",\"方莜莜父亲\",\"阿姨\",\"橘子\"],\"objects\":[\"白色行李箱\",\"小米手机\"],\"places\":[\"海宁\",\"车站\",\"奶茶咖啡店\"]},{\"key\":\"x003\",\"id\":3,\"title\":\"方莜莜和安念的故事（二）\",\"kind\":\"fang\",\"volume\":null,\"start\":2643,\"end\":2646,\"summary\":\"橘子本名田桔，是跨性别男性，与方莜莜坦率相处，嘴上挖苦而相互亲近。他早前讲到大学往事便被打断，留下未完的话题。三人到熟悉的吴记餐馆庆祝开工，吴哥夫妇经营小店，妻子新研发菜色。橘子与安念比拼喝啤酒，方莜莜做裁判，最终橘子胜出，大家举杯祝愿生活更好。\",\"turn\":\"朋友聚餐巩固陪伴关系，橘子的往事即将展开。\",\"time\":\"接x002当晚\",\"people\":[\"方莜莜\",\"安念\",\"橘子\",\"吴哥\",\"吴哥妻子\",\"吴哥女儿\"],\"objects\":[\"啤酒\",\"菜单\"],\"places\":[\"吴记餐馆\"]},{\"key\":\"x004\",\"id\":4,\"title\":\"方莜莜和安念的故事（三）\",\"kind\":\"fang\",\"volume\":null,\"start\":2647,\"end\":2650,\"summary\":\"聚餐中橘子续述大学经历：大三时他尚未开始身体转变，一度以为自己是喜欢女生的女生，默默关注大二新闻系的姜琳。姜琳在图书馆与男友分手遭拉扯，橘子主动解围，她以旧笔友的说法配合脱身。二人由此成为亲近书友，姜琳重获笑容；橘子暗恋渐深，却担心表白后连朋友也做不成。\",\"turn\":\"仗义解围建立亲密友谊，暗恋与身份疑惑仍未解决。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"田桔大学大三时的回忆\",\"people\":[\"橘子\",\"姜琳\",\"姜琳前男友\",\"方莜莜\",\"安念\"],\"objects\":[\"书籍\"],\"places\":[\"大学图书馆\",\"吴记餐馆\"]},{\"key\":\"x005\",\"id\":5,\"title\":\"方莜莜和安念的故事（四）\",\"kind\":\"fang\",\"volume\":null,\"start\":2651,\"end\":2654,\"summary\":\"橘子借协助新闻系作业，向姜琳介绍女性间爱情题材，试探她能否接受自己的感情。姜琳神情异常，却决定用相关主题写访谈，随即请假回家查问往事。当晚她在中心公园哭着打来电话，橘子顾不上吃饭换鞋便赶去，担忧和行动显露已难隐藏的爱意。\",\"turn\":\"作品话题触发姜琳家庭秘密，橘子赶到公园陪伴。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"大学回忆\",\"people\":[\"橘子\",\"姜琳\",\"田桔父母\"],\"objects\":[\"《圣母在上》\",\"手机\",\"米色风衣\"],\"places\":[\"大学图书馆\",\"中心公园\"]},{\"key\":\"x006\",\"id\":6,\"title\":\"方莜莜和安念的故事（五）\",\"kind\":\"fang\",\"volume\":null,\"start\":2655,\"end\":2657,\"summary\":\"姜琳讲父母为生下她而形式结婚，母亲与女性恋人分离七年后离家。她曾把被遗弃感化为对女同性恋的怨恨；这次追问父亲、进入保存母亲遗物的阁楼，通过日记和画作理解母亲的压抑，转而委屈于整段家庭隐瞒。橘子坦承无法立即感同身受，却愿逐步理解她，她依偎在其怀里得到安慰。\",\"turn\":\"家庭真相消解群体偏见，二人情感更加亲近；本篇排在事件前段之后却补叙结果。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"大学回忆；母亲陪伴至七岁\",\"people\":[\"橘子\",\"姜琳\",\"姜琳父亲\",\"姜琳母亲\",\"姜琳母亲女友\"],\"objects\":[\"阁楼钥匙\",\"父亲日记\",\"母亲日记\",\"母亲画作\"],\"places\":[\"中心公园\",\"姜琳家阁楼\"]},{\"key\":\"x007\",\"id\":7,\"title\":\"方莜莜和安念的故事（六）\",\"kind\":\"fang\",\"volume\":null,\"start\":2658,\"end\":2660,\"summary\":\"章节回到公园会面初段，橘子安抚姜琳，表示关心即使有所求也不必等于恶意，不应把对个人的怨恨扩大到群体。姜琳回述母亲与女友相恋，父亲是深爱母亲的青梅竹马；一次同学聚会醉酒后父母发生关系，母亲意外怀孕，三人开始商议未来。这段在原编排中补足前章已经讲出的家庭结局。\",\"turn\":\"交代形式婚姻之前的纠葛；怀孕是否被设计仅属姜琳猜疑。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"大学回忆内嵌父母往事\",\"people\":[\"橘子\",\"姜琳\",\"姜琳父亲\",\"姜琳母亲\",\"姜琳母亲女友\"],\"objects\":[\"长椅\"],\"places\":[\"中心公园\",\"大学聚会\"]},{\"key\":\"x008\",\"id\":8,\"title\":\"方莜莜和安念的故事（七）\",\"kind\":\"fang\",\"volume\":null,\"start\":2661,\"end\":2664,\"summary\":\"公园分别时橘子没敢让姜琳听见表白，回家又遭母亲责骂。母亲连带攻击父亲使他动怒，父亲居中劝解后到房中关心，支持他帮助姜琳。往事显示母亲长期苛责与打骂，父亲后来减少外出、持续谈心，帮助他从自卑中恢复；对父亲的留恋使他始终未彻底离家。\",\"turn\":\"父亲的温和支持与母亲的控制构成橘子家庭矛盾。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"接公园长谈当夜\",\"people\":[\"橘子\",\"姜琳\",\"田桔母亲\",\"田桔父亲\"],\"objects\":[\"拖鞋\",\"风衣\"],\"places\":[\"中心公园\",\"田桔家\"]},{\"key\":\"x009\",\"id\":9,\"title\":\"方莜莜和安念的故事（八）\",\"kind\":\"fang\",\"volume\":null,\"start\":2665,\"end\":2668,\"summary\":\"橘子向姜琳说明自己对陌生人疏离、只珍惜少数朋友，二人承诺重视彼此。为完成女性爱情主题访谈，他们从学校转往市图书馆，筛选十余本书，橘子提炼材料、姜琳写草稿，配合整日完成初稿。分别时他仍无法表白，在想求得明确答案与维持当下陪伴之间犹疑。\",\"turn\":\"共同创作深化默契，橘子开始正视是否应说出感情。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"大学回忆\",\"people\":[\"橘子\",\"姜琳\"],\"objects\":[\"《凡尔赛玫瑰》\",\"笔记本电脑\",\"访谈草稿\"],\"places\":[\"大学图书馆\",\"市图书馆\"]},{\"key\":\"x010\",\"id\":10,\"title\":\"方莜莜和安念的故事（九）\",\"kind\":\"fang\",\"volume\":null,\"start\":2669,\"end\":2672,\"summary\":\"经过约一个月挣扎，橘子决定在国庆约会中表白。姜琳的访谈已完成交给教授，两人选择游乐园度假。姜琳害怕鬼屋却不愿承认，橘子半逗弄半照顾，拉她进入，借讲解布景与气氛让她放松，再提起油灯走进古楼。近距离依赖为即将说破的感情蓄势。\",\"turn\":\"橘子决定求得答案，但表白尚未发生。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"十一国庆\",\"people\":[\"橘子\",\"姜琳\",\"新闻系教授\",\"鬼屋工作人员\"],\"objects\":[\"访谈稿\",\"鬼屋油灯\",\"门票\"],\"places\":[\"游乐园\",\"鬼屋古楼\"]},{\"key\":\"x011\",\"id\":11,\"title\":\"方莜莜和安念的故事（十）\",\"kind\":\"fang\",\"volume\":null,\"start\":2673,\"end\":2675,\"summary\":\"鬼屋里姜琳逞强探路又被草丛动静吓退，橘子检查发现道具蛇，安抚她后继续前行。堂屋供着恐怖女像，左右门上锁，两人推断需找钥匙。搜遍庭院无果后返回堂屋，突然扑来的道具骷髅被橘子踢开；解谜和惊吓让平日自信的他也开始紧张。\",\"turn\":\"看似普通鬼屋游玩逐渐埋入异常空间的入口。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"国庆约会\",\"people\":[\"橘子\",\"姜琳\"],\"objects\":[\"道具蛇\",\"道具骷髅\",\"红灯笼\",\"钥匙\"],\"places\":[\"游乐园鬼屋\"]},{\"key\":\"x012\",\"id\":12,\"title\":\"方莜莜和安念的故事（十一）\",\"kind\":\"fang\",\"volume\":null,\"start\":2676,\"end\":2678,\"summary\":\"橘子用寻找钥匙的比赛激起姜琳好胜心，使她暂缓退出鬼屋的决定。姜琳意外打开地道，不肯留在上面等候，坚持与他同行。二人深入黑暗长廊，谈起访谈获得教授表扬、还获邀合作研究，以聊天驱散恐惧。她愿共担未知使橘子一度觉得，只要这样相伴便足够。\",\"turn\":\"姜琳从受保护者转向共同冒险，地道性质仍不明确。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"国庆约会\",\"people\":[\"橘子\",\"姜琳\",\"新闻系教授\"],\"objects\":[\"红灯笼\",\"手机手电筒\",\"访谈录\"],\"places\":[\"鬼屋堂屋\",\"地下通道\"]},{\"key\":\"x013\",\"id\":13,\"title\":\"方莜莜和安念的故事（十二）\",\"kind\":\"fang\",\"volume\":null,\"start\":2679,\"end\":2682,\"summary\":\"两人在地道尽头看见刻着洪水与人群的石门，仍以为是游乐设施，商量后合力推开。地下祭坛与黑雾让他们意识到异常，急忙逃走；橘子看见阴影怪物追来，却找不到原入口。他抓住岔道密室中卷纸提示，取得钥匙并开启转墙，先推姜琳出去，再关上墙壁，暂时阻隔追逐。\",\"turn\":\"娱乐探险进入外传超自然情节，逃脱尚未真正完成。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"国庆约会\",\"people\":[\"橘子\",\"姜琳\"],\"objects\":[\"洪水刻纹石门\",\"祭坛\",\"黑雾\",\"木盒\",\"钥匙\",\"宣纸机关说明\"],\"places\":[\"地下祭坛\",\"机关密室\"]},{\"key\":\"x014\",\"id\":14,\"title\":\"方莜莜和安念的故事（十三）\",\"kind\":\"fang\",\"volume\":null,\"start\":2683,\"end\":2685,\"summary\":\"姜琳提醒黑雾可能穿墙，二人继续逃回鬼屋，却不知一缕黑雾已附上她；旁白明确写她因此进入易遇灵异的状态。橘子随后表白，她要求时间考虑，数日后却因噩梦与持续低语求助。医院未查出明显问题，橘子又寻访宗教与民间人士，试图兑现保护她的承诺。\",\"turn\":\"告白未获答复，外传设定中的侵蚀转成姜琳的持续危机。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"国庆后数日\",\"people\":[\"橘子\",\"姜琳\",\"医生\",\"道士\",\"和尚\",\"老中医\"],\"objects\":[\"附身黑雾\",\"检查报告\"],\"places\":[\"鬼屋\",\"图书馆\",\"市医院\",\"道观\",\"寺庙\",\"中医馆\"]},{\"key\":\"x015\",\"id\":15,\"title\":\"方莜莜和安念的故事（十四）\",\"kind\":\"fang\",\"volume\":null,\"start\":2686,\"end\":2688,\"summary\":\"姜琳逐渐无法上学、失去正常交流，橘子反复研读相关书籍并陪伴照料，仍无力改善。他带她到静虚宫，少年道士引见早已等候的老道长。老者辨认情况与游乐场有关，要求回到祭坛，得知封印已被打开后决定派徒弟同行；橘子虽不安仍只能追寻这条线索。\",\"turn\":\"回到危险源头成为唯一被提出的解决方案，老者目的未明。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"姜琳病况加重后\",\"people\":[\"橘子\",\"姜琳\",\"姜琳父亲\",\"静虚宫老道长\",\"张诚\"],\"objects\":[\"古籍\",\"空神龛\",\"蒲团\"],\"places\":[\"静虚宫\",\"后山矮屋\",\"姜琳家\"]},{\"key\":\"x016\",\"id\":16,\"title\":\"方莜莜和安念的故事（十五）\",\"kind\":\"fang\",\"volume\":null,\"start\":2689,\"end\":2691,\"summary\":\"少年道士张诚是老道长收养的弃婴，他与橘子谈恨与放下后带二人重进鬼屋。原文略去地下经过，只写地面塌陷、仅橘子逃出；他重创失语住院，父亲长期照顾，母亲只来一次便离开。回到聚餐现在，橘子主动截断故事，三人以酒陪伴彼此悲伤，醉后获吴哥夫妇收留。\",\"turn\":\"姜琳和张诚留在塌陷处，详情未交代；橘子以玩笑掩饰创伤。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"大学往事；叙事返回年初八夜至次日上午\",\"people\":[\"橘子\",\"姜琳\",\"张诚\",\"静虚宫老道长\",\"田桔父亲\",\"田桔母亲\",\"警察\",\"护士\",\"方莜莜\",\"安念\",\"吴哥\",\"吴哥妻子\"],\"objects\":[\"八卦罗盘\",\"白布包\",\"啤酒\",\"蜂蜜水\"],\"places\":[\"鬼屋塌陷深坑\",\"医院\",\"吴记餐馆\"]},{\"key\":\"x017\",\"id\":17,\"title\":\"方莜莜和安念的故事（十六）\",\"kind\":\"fang\",\"volume\":null,\"start\":2692,\"end\":2694,\"summary\":\"醒来后橘子把方莜莜搂在怀里，请她叫自己橘子姐，再述姜琳坠入深渊前自称一直玩弄他、推开他独自坠落。住院时他曾困于幻象、险些从医院高处坠下，被警察和父亲救回，此后现实与梦难分。方莜莜倾听却担心被当作替代，安念进门把沉重倾诉打断成尴尬玩闹。\",\"turn\":\"姜琳结局由橘子口述补足，创伤和现实感动摇仍持续。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"次日上午；内嵌大学住院回忆\",\"people\":[\"橘子\",\"方莜莜\",\"安念\",\"姜琳\",\"田桔父亲\",\"警察\",\"护士\"],\"objects\":[\"枕头\",\"被子\"],\"places\":[\"吴记客房\",\"医院天台\"]},{\"key\":\"x018\",\"id\":18,\"title\":\"方莜莜和安念的故事（十七）\",\"kind\":\"fang\",\"volume\":null,\"start\":2695,\"end\":2697,\"summary\":\"橘子继续逗弄方莜莜，称只把她当妹妹，要她以后一直叫橘子姐。方莜莜担忧他笑中带泪的状态，却不愿当众揭开私事；安念以最爱的糖醋排骨转移其注意，结束失控般笑声。午饭前两人又争用浴室，方莜莜先一步锁门，小小反击也呈现她逐渐熟悉的亲密与边界。\",\"turn\":\"认作姐妹的称呼确定，但方莜莜意识到朋友情绪需认真对待。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"次日上午至午饭前\",\"people\":[\"橘子\",\"方莜莜\",\"安念\",\"吴哥\",\"吴哥妻子\"],\"objects\":[\"糖醋排骨\",\"枕头\"],\"places\":[\"吴记客房\",\"浴室\"]},{\"key\":\"x019\",\"id\":19,\"title\":\"方莜莜和安念的故事（十八）\",\"kind\":\"fang\",\"volume\":null,\"start\":2698,\"end\":2700,\"summary\":\"方莜莜洗漱后主动整理借住客房，饭桌上与橘子争抢最后一块排骨，三人与吴哥夫妇亲近告别。安念留下看店，橘子陪她提行李回明佳小区。重见合住一年多的房间，方莜莜反而想起父家不再属于自己的感觉，欢乐日常之后流露缺乏归属的悲伤。\",\"turn\":\"家与寄居的感受促使方莜莜向橘子谈自己的家庭。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"年初九午后\",\"people\":[\"方莜莜\",\"安念\",\"橘子\",\"吴哥\",\"吴哥妻子\"],\"objects\":[\"行李箱\",\"糖醋排骨\",\"动漫海报\"],\"places\":[\"吴记餐馆\",\"奶茶店\",\"明佳小区606室\"]},{\"key\":\"x020\",\"id\":20,\"title\":\"方莜莜和安念的故事（十九）\",\"kind\":\"fang\",\"volume\":null,\"start\":2701,\"end\":2703,\"summary\":\"阳台水仙终于开花，方莜莜谈花语与思亲，向橘子讲父亲再婚和返乡失落。橘子偏向理解父亲，肯定她仍坚持看望的选择，又拿自己的失去作安慰。方莜莜不愿他揭伤疤强笑，两人互相开导后以玩闹和解，再出门帮安念经营奶茶店。\",\"turn\":\"两人的互相安慰深化知己关系，也显出橘子悲伤并未彻底消散。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"年初九下午\",\"people\":[\"方莜莜\",\"橘子\",\"安念\",\"方莜莜父亲\",\"方莜莜继母\"],\"objects\":[\"水仙花\",\"假百合花\",\"手机\"],\"places\":[\"明佳小区606室\",\"奶茶店\"]},{\"key\":\"x021\",\"id\":21,\"title\":\"方莜莜和安念的故事（二十）\",\"kind\":\"fang\",\"volume\":null,\"start\":2704,\"end\":2707,\"summary\":\"奶茶店忙碌到晚饭，安念支开橘子后与方莜莜讨论其经历。两人在文内网上新闻查到游乐园塌陷确有其事，却无法证实鬼怪。方莜莜担心橘子把自己当作姜琳，又发现其讲述存在不协调，开始怀疑故事是否混入长期精神困扰；这些此时都只是两人的推测。\",\"turn\":\"朋友转而调查叙述可靠性，超自然故事不能直接等同外层事实。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"年初九下午至晚饭\",\"people\":[\"方莜莜\",\"安念\",\"橘子\"],\"objects\":[\"工作服\",\"手机\",\"游乐园塌陷新闻\"],\"places\":[\"奶茶店\"]},{\"key\":\"x022\",\"id\":22,\"title\":\"方莜莜和安念的故事（二十一）\",\"kind\":\"fang\",\"volume\":null,\"start\":2708,\"end\":2711,\"summary\":\"方莜莜发现自己与安念对橘子过往讲述的记忆不一致，医院时期尤其空缺。二人确认目的是帮助朋友，再查报道遇难名单：有张诚却没有姜琳。方莜莜由此提出姜琳未死、未在场或根本不存在等可能，并思考神怪真实与叙述虚构两条解释，尚未得到结论。\",\"turn\":\"张诚在文内报道确认遇难，姜琳身份与命运悬念扩大。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"年初九晚饭前\",\"people\":[\"方莜莜\",\"安念\",\"橘子\",\"姜琳\",\"张诚\"],\"objects\":[\"手机\",\"新闻遇难名单\"],\"places\":[\"奶茶店\"]},{\"key\":\"x023\",\"id\":23,\"title\":\"方莜莜和安念的故事（二十二）\",\"kind\":\"fang\",\"volume\":null,\"start\":2712,\"end\":2714,\"summary\":\"方莜莜想帮助橘子从自编梦境走出，偶然翻到他留下的黑皮书《入梦》，其中有自我催眠内容。二人猜测其创伤、记忆与故事间联系，列出发病时间、姜琳参与程度、现状及替身感等疑问；橘子带餐回来先收起书，似已察觉他们正在查问。\",\"turn\":\"黑皮书成为梦境机制线索，双方试探渐逼近真相。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"年初九晚饭时\",\"people\":[\"方莜莜\",\"安念\",\"橘子\",\"姜琳\"],\"objects\":[\"《入梦》\",\"糖醋排骨餐盒\"],\"places\":[\"奶茶店\"]},{\"key\":\"x024\",\"id\":24,\"title\":\"方莜莜和安念的故事（二十三）\",\"kind\":\"fang\",\"volume\":null,\"start\":2715,\"end\":2717,\"summary\":\"三人分享橘子带回的糖醋排骨，亲密晚餐缓和了关于黑皮书的暗中紧张。打烊前，一位脸色苍白的西装客持黑伞买加奶加糖的抹茶饮品，付百元后离去。方莜莜亲眼看见他撑伞融入夜色消失，平静店铺日常被新的异常打断。\",\"turn\":\"外层人物也目睹异常，为全局梦境真相埋线。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"年初九夜约十点\",\"people\":[\"方莜莜\",\"安念\",\"橘子\",\"黑伞西装客\"],\"objects\":[\"糖醋排骨\",\"抹茶奶茶\",\"百元钞票\",\"黑伞\"],\"places\":[\"奶茶店\",\"夜街\"]},{\"key\":\"x025\",\"id\":25,\"title\":\"方莜莜和安念的故事（二十四）\",\"kind\":\"fang\",\"volume\":null,\"start\":2718,\"end\":2720,\"summary\":\"方莜莜坚持黑伞客突然消失，安念与橘子以暗巷和路灯解释，三人回家后仍心有余悸。浴室外橘子再次过度亲昵，她明确以身份与尊重为由拒绝。递睡衣时他直言知道两人看过《入梦》，约她夜里单独来房间获知真相；她告知安念，期待终于能帮他走出过去。\",\"turn\":\"方莜莜维护亲密边界，接受揭晓橘子往事的约定。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"年初九夜\",\"people\":[\"方莜莜\",\"安念\",\"橘子\",\"黑伞西装客\"],\"objects\":[\"黑伞\",\"小熊睡衣\",\"《入梦》\",\"吹风机\"],\"places\":[\"夜街\",\"明佳小区606室浴室\"]},{\"key\":\"x026\",\"id\":26,\"title\":\"方莜莜和安念的故事（二十五）\",\"kind\":\"fang\",\"volume\":null,\"start\":2721,\"end\":2723,\"summary\":\"方莜莜不接受成为姜琳替代品，想在避免伤害朋友的同时弄清真相。她查《入梦》发现资料稀少、入梦篇受文内评论质疑。到橘子房间后，她说出全部疑点，对方反问是否相信鬼神；她以为否定神怪能帮朋友，于是回答不信，紧张对谈正式开始。\",\"turn\":\"试图治愈朋友的好意面临以猜测代替事实的问题。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"年初九深夜\",\"people\":[\"方莜莜\",\"安念\",\"橘子\"],\"objects\":[\"《入梦》\",\"拿铁马克杯\",\"薰衣草\",\"电脑\"],\"places\":[\"明佳小区606室\"]},{\"key\":\"x027\",\"id\":27,\"title\":\"方莜莜和安念的故事（二十六）\",\"kind\":\"fang\",\"volume\":null,\"start\":2724,\"end\":2726,\"summary\":\"橘子坚持姜琳在祭坛消失，方莜莜以报道中没有遗迹、张诚并非道士等矛盾反驳，并指出自我催眠与过往困扰可能改写记忆。她明确说自己不是姜琳，也不会成为替代。橘子最终承认曾把希望当回忆，表示不再相信那套神怪解释，开始面对伤痛。\",\"turn\":\"祭坛叙述被拆解，朋友的真实边界迫使橘子放弃妄想。 此时涉及橘子的回忆后来在x028证实含神怪与感情改写，非可靠往事。\",\"time\":\"年初九深夜\",\"people\":[\"方莜莜\",\"橘子\",\"姜琳\",\"张诚\"],\"objects\":[\"《入梦》\",\"新闻报道\",\"薰衣草\"],\"places\":[\"橘子房间\"]},{\"key\":\"x028\",\"id\":28,\"title\":\"方莜莜和安念的故事（二十七）\",\"kind\":\"fang\",\"volume\":null,\"start\":2727,\"end\":2729,\"summary\":\"长谈揭示橘子自幼有妄想困扰：姜琳只是学妹，在公园明确拒绝感情；张诚是追求他的学长，邀他去游乐园，姜琳因病未去。塌陷时张诚救他而死，住院后他得知姜琳转学返乡，受刺激改写往事。现今治疗尚未根治，近期停下抑制而把莜莜当替代；说开后两人同房休息，关系重回现实。\",\"turn\":\"姜琳活着转学，张诚为救橘子遇难；此前神怪经历不能当外层事实。\",\"time\":\"当夜至凌晨一两点；真实往事回收\",\"people\":[\"方莜莜\",\"橘子\",\"姜琳\",\"张诚\",\"田桔父亲\",\"田桔母亲\",\"姜琳父亲\",\"医生\"],\"objects\":[\"手机\",\"治疗药物\",\"《入梦》\"],\"places\":[\"大学\",\"中心公园\",\"游乐园\",\"医院\",\"橘子房间\"]},{\"key\":\"x029\",\"id\":29,\"title\":\"方莜莜和安念的故事（二十八）\",\"kind\":\"fang\",\"volume\":null,\"start\":2730,\"end\":2732,\"summary\":\"次晨方莜莜对橘子心生不舍，却知道自己选择安念，严肃要求不再越过亲密边界。橘子答应后仍动手逗弄，安念敲门才让她脱身。她告知安念朋友问题已经谈开，接着得知他母亲催其返乡相亲，恋人之间一直回避的家庭矛盾终于被迫出现。\",\"turn\":\"安念的相亲通知将私人感情推到家庭选择面前。\",\"time\":\"年初十上午\",\"people\":[\"方莜莜\",\"橘子\",\"安念\",\"安念母亲\"],\"objects\":[\"闹钟\",\"手机\"],\"places\":[\"明佳小区606室\"]},{\"key\":\"x030\",\"id\":30,\"title\":\"方莜莜和安念的故事（二十九）\",\"kind\":\"fang\",\"volume\":null,\"start\":2733,\"end\":2735,\"summary\":\"安念承诺不会负莜莜，却无法直接拒绝父母；她重复若不被需要便自行离开的旧承诺，以体谅压住不安。他邀请她同行，说明父母知其身份却不知恋爱同居，二人继续隐瞒。橘子担心结局仍替他们订票、答应看店，叮嘱安念照顾她，也让她受委屈就联系自己。\",\"turn\":\"莜莜跟随恋人返乡，橘子的援手承诺为终局铺垫。\",\"time\":\"正月十五前\",\"people\":[\"方莜莜\",\"安念\",\"橘子\",\"安念父母\"],\"objects\":[\"行李\",\"火车票\"],\"places\":[\"明佳小区\",\"火车站\"]},{\"key\":\"x031\",\"id\":31,\"title\":\"方莜莜和安念的故事（三十）\",\"kind\":\"fang\",\"volume\":null,\"start\":2736,\"end\":2739,\"summary\":\"候车时莜莜联系认作哥哥的杨豪伟，回忆他理解跨性别身份、持续关怀却理性划清爱情边界。杨豪伟到站接二人，安念因旧有好感而有芥蒂，他也担心安念不能给妹妹幸福，仍保持礼貌。交谈得知他二十八岁、已有意中人，准备介绍给妹妹认识。\",\"turn\":\"杨豪伟作为亲友支持者回归，三人的感情边界并未改变。\",\"time\":\"返乡日中午\",\"people\":[\"方莜莜\",\"安念\",\"杨豪伟\"],\"objects\":[\"手机\",\"桑塔纳\",\"火车票\"],\"places\":[\"火车站\",\"杨豪伟车内\"]},{\"key\":\"x032\",\"id\":32,\"title\":\"方莜莜和安念的故事（三十一）\",\"kind\":\"fang\",\"volume\":null,\"start\":2740,\"end\":2742,\"summary\":\"杨豪伟接来同事林蓉共餐，二人关系接近确定但尚未说破；他重感情而慎作承诺，莜莜也珍惜这段兄妹关系。告别后安念带她回家，母亲热烈拥抱儿子、以朋友身份接纳她，触发她对亲情的失落。为隐瞒恋爱她先松开牵手，相亲背后的排斥因而更刺痛。\",\"turn\":\"外人式的友好无法替代伴侣认可，家庭障碍清晰显露。\",\"time\":\"返乡日下午四点多\",\"people\":[\"方莜莜\",\"安念\",\"杨豪伟\",\"林蓉\",\"安念母亲\"],\"objects\":[\"桑塔纳\"],\"places\":[\"餐馆\",\"安念家\"]},{\"key\":\"x033\",\"id\":33,\"title\":\"方莜莜和安念的故事（三十二）\",\"kind\":\"fang\",\"volume\":null,\"start\":2743,\"end\":2746,\"summary\":\"安念父母接受莜莜作朋友，却曾明确反对她成为伴侣。母亲安排翌日相亲，他答应见面但保留不满意的余地；莜莜在厨房帮忙，强作正常。晚饭后她主动同意住宾馆，避免揭穿恋情。两人互知深爱，却都不敢迫使选择，在彼此体谅中累积无法承受的痛苦。\",\"turn\":\"同居恋人被迫分住，莜莜的退让与安念的回避进入危机。\",\"time\":\"返乡日晚饭后\",\"people\":[\"方莜莜\",\"安念\",\"安念母亲\",\"安念父亲\"],\"objects\":[\"热茶\",\"漫画书\",\"手机\"],\"places\":[\"安念家\",\"街道\",\"宾馆\"]},{\"key\":\"x034\",\"id\":34,\"title\":\"终章（上）\",\"kind\":\"fang\",\"volume\":null,\"start\":2747,\"end\":2750,\"summary\":\"独处宾馆的莜莜终于哭出来，反复质问自己究竟是体谅安念，还是以牺牲换他选择自己。她向橘子求助，对方责备安念并鼓励主动争取幸福，却使她重新想起早先不强求的决定。她宣称已明白怎样选择，未说明具体计划便挂电话，留下橘子不安。\",\"turn\":\"倾诉未解除危机，莜莜隐藏的决断成为终章悬念。\",\"time\":\"返乡日深夜\",\"people\":[\"方莜莜\",\"安念\",\"橘子\"],\"objects\":[\"房卡\",\"行李\",\"手机\",\"白色大衣\"],\"places\":[\"宾馆\"]},{\"key\":\"x035\",\"id\":35,\"title\":\"终章（下）\",\"kind\":\"fang\",\"volume\":null,\"start\":2751,\"end\":2756,\"summary\":\"莜莜陪安念与娴静爱书的苏凝相亲，认可她能陪伴安念，晚间独自离馆自杀未遂。橘子察觉危机赶来救援，两人都被送医，数日后出院。事情曝光后，橘子与安念绝交，杨豪伟阻止其再纠缠，莜莜始终拒见安念并退出他的生活。苏凝继续陪伴他，他逐渐接受分离却难以忘怀；两段新恋情均未明确成立。\",\"turn\":\"莜莜和橘子存活；莜莜与安念彻底分离，安念始终记得她。\",\"time\":\"相亲日及其后\",\"people\":[\"方莜莜\",\"安念\",\"橘子\",\"苏凝\",\"杨豪伟\",\"安念父母\",\"宾馆前台\",\"保洁阿姨\",\"路人\",\"急救人员\"],\"objects\":[\"手机\",\"双人房卡\",\"《明朝那些事儿》\",\"玉质发饰\",\"行李\"],\"places\":[\"宾馆\",\"相亲酒店\",\"私人书屋\",\"步行街\",\"沿河路石桥\",\"医院\"]},{\"key\":\"x036\",\"id\":36,\"title\":\"1 · 胡玉牛还在\",\"kind\":\"if\",\"volume\":null,\"start\":2758,\"end\":2761,\"summary\":\"IF从胡玉牛自杀未遂的分岔开始：张思凡用备用钥匙开门，朋友及时呼叫急救使他获救。醒来见众人守夜，他决定珍惜生命、停止转变，向父母承认旧事、与柳韵和好并承诺结婚。他也愿承担与天语遥冲突的责任，不再报复，期待对方放下仇恨。\",\"turn\":\"假设分支中胡玉牛获救，重新选择生活方向。\",\"time\":\"IF在胡玉牛自杀事件处分岔\",\"people\":[\"胡玉牛\",\"张思凡\",\"苏雨晴\",\"林夕晨\",\"方莜莜\",\"柳韵\",\"胡玉牛父母\",\"医生\"],\"objects\":[\"备用钥匙\",\"旧药物\"],\"places\":[\"胡玉牛房间\",\"医院\",\"父母家\",\"柳韵家\"]},{\"key\":\"x037\",\"id\":37,\"title\":\"2 · 没有仇恨\",\"kind\":\"if\",\"volume\":null,\"start\":2762,\"end\":2765,\"summary\":\"IF中天语遥向夏归月坦白报复胡玉牛的计划，在她劝慰下意识到复仇并不能恢复过去，也无法给予未来。夏归月用陪伴、衣服、逛街和共同上学的愿景拉她走出封闭，她答应不再伤害自己，开始期待日常。她仍未直接向胡玉牛道歉，却已不愿对方因自己而死。\",\"turn\":\"仇恨链在假设分支中被主动中止，天语遥恢复生活期待。\",\"time\":\"IF初春\",\"people\":[\"天语遥\",\"夏归月\",\"胡玉牛\"],\"objects\":[\"新裙子\",\"梅花糕\",\"黄色兔子\"],\"places\":[\"夏归月家\",\"街道\",\"宠物店\"]},{\"key\":\"x038\",\"id\":38,\"title\":\"3 · 不过从头再来\",\"kind\":\"if\",\"volume\":null,\"start\":2766,\"end\":2769,\"summary\":\"IF中张思凡被孙昊抛弃后回到小城市，朋友分摊租金保存集装箱房，还买电瓶车方便来往。雨晴、夕晨、莜莜、胡玉牛与柳韵迎接她，她在失恋后仍选择继续女性生活。众人用玩闹陪她承受伤痛，夕晨画出小恶魔形象，旧共同体得以继续完整存在。\",\"turn\":\"失恋导致返回朋友身边，未走向正文恢复男性生活的结局。\",\"time\":\"IF张思凡离开一个多月后\",\"people\":[\"张思凡\",\"孙昊\",\"方莜莜\",\"苏雨晴\",\"林夕晨\",\"胡玉牛\",\"柳韵\",\"流浪猫狗\"],\"objects\":[\"电瓶车\",\"小恶魔画像\"],\"places\":[\"合租房\",\"郊区集装箱房\"]},{\"key\":\"x039\",\"id\":39,\"title\":\"4 · 夕子姐姐，我和你一起回去\",\"kind\":\"if\",\"volume\":null,\"start\":2770,\"end\":2773,\"summary\":\"IF里林夕晨年前返乡坦白身份，苏雨晴坚持同行，在雪中抵达北方山村。母亲认出她后惊慌争论，父亲发现其女性装束便施暴，拒听检查说明。雨晴带她逃到村口，拦住她再次回屋；两人的共同面对改变了夕晨独自承受冲突的处境，但危险仍未结束。\",\"turn\":\"雨晴陪同返乡成为夕晨命运改变的关键分岔。\",\"time\":\"IF年前冬季\",\"people\":[\"林夕晨\",\"苏雨晴\",\"林夕晨母亲\",\"林夕晨父亲\",\"张思凡\",\"方莜莜\"],\"objects\":[\"大衣\",\"行李\"],\"places\":[\"火车\",\"北方山村\",\"林夕晨家\"]},{\"key\":\"x040\",\"id\":40,\"title\":\"5 · 不要放弃\",\"kind\":\"if\",\"volume\":null,\"start\":2774,\"end\":2777,\"summary\":\"IF中父亲追至村口继续威胁夕晨，母亲激烈反抗，杀死丈夫后自杀；雨晴受惊心脏病发被送医，夕晨幸存并守在床边。警方查明与两人无关，雨晴出院后陪夕晨返回小城市。夕晨决定长住朋友身边，再次梳好双马尾，成为勉强重返生活的微小信号。\",\"turn\":\"夕晨在假设线存活，但父母仍死亡；不能概括为IF没有任何人死亡。\",\"time\":\"IF返乡冲突至数日后\",\"people\":[\"林夕晨\",\"苏雨晴\",\"林夕晨父亲\",\"林夕晨母亲\",\"警方\",\"医护人员\"],\"objects\":[\"发绳\",\"梳子\"],\"places\":[\"北方山村\",\"医院\",\"返程火车\",\"小城市\"]},{\"key\":\"x041\",\"id\":41,\"title\":\"6 · 我会娶你\",\"kind\":\"if\",\"volume\":null,\"start\":2778,\"end\":2781,\"summary\":\"IF中夕晨完成身体相关手术，并把母亲所取小名夕儿交给雨晴使用。雨晴担心身份理想与共同生育冲突，夕晨安排辅助生育，随后怀孕，孩子拟名苏慕夕。胡玉牛武馆兴旺，夏归月代天语遥来信道歉并告知二人赴外地上大学；雨晴父母寄百万银行卡支持手术、盼见女儿与孙辈。\",\"turn\":\"两位母亲与亲生孩子的家庭成立；具体医疗设定仅为小说叙述。\",\"time\":\"IF春节后、怀孕期\",\"people\":[\"林夕晨\",\"苏雨晴\",\"苏慕夕\",\"张思凡\",\"方莜莜\",\"胡玉牛\",\"夏归月\",\"天语遥\",\"苏雨晴父母\",\"护士\"],\"objects\":[\"银行卡\",\"书信\",\"发绳\"],\"places\":[\"医院\",\"合租房\",\"武道馆\"]},{\"key\":\"x042\",\"id\":42,\"title\":\"7 · 不准走\",\"kind\":\"if\",\"volume\":null,\"start\":2782,\"end\":2785,\"summary\":\"IF中安念在父母压力下提出分手，莜莜在钱塘江边叫住他，使两人动摇于分离与私奔之间。突然获知安念父母车祸，二人赶医仍未挽回。莜莜陪他处理葬礼和哀痛，之后他卖掉杭州房产，与她搬到小城市海边，决定同雨晴夕晨一起举行婚礼。\",\"turn\":\"父母车祸死亡解除外部阻碍，安念与莜莜在悲痛中继续相伴。\",\"time\":\"IF共同婚礼前不足两个月\",\"people\":[\"方莜莜\",\"安念\",\"安念父母\",\"安念舅舅\",\"医生\"],\"objects\":[\"手机\",\"遗产\",\"杭州房屋\"],\"places\":[\"钱塘江边\",\"市一医院\",\"半山公墓\",\"杭州\",\"小城市海景房\"]},{\"key\":\"x043\",\"id\":43,\"title\":\"8 · 至少，大家都还在\",\"kind\":\"if\",\"volume\":null,\"start\":2786,\"end\":2789,\"summary\":\"IF中莫空担任雨晴与家人的信使，提供手续；雨晴资助张思凡一起赴泰手术，莜莜自行决定不做。夕晨生下女儿苏慕夕，雨晴父母带三岁苏冬凌探望并帮办户籍。集装箱原址改建别墅后，两对新人同日婚礼，张思凡主持、莫空扮神父，曲奇咖啡送花，天语遥夏归月也到场，众人合影结束假设线。\",\"turn\":\"两对新人团聚、核心朋友与宠物在场；此幸福结局不可覆盖正文。\",\"time\":\"IF产女半个月后举行婚礼\",\"people\":[\"苏雨晴\",\"林夕晨\",\"苏慕夕\",\"方莜莜\",\"安念\",\"张思凡\",\"莫空\",\"曲奇\",\"咖啡\",\"胡玉牛\",\"柳韵\",\"天语遥\",\"夏归月\",\"苏雨晴父母\",\"苏冬凌\",\"苏雨晴的大舅\",\"冉空城\",\"三位表哥\"],\"objects\":[\"身份证\",\"婚纱\",\"婚戒\",\"圣经\",\"花篮\",\"榛果巧克力\",\"合影相机\"],\"places\":[\"泰国\",\"小城市\",\"集装箱原址别墅\"]},{\"key\":\"x044\",\"id\":44,\"title\":\"1 · 萌芽\",\"kind\":\"prequel\",\"volume\":null,\"start\":2791,\"end\":2794,\"summary\":\"前传从幼儿园讲雨晴喜欢与女孩相处、留长发，却在被父母剪短后遭同伴疏远，开始模仿男孩。母亲以男子汉不能哭等要求塑造行为，也把药片说成吃了会变女孩，使她暗记在心。升初中后她用好成绩与韩星海报争取蓄发空间，生物课引发进一步搜索，身份愿望从模糊感受转向主动探索。\",\"turn\":\"前传补足隐瞒与取悦父母的习惯来源，药物启蒙属人物记忆与小说说法。\",\"time\":\"幼儿园至初一下学期\",\"people\":[\"苏雨晴\",\"苏雨晴的母亲\",\"苏榕槐\",\"理发师\",\"幼儿园同伴\",\"生物老师\"],\"objects\":[\"玩具汽车\",\"母亲药片\",\"韩星海报\",\"电脑\"],\"places\":[\"幼儿园\",\"家\",\"小学\",\"初中\"]},{\"key\":\"x045\",\"id\":45,\"title\":\"2 · 少年宫\",\"kind\":\"prequel\",\"volume\":null,\"start\":2795,\"end\":2798,\"summary\":\"少年宫素描课里雨晴借画画想象女孩生活，仍担心父亲要求剪头发。母亲出差，父亲来接，罕见地开玩笑并按母亲嘱托给钱喂鸽子。两人吃披萨、逛超市，父亲虽仍强调男子汉，却宽容她的喜好，还比说定的数量多换娃娃机硬币，呈现严肃外表下不善表达的疼爱。\",\"turn\":\"补充父女关系中原有温情，为后来的冲突与和解增加层次。\",\"time\":\"童年一个周日\",\"people\":[\"苏雨晴\",\"苏榕槐\",\"苏雨晴的母亲\",\"美术老师\",\"服务员\"],\"objects\":[\"铅笔素描\",\"猫耳少女画\",\"玉米粒\",\"苦咖啡\",\"娃娃机硬币\"],\"places\":[\"少年宫\",\"鸽子场\",\"和平广场\",\"披萨店\",\"超市\"]},{\"key\":\"x046\",\"id\":46,\"title\":\"3 · 巧克力派\",\"kind\":\"prequel\",\"volume\":null,\"start\":2799,\"end\":2802,\"summary\":\"重读初二的冬日，冉空城让雨晴坐她喜欢的窗边，她则帮他整理抽屉，分享吃不完的饭菜。他随口称赞贤惠，她内心高兴又害怕身份被发现、失去唯一朋友。午休冉空城悄悄带回巧克力派，坚持分半；普通零食因被人记挂而让她感动，成为早期暗恋的温暖记忆。\",\"turn\":\"相互照顾孕育依恋，与周围同伴的疏远形成并置。\",\"time\":\"重读初二的冬天\",\"people\":[\"苏雨晴\",\"冉空城\",\"同班学生\",\"手工老师\"],\"objects\":[\"易拉罐笔筒\",\"玩具手枪\",\"饭盒\",\"巧克力派\"],\"places\":[\"初中教室窗边\"]},{\"key\":\"x047\",\"id\":47,\"title\":\"4 · 人妖表演\",\"kind\":\"prequel\",\"volume\":null,\"start\":2803,\"end\":2806,\"summary\":\"暑假随父母赴泰，雨晴起初好奇跨性别表演者，观演却目睹失误者受辱和挨打，父亲的贬斥也令她心痛。此后到双龙寺，她从高档饰品里选中最普通的一串佛珠，母亲为她买下。她把朴素理解为平淡生活的寄托，信仰因而与身份焦虑和求安稳的愿望联系起来。\",\"turn\":\"佛珠获得最初出处；文中关于群体、历史与医疗的概括不能视为事实。\",\"time\":\"童年或少年暑假\",\"people\":[\"苏雨晴\",\"苏雨晴父母\",\"受伤表演者\",\"管理员\",\"卖饰品老");
